skip_unless_full_tests()

# Rows of the SymPy printing test suites (sympy/printing/tests/test_latex.py
# and sympy/printing/pretty/tests/test_pretty.py) whose output this port
# reproduces; the expected strings are the SymPy outputs with newlines
# written as \n.

.pf_out <- function(v) {
  if (is.logical(v) && length(v) == 1L) return(if (v) "True" else "False")
  if (!is.character(v)) v <- sstr(v)
  gsub("\n", "\\n", gsub("**", "^", v, fixed = TRUE), fixed = TRUE)
}

test_that("latex test_unevaluated_numeric_ratio", {
  for (.n in c("x", "y", "z", "t", "w", "a", "b", "c", "s", "p")) assign(.n, Symbol(.n))
  for (.n in c("k", "m", "n")) assign(.n, Symbol(.n, integer = TRUE))
  mu <- Symbol("mu"); tau <- Symbol("tau")
  f <- Function("f"); g <- Function("g")
  expect_identical(.pf_out(latex(Pow(1L, -1L, evaluate = FALSE))), "\\frac{1}{1}")
  expect_identical(.pf_out(latex(Mul(1L, Rational(1L, 2L), evaluate = FALSE))), "1 \\cdot \\frac{1}{2}")
  expect_identical(.pf_out(latex(Mul(1L, Symbol("x"), evaluate = FALSE))), "1 x")
})

test_that("latex test_latex_basic", {
  for (.n in c("x", "y", "z", "t", "w", "a", "b", "c", "s", "p")) assign(.n, Symbol(.n))
  for (.n in c("k", "m", "n")) assign(.n, Symbol(.n, integer = TRUE))
  mu <- Symbol("mu"); tau <- Symbol("tau")
  f <- Function("f"); g <- Function("g")
  expect_identical(.pf_out(latex(1L + x)), "x + 1")
  expect_identical(.pf_out(latex(x ^ 2L)), "x^{2}")
  expect_identical(.pf_out(latex(x ^ (1L + x))), "x^{x + 1}")
  expect_identical(.pf_out(latex((((x ^ 3L) + x) + 1L) + (x ^ 2L))), "x^{3} + x^{2} + x + 1")
  expect_identical(.pf_out(latex((2L * x) * y)), "2 x y")
  expect_identical(.pf_out(latex((2L * x) * y, mul_symbol = "dot")), "2 \\cdot x \\cdot y")
  expect_identical(.pf_out(latex((3L * (x ^ 2L)) * y, mul_symbol = "\\,")), "3\\,x^{2}\\,y")
  expect_identical(.pf_out(latex(Float(1.5) * (3L ^ x), mul_symbol = "\\,")), "1.5 \\cdot 3^{x}")
  expect_identical(.pf_out(latex(x ^ (S_Half ^ 5L))), "\\sqrt[32]{x}")
  expect_identical(.pf_out(latex(Mul(S_Half, x ^ 2L, -5L, evaluate = FALSE))), "\\frac{1}{2} x^{2} \\left(-5\\right)")
  expect_identical(.pf_out(latex(Mul(S_Half, x ^ 2L, 5L, evaluate = FALSE))), "\\frac{1}{2} x^{2} \\cdot 5")
  expect_identical(.pf_out(latex(Mul(-5L, -5L, evaluate = FALSE))), "\\left(-5\\right) \\left(-5\\right)")
  expect_identical(.pf_out(latex(Mul(5L, -5L, evaluate = FALSE))), "5 \\left(-5\\right)")
  expect_identical(.pf_out(latex(Mul(S_Half, -5L, S_Half, evaluate = FALSE))), "\\frac{1}{2} \\left(-5\\right) \\frac{1}{2}")
  expect_identical(.pf_out(latex(Mul(5L, S_I, 5L, evaluate = FALSE))), "5 i 5")
  expect_identical(.pf_out(latex(Mul(5L, S_I, -5L, evaluate = FALSE))), "5 i \\left(-5\\right)")
  expect_identical(.pf_out(latex(Mul(Pow(x, 2L), (S_Half * x) + 1L))), "x^{2} \\left(\\frac{x}{2} + 1\\right)")
  expect_identical(.pf_out(latex(Mul(Pow(x, 3L), (Rational(2L, 3L) * x) + 1L))), "x^{3} \\left(\\frac{2 x}{3} + 1\\right)")
  expect_identical(.pf_out(latex(Mul(Pow(x, 11L), (2L * x) + 1L))), "x^{11} \\left(2 x + 1\\right)")
  expect_identical(.pf_out(latex(Mul(0L, 1L, evaluate = FALSE))), "0 \\cdot 1")
  expect_identical(.pf_out(latex(Mul(1L, 0L, evaluate = FALSE))), "1 \\cdot 0")
  expect_identical(.pf_out(latex(Mul(1L, 1L, evaluate = FALSE))), "1 \\cdot 1")
  expect_identical(.pf_out(latex(Mul(-1L, 1L, evaluate = FALSE))), "\\left(-1\\right) 1")
  expect_identical(.pf_out(latex(Mul(1L, 1L, 1L, evaluate = FALSE))), "1 \\cdot 1 \\cdot 1")
  expect_identical(.pf_out(latex(Mul(1L, 2L, evaluate = FALSE))), "1 \\cdot 2")
  expect_identical(.pf_out(latex(Mul(1L, S_Half, evaluate = FALSE))), "1 \\cdot \\frac{1}{2}")
  expect_identical(.pf_out(latex(Mul(1L, 1L, S_Half, evaluate = FALSE))), "1 \\cdot 1 \\cdot \\frac{1}{2}")
  expect_identical(.pf_out(latex(Mul(1L, 1L, 2L, 3L, x, evaluate = FALSE))), "1 \\cdot 1 \\cdot 2 \\cdot 3 x")
  expect_identical(.pf_out(latex(Mul(1L, -1L, evaluate = FALSE))), "1 \\left(-1\\right)")
  expect_identical(.pf_out(latex(Mul(4L, 3L, 2L, 1L, 0L, y, x, evaluate = FALSE))), "4 \\cdot 3 \\cdot 2 \\cdot 1 \\cdot 0 y x")
  expect_identical(.pf_out(latex(Mul(4L, 3L, 2L, 1L + z, 0L, y, x, evaluate = FALSE))), "4 \\cdot 3 \\cdot 2 \\left(z + 1\\right) 0 y x")
  expect_identical(.pf_out(latex(Mul(Rational(2L, 3L), Rational(5L, 7L), evaluate = FALSE))), "\\frac{2}{3} \\cdot \\frac{5}{7}")
  expect_identical(.pf_out(latex(1L / x)), "\\frac{1}{x}")
  expect_identical(.pf_out(latex(1L / x, fold_short_frac = TRUE)), "1 / x")
  expect_identical(.pf_out(latex((x + y) ^ (-1L), fold_short_frac = TRUE)), "1 / \\left(x + y\\right)")
  expect_identical(.pf_out(latex((-S(3L)) / 2L)), "- \\frac{3}{2}")
  expect_identical(.pf_out(latex((-S(3L)) / 2L, fold_short_frac = TRUE)), "- 3 / 2")
  expect_identical(.pf_out(latex(1L / (x ^ 2L))), "\\frac{1}{x^{2}}")
  expect_identical(.pf_out(latex((1L / (x + y)) / 2L)), "\\frac{1}{2 \\left(x + y\\right)}")
  expect_identical(.pf_out(latex(x / 2L)), "\\frac{x}{2}")
  expect_identical(.pf_out(latex(x / 2L, fold_short_frac = TRUE)), "x / 2")
  expect_identical(.pf_out(latex((x + y) / (2L * x))), "\\frac{x + y}{2 x}")
  expect_identical(.pf_out(latex((x + y) / (2L * x), fold_short_frac = TRUE)), "\\left(x + y\\right) / 2 x")
  expect_identical(.pf_out(latex((x + y) / (2L * x), long_frac_ratio = 0L)), "\\frac{1}{2 x} \\left(x + y\\right)")
  expect_identical(.pf_out(latex((x + y) / x)), "\\frac{x + y}{x}")
  expect_identical(.pf_out(latex((x + y) / x, long_frac_ratio = 3L)), "\\frac{x + y}{x}")
  expect_identical(.pf_out(latex(((2L * sqrt(Integer(2L))) * x) / 3L)), "\\frac{2 \\sqrt{2} x}{3}")
  expect_identical(.pf_out(latex(((2L * sqrt(Integer(2L))) * x) / 3L, long_frac_ratio = 2L)), "\\frac{2 x}{3} \\sqrt{2}")
  expect_identical(.pf_out(latex(sym_binomial(x, y))), "{\\binom{x}{y}}")
  try(x_star <- Symbol("x^*"), silent = TRUE)
  try(f <- Function("f"), silent = TRUE)
  expect_identical(.pf_out(latex(x_star ^ 2L)), "\\left(x^{*}\\right)^{2}")
  expect_identical(.pf_out(latex(x_star ^ 2L, parenthesize_super = FALSE)), "{x^{*}}^{2}")
  expect_identical(.pf_out(latex(Derivative(f(x_star), x_star, 2L))), "\\frac{d^{2}}{d \\left(x^{*}\\right)^{2}} f{\\left(x^{*} \\right)}")
  expect_identical(.pf_out(latex(Derivative(f(x_star), x_star, 2L), parenthesize_super = FALSE)), "\\frac{d^{2}}{d {x^{*}}^{2}} f{\\left(x^{*} \\right)}")
  expect_identical(.pf_out(latex(x ^ (x ^ x))), "x^{\\left(x^{x}\\right)}")
  expect_identical(.pf_out(latex((x ^ x) ^ (x ^ x))), "\\left(x^{x}\\right)^{\\left(x^{x}\\right)}")
  expect_identical(.pf_out(latex((2L * Integral(x, x)) / 3L)), "\\frac{2 \\int x\\, dx}{3}")
  expect_identical(.pf_out(latex((2L * Integral(x, x)) / 3L, fold_short_frac = TRUE)), "\\left(2 \\int x\\, dx\\right) / 3")
  expect_identical(.pf_out(latex(sqrt(x))), "\\sqrt{x}")
  expect_identical(.pf_out(latex(x ^ Rational(1L, 3L))), "\\sqrt[3]{x}")
  expect_identical(.pf_out(latex(x ^ Rational(1L, 3L), root_notation = FALSE)), "x^{\\frac{1}{3}}")
  expect_identical(.pf_out(latex(sqrt(x) ^ 3L)), "x^{\\frac{3}{2}}")
  expect_identical(.pf_out(latex(sqrt(x), itex = TRUE)), "\\sqrt{x}")
  expect_identical(.pf_out(latex(x ^ Rational(1L, 3L), itex = TRUE)), "\\root{3}{x}")
  expect_identical(.pf_out(latex(sqrt(x) ^ 3L, itex = TRUE)), "x^{\\frac{3}{2}}")
  expect_identical(.pf_out(latex(x ^ Rational(3L, 4L))), "x^{\\frac{3}{4}}")
  expect_identical(.pf_out(latex(x ^ Rational(3L, 4L), fold_frac_powers = TRUE)), "x^{3/4}")
  expect_identical(.pf_out(latex((x + 1L) ^ Rational(3L, 4L))), "\\left(x + 1\\right)^{\\frac{3}{4}}")
  expect_identical(.pf_out(latex((x + 1L) ^ Rational(3L, 4L), fold_frac_powers = TRUE)), "\\left(x + 1\\right)^{3/4}")
  expect_identical(.pf_out(latex(AlgebraicNumber(sqrt(Integer(2L))))), "\\sqrt{2}")
  expect_identical(.pf_out(latex(AlgebraicNumber(sqrt(Integer(2L)), list(3L, -7L)))), "-7 + 3 \\sqrt{2}")
  expect_identical(.pf_out(latex(AlgebraicNumber(sqrt(Integer(2L)), alias = "alpha"))), "\\alpha")
  expect_identical(.pf_out(latex(AlgebraicNumber(sqrt(Integer(2L)), list(3L, -7L), alias = "alpha"))), "3 \\alpha - 7")
  expect_identical(.pf_out(latex(AlgebraicNumber(2L ^ (S(1L) / 3L), list(1L, 3L, -7L), alias = "beta"))), "\\beta^{2} + 3 \\beta - 7")
})

test_that("latex test_latex_builtins", {
  for (.n in c("x", "y", "z", "t", "w", "a", "b", "c", "s", "p")) assign(.n, Symbol(.n))
  for (.n in c("k", "m", "n")) assign(.n, Symbol(.n, integer = TRUE))
  mu <- Symbol("mu"); tau <- Symbol("tau")
  f <- Function("f"); g <- Function("g")
  expect_identical(.pf_out(latex(TRUE)), "\\text{True}")
  expect_identical(.pf_out(latex(FALSE)), "\\text{False}")
  expect_identical(.pf_out(latex(NULL)), "\\text{None}")
  expect_identical(.pf_out(latex(S_true)), "\\text{True}")
  expect_identical(.pf_out(latex(S_false)), "\\text{False}")
})

test_that("latex test_latex_SingularityFunction", {
  for (.n in c("x", "y", "z", "t", "w", "a", "b", "c", "s", "p")) assign(.n, Symbol(.n))
  for (.n in c("k", "m", "n")) assign(.n, Symbol(.n, integer = TRUE))
  mu <- Symbol("mu"); tau <- Symbol("tau")
  f <- Function("f"); g <- Function("g")
  expect_identical(.pf_out(latex(SingularityFunction(x, 4L, 5L))), "{\\left\\langle x - 4 \\right\\rangle}^{5}")
  expect_identical(.pf_out(latex(SingularityFunction(x, -3L, 4L))), "{\\left\\langle x + 3 \\right\\rangle}^{4}")
  expect_identical(.pf_out(latex(SingularityFunction(x, 0L, 4L))), "{\\left\\langle x \\right\\rangle}^{4}")
  expect_identical(.pf_out(latex(SingularityFunction(x, a, n))), "{\\left\\langle - a + x \\right\\rangle}^{n}")
  expect_identical(.pf_out(latex(SingularityFunction(x, 4L, -2L))), "{\\left\\langle x - 4 \\right\\rangle}^{-2}")
  expect_identical(.pf_out(latex(SingularityFunction(x, 4L, -1L))), "{\\left\\langle x - 4 \\right\\rangle}^{-1}")
  expect_identical(.pf_out(latex(SingularityFunction(x, 4L, 5L) ^ 3L)), "{\\left({\\langle x - 4 \\rangle}^{5}\\right)}^{3}")
  expect_identical(.pf_out(latex(SingularityFunction(x, -3L, 4L) ^ 3L)), "{\\left({\\langle x + 3 \\rangle}^{4}\\right)}^{3}")
  expect_identical(.pf_out(latex(SingularityFunction(x, 0L, 4L) ^ 3L)), "{\\left({\\langle x \\rangle}^{4}\\right)}^{3}")
  expect_identical(.pf_out(latex(SingularityFunction(x, a, n) ^ 3L)), "{\\left({\\langle - a + x \\rangle}^{n}\\right)}^{3}")
  expect_identical(.pf_out(latex(SingularityFunction(x, 4L, -2L) ^ 3L)), "{\\left({\\langle x - 4 \\rangle}^{-2}\\right)}^{3}")
  expect_identical(.pf_out(latex((SingularityFunction(x, 4L, -1L) ^ 3L) ^ 3L)), "{\\left({\\langle x - 4 \\rangle}^{-1}\\right)}^{9}")
})

test_that("latex test_latex_cycle", {
  for (.n in c("x", "y", "z", "t", "w", "a", "b", "c", "s", "p")) assign(.n, Symbol(.n))
  for (.n in c("k", "m", "n")) assign(.n, Symbol(.n, integer = TRUE))
  mu <- Symbol("mu"); tau <- Symbol("tau")
  f <- Function("f"); g <- Function("g")
  expect_identical(.pf_out(latex(Cycle(1L, 2L, 4L))), "\\left( 1\\; 2\\; 4\\right)")
  expect_identical(.pf_out(latex(Cycle())), "\\left( \\right)")
})

test_that("latex test_latex_permutation", {
  for (.n in c("x", "y", "z", "t", "w", "a", "b", "c", "s", "p")) assign(.n, Symbol(.n))
  for (.n in c("k", "m", "n")) assign(.n, Symbol(.n, integer = TRUE))
  mu <- Symbol("mu"); tau <- Symbol("tau")
  f <- Function("f"); g <- Function("g")
  expect_identical(.pf_out(latex(Permutation(1L, 2L, 4L))), "\\left( 1\\; 2\\; 4\\right)")
  expect_identical(.pf_out(latex(Permutation())), "\\left( \\right)")
  expect_identical(.pf_out(latex(Permutation(2L, 4L) * Permutation(5L))), "\\left( 2\\; 4\\right)\\left( 5\\right)")
  expect_identical(.pf_out(latex(Permutation(5L))), "\\left( 5\\right)")
  expect_identical(.pf_out(latex(Permutation(0L, 1L), perm_cyclic = FALSE)), "\\begin{pmatrix} 0 & 1 \\\\ 1 & 0 \\end{pmatrix}")
  expect_identical(.pf_out(latex(Permutation(), perm_cyclic = FALSE)), "\\left( \\right)")
})

test_that("latex test_latex_Float", {
  for (.n in c("x", "y", "z", "t", "w", "a", "b", "c", "s", "p")) assign(.n, Symbol(.n))
  for (.n in c("k", "m", "n")) assign(.n, Symbol(.n, integer = TRUE))
  mu <- Symbol("mu"); tau <- Symbol("tau")
  f <- Function("f"); g <- Function("g")
  expect_identical(.pf_out(latex(Float(Float(1e+100)))), "1.0 \\cdot 10^{100}")
  expect_identical(.pf_out(latex(Float(Float(1e-100)))), "1.0 \\cdot 10^{-100}")
  expect_identical(.pf_out(latex(Float(Float(1e-100)), mul_symbol = "times")), "1.0 \\times 10^{-100}")
  expect_identical(.pf_out(latex(Float("10000.0"), full_prec = FALSE, min = -2L, max = 2L)), "1.0 \\cdot 10^{4}")
  expect_identical(.pf_out(latex(Float("10000.0"), full_prec = FALSE, min = -2L, max = 4L)), "1.0 \\cdot 10^{4}")
  expect_identical(.pf_out(latex(Float("10000.0"), full_prec = FALSE, min = -2L, max = 5L)), "10000.0")
  expect_identical(.pf_out(latex(Float("0.099999"), full_prec = TRUE, min = -2L, max = 5L)), "9.99990000000000 \\cdot 10^{-2}")
})

test_that("latex test_latex_functions", {
  for (.n in c("x", "y", "z", "t", "w", "a", "b", "c", "s", "p")) assign(.n, Symbol(.n))
  for (.n in c("k", "m", "n")) assign(.n, Symbol(.n, integer = TRUE))
  mu <- Symbol("mu"); tau <- Symbol("tau")
  f <- Function("f"); g <- Function("g")
  expect_identical(.pf_out(latex(exp(x))), "e^{x}")
  expect_identical(.pf_out(latex(exp(Integer(1L)) + exp(Integer(2L)))), "e + e^{2}")
  f <- Function("f")
  expect_identical(.pf_out(latex(f(x))), "f{\\left(x \\right)}")
  expect_identical(.pf_out(latex(f)), "f")
  g <- Function("g")
  expect_identical(.pf_out(latex(g(x, y))), "g{\\left(x,y \\right)}")
  expect_identical(.pf_out(latex(g)), "g")
  h <- Function("h")
  expect_identical(.pf_out(latex(h(x, y, z))), "h{\\left(x,y,z \\right)}")
  expect_identical(.pf_out(latex(h)), "h")
  Li <- Function("Li")
  expect_identical(.pf_out(latex(Li)), "\\operatorname{Li}")
  expect_identical(.pf_out(latex(Li(x))), "\\operatorname{Li}{\\left(x \\right)}")
  mybeta <- Function("beta")
  expect_identical(.pf_out(latex(sym_beta(x, y))), "\\operatorname{B}\\left(x, y\\right)")
  expect_identical(.pf_out(latex(sym_beta(x, y) ^ 2L)), "\\operatorname{B}^{2}\\left(x, y\\right)")
  expect_identical(.pf_out(latex(mybeta)), "\\beta")
  g <- Function("gamma")
  expect_identical(.pf_out(latex(g)), "\\gamma")
  a_1 <- Function("a_1")
  expect_identical(.pf_out(latex(a_1)), "a_{1}")
  expect_identical(.pf_out(latex(a_1(x))), "a_{1}{\\left(x \\right)}")
  expect_identical(.pf_out(latex(Function("a_1"))), "a_{1}")
  expect_identical(.pf_out(latex(Function("ab"))), "\\operatorname{ab}")
  expect_identical(.pf_out(latex(Function("ab1"))), "\\operatorname{ab}_{1}")
  expect_identical(.pf_out(latex(Function("ab12"))), "\\operatorname{ab}_{12}")
  expect_identical(.pf_out(latex(Function("ab_1"))), "\\operatorname{ab}_{1}")
  expect_identical(.pf_out(latex(Function("ab_12"))), "\\operatorname{ab}_{12}")
  expect_identical(.pf_out(latex(Function("ab_c"))), "\\operatorname{ab}_{c}")
  expect_identical(.pf_out(latex(Function("ab_cd"))), "\\operatorname{ab}_{cd}")
  expect_identical(.pf_out(latex(Function("a"))), "a")
  expect_identical(.pf_out(latex(Function("a1"))), "a_{1}")
  expect_identical(.pf_out(latex(Function("a12"))), "a_{12}")
  expect_identical(.pf_out(latex(Function("a_1"))), "a_{1}")
  expect_identical(.pf_out(latex(Function("a_12"))), "a_{12}")
  ab <- Symbol("ab")
  omega1 <- Function("omega1")
  expect_identical(.pf_out(latex(omega1)), "\\omega_{1}")
  expect_identical(.pf_out(latex(omega1(x))), "\\omega_{1}{\\left(x \\right)}")
  expect_identical(.pf_out(latex(sin(x))), "\\sin{\\left(x \\right)}")
  expect_identical(.pf_out(latex(sin(x), fold_func_brackets = TRUE)), "\\sin {x}")
  expect_identical(.pf_out(latex(sin(2L * (x ^ 2L)), fold_func_brackets = TRUE)), "\\sin {2 x^{2}}")
  expect_identical(.pf_out(latex(sin(x ^ 2L), fold_func_brackets = TRUE)), "\\sin {x^{2}}")
  expect_identical(.pf_out(latex(asin(x) ^ 2L)), "\\operatorname{asin}^{2}{\\left(x \\right)}")
  expect_identical(.pf_out(latex(asin(x) ^ 2L, inv_trig_style = "full")), "\\arcsin^{2}{\\left(x \\right)}")
  expect_identical(.pf_out(latex(asin(x) ^ 2L, inv_trig_style = "power")), "\\sin^{-1}{\\left(x \\right)}^{2}")
  expect_identical(.pf_out(latex(asin(x ^ 2L), inv_trig_style = "power", fold_func_brackets = TRUE)), "\\sin^{-1} {x^{2}}")
  expect_identical(.pf_out(latex(acsc(x), inv_trig_style = "full")), "\\operatorname{arccsc}{\\left(x \\right)}")
  expect_identical(.pf_out(latex(asinh(x), inv_trig_style = "full")), "\\operatorname{arsinh}{\\left(x \\right)}")
  expect_identical(.pf_out(latex(sym_factorial(k))), "k!")
  expect_identical(.pf_out(latex(sym_factorial(-k))), "\\left(- k\\right)!")
  expect_identical(.pf_out(latex(sym_factorial(k) ^ 2L)), "k!^{2}")
  expect_identical(.pf_out(latex(subfactorial(k))), "!k")
  expect_identical(.pf_out(latex(subfactorial(-k))), "!\\left(- k\\right)")
  expect_identical(.pf_out(latex(subfactorial(k) ^ 2L)), "\\left(!k\\right)^{2}")
  expect_identical(.pf_out(latex(factorial2(k))), "k!!")
  expect_identical(.pf_out(latex(factorial2(-k))), "\\left(- k\\right)!!")
  expect_identical(.pf_out(latex(factorial2(k) ^ 2L)), "k!!^{2}")
  expect_identical(.pf_out(latex(sym_binomial(2L, k))), "{\\binom{2}{k}}")
  expect_identical(.pf_out(latex(sym_binomial(2L, k) ^ 2L)), "{\\binom{2}{k}}^{2}")
  expect_identical(.pf_out(latex(FallingFactorial(3L, k))), "{\\left(3\\right)}_{k}")
  expect_identical(.pf_out(latex(RisingFactorial(3L, k))), "{3}^{\\left(k\\right)}")
  expect_identical(.pf_out(latex(floor(x))), "\\left\\lfloor{x}\\right\\rfloor")
  expect_identical(.pf_out(latex(ceiling(x))), "\\left\\lceil{x}\\right\\rceil")
  expect_identical(.pf_out(latex(frac(x))), "\\operatorname{frac}{\\left(x\\right)}")
  expect_identical(.pf_out(latex(floor(x) ^ 2L)), "\\left\\lfloor{x}\\right\\rfloor^{2}")
  expect_identical(.pf_out(latex(ceiling(x) ^ 2L)), "\\left\\lceil{x}\\right\\rceil^{2}")
  expect_identical(.pf_out(latex(frac(x) ^ 2L)), "\\operatorname{frac}{\\left(x\\right)}^{2}")
  expect_identical(.pf_out(latex(Min(x, 2L, x ^ 3L))), "\\min\\left(2, x, x^{3}\\right)")
  expect_identical(.pf_out(latex(Min(x, y) ^ 2L)), "\\min\\left(x, y\\right)^{2}")
  expect_identical(.pf_out(latex(Max(x, 2L, x ^ 3L))), "\\max\\left(2, x, x^{3}\\right)")
  expect_identical(.pf_out(latex(Max(x, y) ^ 2L)), "\\max\\left(x, y\\right)^{2}")
  expect_identical(.pf_out(latex(Abs(x))), "\\left|{x}\\right|")
  expect_identical(.pf_out(latex(Abs(x) ^ 2L)), "\\left|{x}\\right|^{2}")
  expect_identical(.pf_out(latex(re(x))), "\\operatorname{re}{\\left(x\\right)}")
  expect_identical(.pf_out(latex(re(x + y))), "\\operatorname{re}{\\left(x\\right)} + \\operatorname{re}{\\left(y\\right)}")
  expect_identical(.pf_out(latex(im(x))), "\\operatorname{im}{\\left(x\\right)}")
  expect_identical(.pf_out(latex(conjugate(x))), "\\overline{x}")
