test_that("latex test_hyper_printing", {
  for (.n in c("x", "y", "z", "t", "w", "a", "b", "c", "s", "p")) assign(.n, Symbol(.n))
  for (.n in c("k", "m", "n")) assign(.n, Symbol(.n, integer = TRUE))
  mu <- Symbol("mu"); tau <- Symbol("tau")
  f <- Function("f"); g <- Function("g")
  expect_identical(.pf_out(latex(meijerg(Tuple(S_Pi, S_Pi, x), Tuple(1L), list(0L, 1L), Tuple(1L, 2L, 3L / S_Pi), z))), "{G_{4, 5}^{2, 3}\\left(\\begin{matrix} \\pi, \\pi, x & 1 \\\\0, 1 & 1, 2, \\frac{3}{\\pi} \\end{matrix} \\middle| {z} \\right)}")
  expect_identical(.pf_out(latex(meijerg(Tuple(), Tuple(1L), list(0L), Tuple(), z))), "{G_{1, 1}^{1, 0}\\left(\\begin{matrix}  & 1 \\\\0 &  \\end{matrix} \\middle| {z} \\right)}")
  expect_identical(.pf_out(latex(hyper(list(x, 2L), list(3L), z))), "{{}_{2}F_{1}\\left(\\begin{matrix} 2, x \\\\ 3 \\end{matrix}\\middle| {z} \\right)}")
  expect_identical(.pf_out(latex(hyper(Tuple(), Tuple(1L), z))), "{{}_{0}F_{1}\\left(\\begin{matrix}  \\\\ 1 \\end{matrix}\\middle| {z} \\right)}")
})

