test_that("latex test_latex_derivatives", {
  for (.n in c("x", "y", "z", "t", "w", "a", "b", "c", "s", "p")) assign(.n, Symbol(.n))
  for (.n in c("k", "m", "n")) assign(.n, Symbol(.n, integer = TRUE))
  mu <- Symbol("mu"); tau <- Symbol("tau")
  f <- Function("f"); g <- Function("g")
  expect_identical(.pf_out(latex(diff(x ^ 3L, x, evaluate = FALSE))), "\\frac{d}{d x} x^{3}")
  expect_identical(.pf_out(latex(diff(sin(x) + (x ^ 2L), x, evaluate = FALSE))), "\\frac{d}{d x} \\left(x^{2} + \\sin{\\left(x \\right)}\\right)")
  expect_identical(.pf_out(latex(diff(diff(sin(x) + (x ^ 2L), x, evaluate = FALSE), evaluate = FALSE))), "\\frac{d^{2}}{d x^{2}} \\left(x^{2} + \\sin{\\left(x \\right)}\\right)")
  expect_identical(.pf_out(latex(diff(diff(diff(sin(x) + (x ^ 2L), x, evaluate = FALSE), evaluate = FALSE), evaluate = FALSE))), "\\frac{d^{3}}{d x^{3}} \\left(x^{2} + \\sin{\\left(x \\right)}\\right)")
  expect_identical(.pf_out(latex(diff(sin(x * y), x, evaluate = FALSE))), "\\frac{\\partial}{\\partial x} \\sin{\\left(x y \\right)}")
  expect_identical(.pf_out(latex(diff(sin(x * y) + (x ^ 2L), x, evaluate = FALSE))), "\\frac{\\partial}{\\partial x} \\left(x^{2} + \\sin{\\left(x y \\right)}\\right)")
  expect_identical(.pf_out(latex(diff(diff(sin(x * y) + (x ^ 2L), x, evaluate = FALSE), x, evaluate = FALSE))), "\\frac{\\partial^{2}}{\\partial x^{2}} \\left(x^{2} + \\sin{\\left(x y \\right)}\\right)")
  expect_identical(.pf_out(latex(diff(diff(diff(sin(x * y) + (x ^ 2L), x, evaluate = FALSE), x, evaluate = FALSE), x, evaluate = FALSE))), "\\frac{\\partial^{3}}{\\partial x^{3}} \\left(x^{2} + \\sin{\\left(x y \\right)}\\right)")
  f <- Function("f")
  expect_identical(.pf_out(latex(diff(diff(f(x, y), x, evaluate = FALSE), y, evaluate = FALSE))), "\\frac{\\partial^{2}}{\\partial y\\partial x} f{\\left(x,y \\right)}")
  expect_identical(.pf_out(latex(diff(diff(diff(f(x, y), x, evaluate = FALSE), x, evaluate = FALSE), y, evaluate = FALSE))), "\\frac{\\partial^{3}}{\\partial y\\partial x^{2}} f{\\left(x,y \\right)}")
  expect_identical(.pf_out(latex(diff(-diff(y ^ 2L, x, evaluate = FALSE), x, evaluate = FALSE))), "\\frac{d}{d x} \\left(- \\frac{d}{d x} y^{2}\\right)")
  expect_identical(.pf_out(latex(diff(diff(-diff(diff(y, x, evaluate = FALSE), x, evaluate = FALSE), x, evaluate = FALSE), x, evaluate = FALSE))), "\\frac{d^{2}}{d x^{2}} \\left(- \\frac{d^{2}}{d x^{2}} y\\right)")
  expect_identical(.pf_out(latex(diff(Integral(exp((-x) * y), list(x, 0L, oo)), y, evaluate = FALSE))), "\\frac{d}{d y} \\int\\limits_{0}^{\\infty} e^{- x y}\\, dx")
  expect_identical(.pf_out(latex(diff(x, x, evaluate = FALSE) ^ 2L)), "\\left(\\frac{d}{d x} x\\right)^{2}")
  expect_identical(.pf_out(latex(diff(f(x), x) ^ 2L)), "\\left(\\frac{d}{d x} f{\\left(x \\right)}\\right)^{2}")
  expect_identical(.pf_out(latex(diff(f(x), list(x, n)))), "\\frac{d^{n}}{d x^{n}} f{\\left(x \\right)}")
  x1 <- Symbol("x1")
  x2 <- Symbol("x2")
  expect_identical(.pf_out(latex(diff(f(x1, x2), x1))), "\\frac{\\partial}{\\partial x_{1}} f{\\left(x_{1},x_{2} \\right)}")
  n1 <- Symbol("n1")
  expect_identical(.pf_out(latex(diff(f(x), list(x, n1)))), "\\frac{d^{n_{1}}}{d x^{n_{1}}} f{\\left(x \\right)}")
  n2 <- Symbol("n2")
  expect_identical(.pf_out(latex(diff(f(x), list(x, Max(n1, n2))))), "\\frac{d^{\\max\\left(n_{1}, n_{2}\\right)}}{d x^{\\max\\left(n_{1}, n_{2}\\right)}} f{\\left(x \\right)}")
  g <- Function("g")
  expect_identical(.pf_out(latex(Derivative(f(x) * g(x), x))), "\\frac{d}{d x} f{\\left(x \\right)} g{\\left(x \\right)}")
  expect_identical(.pf_out(latex(Derivative(f(x) * g(x), x), mul_symbol = "dot")), "\\frac{d}{d x} \\left(f{\\left(x \\right)} \\cdot g{\\left(x \\right)}\\right)")
  expect_identical(.pf_out(latex(diff(f(x), x), diff_operator = "rd")), "\\frac{\\mathrm{d}}{\\mathrm{d} x} f{\\left(x \\right)}")
})

test_that("latex test_latex_integrals", {
  for (.n in c("x", "y", "z", "t", "w", "a", "b", "c", "s", "p")) assign(.n, Symbol(.n))
  for (.n in c("k", "m", "n")) assign(.n, Symbol(.n, integer = TRUE))
  mu <- Symbol("mu"); tau <- Symbol("tau")
  f <- Function("f"); g <- Function("g")
  expect_identical(.pf_out(latex(Integral(log(x), x))), "\\int \\log{\\left(x \\right)}\\, dx")
  expect_identical(.pf_out(latex(Integral(x ^ 2L, list(x, 0L, 1L)))), "\\int\\limits_{0}^{1} x^{2}\\, dx")
  expect_identical(.pf_out(latex(Integral(x ^ 2L, list(x, 10L, 20L)))), "\\int\\limits_{10}^{20} x^{2}\\, dx")
  expect_identical(.pf_out(latex(Integral(y * (x ^ 2L), list(x, 0L, 1L), y))), "\\int\\int\\limits_{0}^{1} x^{2} y\\, dx\\, dy")
  expect_identical(.pf_out(latex(Integral(y * (x ^ 2L), list(x, 0L, 1L), y), mode = "equation*")), "\\begin{equation*}\\int\\int\\limits_{0}^{1} x^{2} y\\, dx\\, dy\\end{equation*}")
  expect_identical(.pf_out(latex(Integral(y * (x ^ 2L), list(x, 0L, 1L), y), mode = "equation*", itex = TRUE)), "$$\\int\\int_{0}^{1} x^{2} y\\, dx\\, dy$$")
  expect_identical(.pf_out(latex(Integral(x, list(x, 0L)))), "\\int\\limits^{0} x\\, dx")
  expect_identical(.pf_out(latex(Integral(x * y, x, y))), "\\iint x y\\, dx\\, dy")
  expect_identical(.pf_out(latex(Integral((x * y) * z, x, y, z))), "\\iiint x y z\\, dx\\, dy\\, dz")
  expect_identical(.pf_out(latex(Integral(((x * y) * z) * t, x, y, z, t))), "\\iiiint t x y z\\, dx\\, dy\\, dz\\, dt")
  expect_identical(.pf_out(latex(Integral(x, x, x, x, x, x, x))), "\\int\\int\\int\\int\\int\\int x\\, dx\\, dx\\, dx\\, dx\\, dx\\, dx")
  expect_identical(.pf_out(latex(Integral(x, x, y, list(z, 0L, 1L)))), "\\int\\limits_{0}^{1}\\int\\int x\\, dx\\, dy\\, dz")
  expect_identical(.pf_out(latex(Integral(-Integral(y ^ 2L, x), x))), "\\int \\left(- \\int y^{2}\\, dx\\right)\\, dx")
  expect_identical(.pf_out(latex(Integral(-Integral(-Integral(y, x), x), x))), "\\int \\left(- \\int \\left(- \\int y\\, dx\\right)\\, dx\\right)\\, dx")
  expect_identical(.pf_out(latex(Integral(z, z) ^ 2L)), "\\left(\\int z\\, dz\\right)^{2}")
  expect_identical(.pf_out(latex(Integral(x + z, z))), "\\int \\left(x + z\\right)\\, dz")
  expect_identical(.pf_out(latex(Integral(x + (z / 2L), z))), "\\int \\left(x + \\frac{z}{2}\\right)\\, dz")
  expect_identical(.pf_out(latex(Integral(x ^ y, z))), "\\int x^{y}\\, dz")
  expect_identical(.pf_out(latex(Integral(x, x), diff_operator = "rd")), "\\int x\\, \\mathrm{d}x")
  expect_identical(.pf_out(latex(Integral(x, list(x, 0L, 1L)), diff_operator = "rd")), "\\int\\limits_{0}^{1} x\\, \\mathrm{d}x")
})

