test_that("latex test_latex_sequences", {
  for (.n in c("x", "y", "z", "t", "w", "a", "b", "c", "s", "p")) assign(.n, Symbol(.n))
  for (.n in c("k", "m", "n")) assign(.n, Symbol(.n, integer = TRUE))
  mu <- Symbol("mu"); tau <- Symbol("tau")
  f <- Function("f"); g <- Function("g")
  s1 <- SeqFormula(a ^ 2L, list(0L, oo))
  s2 <- SeqPer(list(1L, 2L))
  latex_str <- "\\left[0, 1, 4, 9, \\ldots\\right]"
  expect_identical(.pf_out(latex(s1)), "\\left[0, 1, 4, 9, \\ldots\\right]")
  latex_str <- "\\left[1, 2, 1, 2, \\ldots\\right]"
  expect_identical(.pf_out(latex(s2)), "\\left[1, 2, 1, 2, \\ldots\\right]")
  s3 <- SeqFormula(a ^ 2L, list(0L, 2L))
  s4 <- SeqPer(list(1L, 2L), list(0L, 2L))
  latex_str <- "\\left[0, 1, 4\\right]"
  expect_identical(.pf_out(latex(s3)), "\\left[0, 1, 4\\right]")
  latex_str <- "\\left[1, 2, 1\\right]"
  expect_identical(.pf_out(latex(s4)), "\\left[1, 2, 1\\right]")
  s5 <- SeqFormula(a ^ 2L, list(-oo, 0L))
  s6 <- SeqPer(list(1L, 2L), list(-oo, 0L))
  latex_str <- "\\left[\\ldots, 9, 4, 1, 0\\right]"
  expect_identical(.pf_out(latex(s5)), "\\left[\\ldots, 9, 4, 1, 0\\right]")
  latex_str <- "\\left[\\ldots, 2, 1, 2, 1\\right]"
  expect_identical(.pf_out(latex(s6)), "\\left[\\ldots, 2, 1, 2, 1\\right]")
  latex_str <- "\\left[1, 3, 5, 11, \\ldots\\right]"
  expect_identical(.pf_out(latex(SeqAdd(s1, s2))), "\\left[1, 3, 5, 11, \\ldots\\right]")
  latex_str <- "\\left[1, 3, 5\\right]"
  expect_identical(.pf_out(latex(SeqAdd(s3, s4))), "\\left[1, 3, 5\\right]")
  latex_str <- "\\left[\\ldots, 11, 5, 3, 1\\right]"
  expect_identical(.pf_out(latex(SeqAdd(s5, s6))), "\\left[\\ldots, 11, 5, 3, 1\\right]")
  latex_str <- "\\left[0, 2, 4, 18, \\ldots\\right]"
  expect_identical(.pf_out(latex(SeqMul(s1, s2))), "\\left[0, 2, 4, 18, \\ldots\\right]")
  latex_str <- "\\left[0, 2, 4\\right]"
  expect_identical(.pf_out(latex(SeqMul(s3, s4))), "\\left[0, 2, 4\\right]")
  latex_str <- "\\left[\\ldots, 18, 4, 2, 0\\right]"
  expect_identical(.pf_out(latex(SeqMul(s5, s6))), "\\left[\\ldots, 18, 4, 2, 0\\right]")
  s7 <- SeqFormula(a ^ 2L, list(a, 0L, x))
  latex_str <- "\\left\\{a^{2}\\right\\}_{a=0}^{x}"
  expect_identical(.pf_out(latex(s7)), "\\left\\{a^{2}\\right\\}_{a=0}^{x}")
  b <- Symbol("b")
  s8 <- SeqFormula(b * (a ^ 2L), list(a, 0L, 2L))
  latex_str <- "\\left[0, b, 4 b\\right]"
  expect_identical(.pf_out(latex(s8)), "\\left[0, b, 4 b\\right]")
})

