test_that("latex test_latex_limits", {
  for (.n in c("x", "y", "z", "t", "w", "a", "b", "c", "s", "p")) assign(.n, Symbol(.n))
  for (.n in c("k", "m", "n")) assign(.n, Symbol(.n, integer = TRUE))
  mu <- Symbol("mu"); tau <- Symbol("tau")
  f <- Function("f"); g <- Function("g")
  expect_identical(.pf_out(latex(Limit(x, x, oo))), "\\lim_{x \\to \\infty} x")
  f <- Function("f")
  expect_identical(.pf_out(latex(Limit(f(x), x, 0L))), "\\lim_{x \\to 0^+} f{\\left(x \\right)}")
  expect_identical(.pf_out(latex(Limit(f(x), x, 0L, "-"))), "\\lim_{x \\to 0^-} f{\\left(x \\right)}")
  expect_identical(.pf_out(latex(Limit(f(x), x, 0L) ^ 2L)), "\\left(\\lim_{x \\to 0^+} f{\\left(x \\right)}\\right)^{2}")
  expect_identical(.pf_out(latex(Limit(f(x), x, 0L, dir = "+-"))), "\\lim_{x \\to 0} f{\\left(x \\right)}")
})

