test_that("latex test_latex", {
  for (.n in c("x", "y", "z", "t", "w", "a", "b", "c", "s", "p")) assign(.n, Symbol(.n))
  for (.n in c("k", "m", "n")) assign(.n, Symbol(.n, integer = TRUE))
  mu <- Symbol("mu"); tau <- Symbol("tau")
  f <- Function("f"); g <- Function("g")
  expect_identical(.pf_out(latex((2L * tau) ^ Rational(7L, 2L))), "8 \\sqrt{2} \\tau^{\\frac{7}{2}}")
  expect_identical(.pf_out(latex((2L * mu) ^ Rational(7L, 2L), mode = "equation*")), "\\begin{equation*}8 \\sqrt{2} \\mu^{\\frac{7}{2}}\\end{equation*}")
  expect_identical(.pf_out(latex((2L * mu) ^ Rational(7L, 2L), mode = "equation", itex = TRUE)), "$$8 \\sqrt{2} \\mu^{\\frac{7}{2}}$$")
  expect_identical(.pf_out(latex(list(2L / x, y))), "\\left[ \\frac{2}{x}, \\  y\\right]")
})

