test_that("latex test_mode", {
  for (.n in c("x", "y", "z", "t", "w", "a", "b", "c", "s", "p")) assign(.n, Symbol(.n))
  for (.n in c("k", "m", "n")) assign(.n, Symbol(.n, integer = TRUE))
  mu <- Symbol("mu"); tau <- Symbol("tau")
  f <- Function("f"); g <- Function("g")
  try(expr <- x + y, silent = TRUE)
  expect_identical(.pf_out(latex(expr)), "x + y")
  expect_identical(.pf_out(latex(expr, mode = "plain")), "x + y")
  expect_identical(.pf_out(latex(expr, mode = "inline")), "$x + y$")
  expect_identical(.pf_out(latex(expr, mode = "equation*")), "\\begin{equation*}x + y\\end{equation*}")
  expect_identical(.pf_out(latex(expr, mode = "equation")), "\\begin{equation}x + y\\end{equation}")
  try(raises(ValueError, function() latex(expr, mode = "foo")), silent = TRUE)
})

