  mu <- Symbol("mu"); tau <- Symbol("tau")
  f <- Function("f"); g <- Function("g")
  p <- Piecewise(list(x, x < 1L), list(x ^ 2L, TRUE))
  expect_identical(.pf_out(latex(p)), "\\begin{cases} x & \\text{for}\\: x < 1 \\\\x^{2} & \\text{otherwise} \\end{cases}")
  expect_identical(.pf_out(latex(p, itex = TRUE)), "\\begin{cases} x & \\text{for}\\: x \\lt 1 \\\\x^{2} & \\text{otherwise} \\end{cases}")
  p <- Piecewise(list(x, x < 0L), list(0L, x >= 0L))
  expect_identical(.pf_out(latex(p)), "\\begin{cases} x & \\text{for}\\: x < 0 \\\\0 & \\text{otherwise} \\end{cases}")
})

test_that("latex test_latex_Matrix", {
  for (.n in c("x", "y", "z", "t", "w", "a", "b", "c", "s", "p")) assign(.n, Symbol(.n))
  for (.n in c("k", "m", "n")) assign(.n, Symbol(.n, integer = TRUE))
  mu <- Symbol("mu"); tau <- Symbol("tau")
  f <- Function("f"); g <- Function("g")
  M <- Matrix(list(list(1L + x, y), list(y, x - 1L)))
  expect_identical(.pf_out(latex(M)), "\\left[\\begin{matrix}x + 1 & y\\\\y & x - 1\\end{matrix}\\right]")
  expect_identical(.pf_out(latex(M, mode = "inline")), "$\\left[\\begin{smallmatrix}x + 1 & y\\\\y & x - 1\\end{smallmatrix}\\right]$")
  expect_identical(.pf_out(latex(M, mat_str = "array")), "\\left[\\begin{array}{cc}x + 1 & y\\\\y & x - 1\\end{array}\\right]")
  expect_identical(.pf_out(latex(M, mat_str = "bmatrix")), "\\left[\\begin{bmatrix}x + 1 & y\\\\y & x - 1\\end{bmatrix}\\right]")
  expect_identical(.pf_out(latex(M, mat_delim = NULL, mat_str = "bmatrix")), "\\begin{bmatrix}x + 1 & y\\\\y & x - 1\\end{bmatrix}")
})

