  expect_identical(.pf_out(latex(Symbol("beta_132_20"))), "\\beta_{132 20}")
  expect_identical(.pf_out(latex(Symbol("beta_13"))), "\\beta_{13}")
  expect_identical(.pf_out(latex(Symbol("x_a_b"))), "x_{a b}")
  expect_identical(.pf_out(latex(Symbol("x_1_2_3"))), "x_{1 2 3}")
  expect_identical(.pf_out(latex(Symbol("x_a_b1"))), "x_{a b1}")
  expect_identical(.pf_out(latex(Symbol("x_a_1"))), "x_{a 1}")
  expect_identical(.pf_out(latex(Symbol("x_1_a"))), "x_{1 a}")
  expect_identical(.pf_out(latex(Symbol("x_1^aa"))), "x^{aa}_{1}")
  expect_identical(.pf_out(latex(Symbol("x_1__aa"))), "x^{aa}_{1}")
  expect_identical(.pf_out(latex(Symbol("x_11^a"))), "x^{a}_{11}")
  expect_identical(.pf_out(latex(Symbol("x_11__a"))), "x^{a}_{11}")
  expect_identical(.pf_out(latex(Symbol("x_a_a_a_a"))), "x_{a a a a}")
  expect_identical(.pf_out(latex(Symbol("x_a_a^a^a"))), "x^{a a}_{a a}")
