  expect_identical(.pf_out(latex(Symbol("alpha_alpha"))), "\\alpha_{\\alpha}")
  expect_identical(.pf_out(latex(Symbol("alpha^aleph"))), "\\alpha^{\\aleph}")
  expect_identical(.pf_out(latex(Symbol("alpha__aleph"))), "\\alpha^{\\aleph}")
})

test_that("latex test_latex_order", {
  for (.n in c("x", "y", "z", "t", "w", "a", "b", "c", "s", "p")) assign(.n, Symbol(.n))
  for (.n in c("k", "m", "n")) assign(.n, Symbol(.n, integer = TRUE))
  mu <- Symbol("mu"); tau <- Symbol("tau")
  f <- Function("f"); g <- Function("g")
  expr <- (((x ^ 3L) + ((x ^ 2L) * y)) + (y ^ 4L)) + ((3L * x) * (y ^ 3L))
  expect_identical(.pf_out(latex(expr, order = "lex")), "x^{3} + x^{2} y + 3 x y^{3} + y^{4}")
  expect_identical(.pf_out(latex(expr, order = "none")), "x^{3} + y^{4} + y x^{2} + 3 x y^{3}")
})

