  f <- Function("f")
  a <- Symbol("a")
  b <- Symbol("b")
  expect_identical(.pf_out(latex(MellinTransform(f(x), x, k))), "\\mathcal{M}_{x}\\left[f{\\left(x \\right)}\\right]\\left(k\\right)")
  expect_identical(.pf_out(latex(InverseMellinTransform(f(k), k, x, a, b))), "\\mathcal{M}^{-1}_{k}\\left[f{\\left(k \\right)}\\right]\\left(x\\right)")
  expect_identical(.pf_out(latex(LaplaceTransform(f(x), x, k))), "\\mathcal{L}_{x}\\left[f{\\left(x \\right)}\\right]\\left(k\\right)")
