  expect_identical(.pf_out(latex(InverseFourierTransform(f(k), k, x))), "\\mathcal{F}^{-1}_{k}\\left[f{\\left(k \\right)}\\right]\\left(x\\right)")
  expect_identical(.pf_out(latex(CosineTransform(f(x), x, k))), "\\mathcal{COS}_{x}\\left[f{\\left(x \\right)}\\right]\\left(k\\right)")
  expect_identical(.pf_out(latex(InverseCosineTransform(f(k), k, x))), "\\mathcal{COS}^{-1}_{k}\\left[f{\\left(k \\right)}\\right]\\left(x\\right)")
  expect_identical(.pf_out(latex(SineTransform(f(x), x, k))), "\\mathcal{SIN}_{x}\\left[f{\\left(x \\right)}\\right]\\left(k\\right)")
  expect_identical(.pf_out(latex(InverseSineTransform(f(k), k, x))), "\\mathcal{SIN}^{-1}_{k}\\left[f{\\left(k \\right)}\\right]\\left(x\\right)")
})

