test_that("latex test_Adjoint", {
  for (.n in c("x", "y", "z", "t", "w", "a", "b", "c", "s", "p")) assign(.n, Symbol(.n))
  for (.n in c("k", "m", "n")) assign(.n, Symbol(.n, integer = TRUE))
  mu <- Symbol("mu"); tau <- Symbol("tau")
  f <- Function("f"); g <- Function("g")
  X <- MatrixSymbol("X", 2L, 2L)
  Y <- MatrixSymbol("Y", 2L, 2L)
  expect_identical(.pf_out(latex(Adjoint(X))), "X^{\\dagger}")
  expect_identical(.pf_out(latex(Adjoint(X + Y))), "\\left(X + Y\\right)^{\\dagger}")
  expect_identical(.pf_out(latex(Adjoint(X) + Adjoint(Y))), "X^{\\dagger} + Y^{\\dagger}")
  expect_identical(.pf_out(latex(Adjoint(X * Y))), "\\left(X Y\\right)^{\\dagger}")
  expect_identical(.pf_out(latex(Adjoint(Y) * Adjoint(X))), "Y^{\\dagger} X^{\\dagger}")
  expect_identical(.pf_out(latex(Adjoint(X ^ 2L))), "\\left(X^{2}\\right)^{\\dagger}")
  expect_identical(.pf_out(latex(Adjoint(X) ^ 2L)), "\\left(X^{\\dagger}\\right)^{2}")
  expect_identical(.pf_out(latex(Adjoint(Inverse(X)))), "\\left(X^{-1}\\right)^{\\dagger}")
  expect_identical(.pf_out(latex(Inverse(Adjoint(X)))), "\\left(X^{\\dagger}\\right)^{-1}")
  expect_identical(.pf_out(latex(Adjoint(Transpose(X)))), "\\left(X^{T}\\right)^{\\dagger}")
  expect_identical(.pf_out(latex(Transpose(Adjoint(X)))), "\\left(X^{\\dagger}\\right)^{T}")
  expect_identical(.pf_out(latex(Transpose(Adjoint(X) + Y))), "\\left(X^{\\dagger} + Y\\right)^{T}")
  m <- Matrix(list(list(1L, 2L), list(3L, 4L)))
  expect_identical(.pf_out(latex(Adjoint(m + X))), "\\left(\\left[\\begin{matrix}1 & 2\\\\3 & 4\\end{matrix}\\right] + X\\right)^{\\dagger}")
  expect_identical(.pf_out(latex(Adjoint(BlockMatrix(list(list(OneMatrix(2L, 2L), X), list(m, ZeroMatrix(2L, 2L))))))), "\\left[\\begin{matrix}1 & X\\\\\\left[\\begin{matrix}1 & 2\\\\3 & 4\\end{matrix}\\right] & 0\\end{matrix}\\right]^{\\dagger}")
  Mx <- MatrixSymbol("M^x", 2L, 2L)
  expect_identical(.pf_out(latex(Adjoint(Mx))), "\\left(M^{x}\\right)^{\\dagger}")
  expect_identical(.pf_out(latex(Adjoint(X), adjoint_style = "star")), "X^{\\ast}")
  expect_identical(.pf_out(latex(Adjoint(X + Y), adjoint_style = "hermitian")), "\\left(X + Y\\right)^{\\mathsf{H}}")
  expect_identical(.pf_out(latex(Adjoint(X) + Adjoint(Y), adjoint_style = "dagger")), "X^{\\dagger} + Y^{\\dagger}")
  expect_identical(.pf_out(latex(Adjoint(Y) * Adjoint(X))), "Y^{\\dagger} X^{\\dagger}")
  expect_identical(.pf_out(latex(Adjoint(X ^ 2L), adjoint_style = "star")), "\\left(X^{2}\\right)^{\\ast}")
  expect_identical(.pf_out(latex(Adjoint(X) ^ 2L, adjoint_style = "hermitian")), "\\left(X^{\\mathsf{H}}\\right)^{2}")
})

