  e <- Mul(S_Half, x + 1L, evaluate = FALSE)
  expect_identical(.pf_out(latex(e)), "\\frac{x + 1}{2}")
  e <- Mul(y, x + 1L, evaluate = FALSE)
  expect_identical(.pf_out(latex(e)), "y \\left(x + 1\\right)")
  e <- Mul(-y, x + 1L, evaluate = FALSE)
  expect_identical(.pf_out(latex(e)), "- y \\left(x + 1\\right)")
  e <- Mul(-2L, x + 1L)
  expect_identical(.pf_out(latex(e)), "- 2 x - 2")
  e <- Mul(2L, x + 1L)
  expect_identical(.pf_out(latex(e)), "2 x + 2")
})

