test_that("latex test_Series_printing", {
  for (.n in c("x", "y", "z", "t", "w", "a", "b", "c", "s", "p")) assign(.n, Symbol(.n))
  for (.n in c("k", "m", "n")) assign(.n, Symbol(.n, integer = TRUE))
  mu <- Symbol("mu"); tau <- Symbol("tau")
  f <- Function("f"); g <- Function("g")
  try(tf1 <- TransferFunction((x * (y ^ 2L)) - z, (y ^ 3L) - (t ^ 3L), y), silent = TRUE)
  try(tf2 <- TransferFunction(x - y, x + y, y), silent = TRUE)
  try(tf3 <- TransferFunction(((t * (x ^ 2L)) - ((t ^ w) * x)) + w, t - y, y), silent = TRUE)
  expect_identical(.pf_out(latex(Series(tf1, tf2))), "\\left(\\frac{x y^{2} - z}{- t^{3} + y^{3}}\\right) \\left(\\frac{x - y}{x + y}\\right)")
  expect_identical(.pf_out(latex(Series(tf1, tf2, tf3))), "\\left(\\frac{x y^{2} - z}{- t^{3} + y^{3}}\\right) \\left(\\frac{x - y}{x + y}\\right) \\left(\\frac{t x^{2} - t^{w} x + w}{t - y}\\right)")
  expect_identical(.pf_out(latex(Series(-tf2, tf1))), "\\left(\\frac{- x + y}{x + y}\\right) \\left(\\frac{x y^{2} - z}{- t^{3} + y^{3}}\\right)")
  try(M_1 <- Matrix(list(list(5L / s), list(5L / (2L * s)))), silent = TRUE)
})

