test_that("latex test_TransferFunctionMatrix_printing", {
  for (.n in c("x", "y", "z", "t", "w", "a", "b", "c", "s", "p")) assign(.n, Symbol(.n))
  for (.n in c("k", "m", "n")) assign(.n, Symbol(.n, integer = TRUE))
  mu <- Symbol("mu"); tau <- Symbol("tau")
  f <- Function("f"); g <- Function("g")
  tf1 <- TransferFunction(p, p + x, p)
  tf2 <- TransferFunction((-s) + p, p + s, p)
  tf3 <- TransferFunction(p, ((y ^ 2L) + (2L * y)) + 3L, p)
  expect_identical(.pf_out(latex(TransferFunctionMatrix(list(list(tf1), list(tf2))))), "\\left[\\begin{matrix}\\frac{p}{p + x}\\\\\\frac{p - s}{p + s}\\end{matrix}\\right]_\\tau")
  expect_identical(.pf_out(latex(TransferFunctionMatrix(list(list(tf1, tf2), list(tf3, -tf1))))), "\\left[\\begin{matrix}\\frac{p}{p + x} & \\frac{p - s}{p + s}\\\\\\frac{p}{y^{2} + 2 y + 3} & \\frac{\\left(-1\\right) p}{p + x}\\end{matrix}\\right]_\\tau")
  dtf1 <- DiscreteTransferFunction(p, p + x, p, Float(0.1))
  dtf2 <- DiscreteTransferFunction((-s) + p, p + s, p, Float(0.1))
  expect_identical(.pf_out(latex(TransferFunctionMatrix(list(list(dtf1), list(dtf2))))), "\\underset{[st:\\ {0.100000000000000}]}{\\left[\\begin{matrix}\\frac{p}{p + x}\\\\\\frac{p - s}{p + s}\\end{matrix}\\right]_k}")
})

test_that("latex test_Feedback_printing", {
  for (.n in c("x", "y", "z", "t", "w", "a", "b", "c", "s", "p")) assign(.n, Symbol(.n))
  for (.n in c("k", "m", "n")) assign(.n, Symbol(.n, integer = TRUE))
  mu <- Symbol("mu"); tau <- Symbol("tau")
  f <- Function("f"); g <- Function("g")
  tf1 <- TransferFunction(p, p + x, p)
  tf2 <- TransferFunction((-s) + p, p + s, p)
  expect_identical(.pf_out(latex(Feedback(tf1, tf2))), "\\frac{\\frac{p}{p + x}}{\\frac{1}{1} + \\left(\\frac{p}{p + x}\\right) \\left(\\frac{p - s}{p + s}\\right)}")
  expect_identical(.pf_out(latex(Feedback(tf1 * tf2, TransferFunction(1L, 1L, p)))), "\\frac{\\left(\\frac{p}{p + x}\\right) \\left(\\frac{p - s}{p + s}\\right)}{\\frac{1}{1} + \\left(\\frac{p}{p + x}\\right) \\left(\\frac{p - s}{p + s}\\right)}")
  expect_identical(.pf_out(latex(Feedback(tf1, tf2, 1L))), "\\frac{\\frac{p}{p + x}}{\\frac{1}{1} - \\left(\\frac{p}{p + x}\\right) \\left(\\frac{p - s}{p + s}\\right)}")
  expect_identical(.pf_out(latex(Feedback(tf1 * tf2, sign = 1L))), "\\frac{\\left(\\frac{p}{p + x}\\right) \\left(\\frac{p - s}{p + s}\\right)}{\\frac{1}{1} - \\left(\\frac{p}{p + x}\\right) \\left(\\frac{p - s}{p + s}\\right)}")
  tf3 <- TransferFunction(1L, p + 2L, p)
  expect_identical(.pf_out(latex(Feedback(tf1 * tf2, tf3))), "\\frac{\\left(\\frac{p}{p + x}\\right) \\left(\\frac{p - s}{p + s}\\right)}{\\frac{1}{1} + \\left(\\frac{p}{p + x}\\right) \\left(\\frac{p - s}{p + s}\\right) \\left(\\frac{1}{p + 2}\\right)}")
})

test_that("latex test_MIMOFeedback_printing", {
  for (.n in c("x", "y", "z", "t", "w", "a", "b", "c", "s", "p")) assign(.n, Symbol(.n))
  for (.n in c("k", "m", "n")) assign(.n, Symbol(.n, integer = TRUE))
  mu <- Symbol("mu"); tau <- Symbol("tau")
  f <- Function("f"); g <- Function("g")
  tf1 <- TransferFunction(1L, s, s)
  tf2 <- TransferFunction(s, (s ^ 2L) - 1L, s)
  tf3 <- TransferFunction(s, s - 1L, s)
  tf4 <- TransferFunction(s ^ 2L, (s ^ 2L) - 1L, s)
  tfm_1 <- TransferFunctionMatrix(list(list(tf1, tf2), list(tf3, tf4)))
  tfm_2 <- TransferFunctionMatrix(list(list(tf4, tf3), list(tf2, tf1)))
  expect_identical(.pf_out(latex(MIMOFeedback(tfm_1, tfm_2))), "\\left(I_{\\tau} + \\left[\\begin{matrix}\\frac{1}{s} & \\frac{s}{s^{2} - 1}\\\\\\frac{s}{s - 1} & \\frac{s^{2}}{s^{2} - 1}\\end{matrix}\\right]_\\tau\\cdot\\left[\\begin{matrix}\\frac{s^{2}}{s^{2} - 1} & \\frac{s}{s - 1}\\\\\\frac{s}{s^{2} - 1} & \\frac{1}{s}\\end{matrix}\\right]_\\tau\\right)^{-1} \\cdot \\left[\\begin{matrix}\\frac{1}{s} & \\frac{s}{s^{2} - 1}\\\\\\frac{s}{s - 1} & \\frac{s^{2}}{s^{2} - 1}\\end{matrix}\\right]_\\tau")
  expect_identical(.pf_out(latex(MIMOFeedback(tfm_1 * tfm_2, tfm_1, 1L))), "\\left(I_{\\tau} - \\left[\\begin{matrix}\\frac{1}{s} & \\frac{s}{s^{2} - 1}\\\\\\frac{s}{s - 1} & \\frac{s^{2}}{s^{2} - 1}\\end{matrix}\\right]_\\tau\\cdot\\left[\\begin{matrix}\\frac{s^{2}}{s^{2} - 1} & \\frac{s}{s - 1}\\\\\\frac{s}{s^{2} - 1} & \\frac{1}{s}\\end{matrix}\\right]_\\tau\\cdot\\left[\\begin{matrix}\\frac{1}{s} & \\frac{s}{s^{2} - 1}\\\\\\frac{s}{s - 1} & \\frac{s^{2}}{s^{2} - 1}\\end{matrix}\\right]_\\tau\\right)^{-1} \\cdot \\left[\\begin{matrix}\\frac{1}{s} & \\frac{s}{s^{2} - 1}\\\\\\frac{s}{s - 1} & \\frac{s^{2}}{s^{2} - 1}\\end{matrix}\\right]_\\tau\\cdot\\left[\\begin{matrix}\\frac{s^{2}}{s^{2} - 1} & \\frac{s}{s - 1}\\\\\\frac{s}{s^{2} - 1} & \\frac{1}{s}\\end{matrix}\\right]_\\tau")
})

