  expect_identical(.pf_out(latex(expr_2)), "1^{\\frac{1}{1}}")
  expr_3 <- Pow(3L, -2L, evaluate = FALSE)
  expect_identical(.pf_out(latex(expr_3)), "\\frac{1}{3^{2}}")
  expr_4 <- Pow(1L, -2L, evaluate = FALSE)
  expect_identical(.pf_out(latex(expr_4)), "1^{-2}")
})

