test_that("latex test_MatrixSymbol_bold", {
  for (.n in c("x", "y", "z", "t", "w", "a", "b", "c", "s", "p")) assign(.n, Symbol(.n))
  for (.n in c("k", "m", "n")) assign(.n, Symbol(.n, integer = TRUE))
  mu <- Symbol("mu"); tau <- Symbol("tau")
  f <- Function("f"); g <- Function("g")
  A <- MatrixSymbol("A", 2L, 2L)
  expect_identical(.pf_out(latex(sym_trace(A), mat_symbol_style = "bold")), "\\operatorname{tr}\\left(\\mathbf{A} \\right)")
  expect_identical(.pf_out(latex(sym_trace(A), mat_symbol_style = "plain")), "\\operatorname{tr}\\left(A \\right)")
  A <- MatrixSymbol("A", 3L, 3L)
  B <- MatrixSymbol("B", 3L, 3L)
  C <- MatrixSymbol("C", 3L, 3L)
  expect_identical(.pf_out(latex(-A, mat_symbol_style = "bold")), "- \\mathbf{A}")
  expect_identical(.pf_out(latex((A - (A * B)) - B, mat_symbol_style = "bold")), "\\mathbf{A} - \\mathbf{A} \\mathbf{B} - \\mathbf{B}")
  expect_identical(.pf_out(latex((((-A) * B) - ((A * B) * C)) - B, mat_symbol_style = "bold")), "- \\mathbf{A} \\mathbf{B} - \\mathbf{A} \\mathbf{B} \\mathbf{C} - \\mathbf{B}")
  A_k <- MatrixSymbol("A_k", 3L, 3L)
  expect_identical(.pf_out(latex(A_k, mat_symbol_style = "bold")), "\\mathbf{A}_{k}")
  A <- MatrixSymbol("\\nabla_k", 3L, 3L)
  expect_identical(.pf_out(latex(A, mat_symbol_style = "bold")), "\\mathbf{\\nabla}_{k}")
})

