test_that("pretty test_pretty_basic", {
  for (.n in c("a", "b", "c", "d", "x", "y", "z", "k", "n", "s", "p")) assign(.n, Symbol(.n))
  f <- Function("f"); th <- Symbol("theta"); ph <- Symbol("phi")
  .ppw <- function(e, u, order = NULL) if (inherits(e, "sym")) base::pretty(e, use_unicode = u, order = order) else if (inherits(e, "symmatrix")) base::pretty(e, use_unicode = u) else .pp2_doprint(e, u)
  pretty <- function(e, order = NULL) .ppw(e, FALSE, order)
  upretty <- function(e, order = NULL) .ppw(e, TRUE, order)
  expect_identical(.pf_out(pretty((-Rational(1L)) / 2L)), "-1/2")
  expect_identical(.pf_out(pretty((-Rational(13L)) / 22L)), "-13 \\n----\\n 22 ")
  expr <- oo
  ascii_str <- "oo"
  ucode_str <- "\u221e"
  expect_identical(.pf_out(pretty(expr)), "oo")
  expect_identical(.pf_out(upretty(expr)), "\u221e")
  expr <- x ^ 2L
  ascii_str <- " 2\nx "
  ucode_str <- " 2\nx "
  expect_identical(.pf_out(pretty(expr)), " 2\\nx ")
  expect_identical(.pf_out(upretty(expr)), " 2\\nx ")
  expr <- 1L / x
  ascii_str <- "1\n-\nx"
  ucode_str <- "1\n\u2500\nx"
  expect_identical(.pf_out(pretty(expr)), "1\\n-\\nx")
  expect_identical(.pf_out(upretty(expr)), "1\\n\u2500\\nx")
  expr <- x ^ (-Float(1.0))
  ascii_str <- " -1.0\nx    "
  ucode_str <- " -1.0\nx    "
  expect_identical(.pf_out(pretty(expr)), " -1.0\\nx    ")
  expect_identical(.pf_out(upretty(expr)), " -1.0\\nx    ")
  expr <- Pow(S(2L), -Float(1.0), evaluate = FALSE)
  ascii_str <- " -1.0\n2    "
  ucode_str <- " -1.0\n2    "
  expect_identical(.pf_out(pretty(expr)), " -1.0\\n2    ")
  expect_identical(.pf_out(upretty(expr)), " -1.0\\n2    ")
  expr <- y * (x ^ (-2L))
  ascii_str <- "y \n--\n 2\nx "
  ucode_str <- "y \n\u2500\u2500\n 2\nx "
  expect_identical(.pf_out(pretty(expr)), "y \\n--\\n 2\\nx ")
  expect_identical(.pf_out(upretty(expr)), "y \\n\u2500\u2500\\n 2\\nx ")
  expr <- x ^ Rational(1L, 3L)
  ascii_str <- " 1/3\nx   "
  ucode_str <- " 1/3\nx   "
  expr <- x ^ Rational(-5L, 2L)
  ascii_str <- " 1  \n----\n 5/2\nx   "
  ucode_str <- " 1  \n\u2500\u2500\u2500\u2500\n 5/2\nx   "
  expect_identical(.pf_out(pretty(expr)), " 1  \\n----\\n 5/2\\nx   ")
  expect_identical(.pf_out(upretty(expr)), " 1  \\n\u2500\u2500\u2500\u2500\\n 5/2\\nx   ")
  expr <- (-2L) ^ x
  ascii_str <- "    x\n(-2) "
  ucode_str <- "    x\n(-2) "
  expect_identical(.pf_out(pretty(expr)), "    x\\n(-2) ")
  expect_identical(.pf_out(upretty(expr)), "    x\\n(-2) ")
  expr <- Pow(3L, 1L, evaluate = FALSE)
  ascii_str <- " 1\n3 "
  ucode_str <- " 1\n3 "
  expect_identical(.pf_out(pretty(expr)), " 1\\n3 ")
  expect_identical(.pf_out(upretty(expr)), " 1\\n3 ")
  expr <- ((x ^ 2L) + x) + 1L
  ascii_str_1 <- "         2\n1 + x + x "
  ascii_str_2 <- " 2        \nx  + x + 1"
  ascii_str_3 <- " 2        \nx  + 1 + x"
  ucode_str_1 <- "         2\n1 + x + x "
  ucode_str_2 <- " 2        \nx  + x + 1"
  ucode_str_3 <- " 2        \nx  + 1 + x"
  expect_identical(.pf_out(pretty(expr)), " 2        \\nx  + x + 1")
  expect_identical(.pf_out(upretty(expr)), " 2        \\nx  + x + 1")
  expr <- 1L - x
  ascii_str_1 <- "1 - x"
  ascii_str_2 <- "-x + 1"
  ucode_str_1 <- "1 - x"
  ucode_str_2 <- "-x + 1"
  expect_identical(.pf_out(pretty(expr)), "1 - x")
  expect_identical(.pf_out(upretty(expr)), "1 - x")
  expr <- 1L - (2L * x)
  ascii_str_1 <- "1 - 2*x"
  ascii_str_2 <- "-2*x + 1"
  ucode_str_1 <- "1 - 2\u22c5x"
  ucode_str_2 <- "-2\u22c5x + 1"
  expect_identical(.pf_out(pretty(expr)), "1 - 2*x")
  expect_identical(.pf_out(upretty(expr)), "1 - 2\u22c5x")
  expr <- x / y
  ascii_str <- "x\n-\ny"
  ucode_str <- "x\n\u2500\ny"
  expect_identical(.pf_out(pretty(expr)), "x\\n-\\ny")
  expect_identical(.pf_out(upretty(expr)), "x\\n\u2500\\ny")
  expr <- (-x) / y
  ascii_str <- "-x \n---\n y "
  ucode_str <- "-x \n\u2500\u2500\u2500\n y "
  expect_identical(.pf_out(pretty(expr)), "-x \\n---\\n y ")
  expect_identical(.pf_out(upretty(expr)), "-x \\n\u2500\u2500\u2500\\n y ")
  expr <- (x + 2L) / y
  ascii_str_1 <- "2 + x\n-----\n  y  "
  ascii_str_2 <- "x + 2\n-----\n  y  "
  ucode_str_1 <- "2 + x\n\u2500\u2500\u2500\u2500\u2500\n  y  "
  ucode_str_2 <- "x + 2\n\u2500\u2500\u2500\u2500\u2500\n  y  "
  expect_identical(.pf_out(pretty(expr)), "x + 2\\n-----\\n  y  ")
  expect_identical(.pf_out(upretty(expr)), "x + 2\\n\u2500\u2500\u2500\u2500\u2500\\n  y  ")
  expr <- (1L + x) * y
  ascii_str_1 <- "y*(1 + x)"
  ascii_str_2 <- "(1 + x)*y"
  ascii_str_3 <- "y*(x + 1)"
  ucode_str_1 <- "y\u22c5(1 + x)"
  ucode_str_2 <- "(1 + x)\u22c5y"
  ucode_str_3 <- "y\u22c5(x + 1)"
  expect_identical(.pf_out(pretty(expr)), "y*(x + 1)")
  expect_identical(.pf_out(upretty(expr)), "y\u22c5(x + 1)")
  expr <- ((-5L) * x) / (x + 10L)
  ascii_str_1 <- "-5*x  \n------\n10 + x"
  ascii_str_2 <- "-5*x  \n------\nx + 10"
  ucode_str_1 <- "-5\u22c5x  \n\u2500\u2500\u2500\u2500\u2500\u2500\n10 + x"
  ucode_str_2 <- "-5\u22c5x  \n\u2500\u2500\u2500\u2500\u2500\u2500\nx + 10"
  expect_identical(.pf_out(pretty(expr)), "-5*x  \\n------\\nx + 10")
  expect_identical(.pf_out(upretty(expr)), "-5\u22c5x  \\n\u2500\u2500\u2500\u2500\u2500\u2500\\nx + 10")
  expr <- (-S_Half) - (3L * x)
  ascii_str <- "-3*x - 1/2"
  ucode_str <- "-3\u22c5x - 1/2"
  expect_identical(.pf_out(pretty(expr)), "-3*x - 1/2")
  expect_identical(.pf_out(upretty(expr)), "-3\u22c5x - 1/2")
  expr <- S_Half - (3L * x)
  ascii_str <- "1/2 - 3*x"
  ucode_str <- "1/2 - 3\u22c5x"
  expect_identical(.pf_out(pretty(expr)), "1/2 - 3*x")
  expect_identical(.pf_out(upretty(expr)), "1/2 - 3\u22c5x")
  expr <- (-S_Half) - ((3L * x) / 2L)
  ascii_str <- "  3*x   1\n- --- - -\n   2    2"
  ucode_str <- "  3\u22c5x   1\n- \u2500\u2500\u2500 - \u2500\n   2    2"
  expect_identical(.pf_out(pretty(expr)), "  3*x   1\\n- --- - -\\n   2    2")
  expect_identical(.pf_out(upretty(expr)), "  3\u22c5x   1\\n- \u2500\u2500\u2500 - \u2500\\n   2    2")
  expr <- S_Half - ((3L * x) / 2L)
  ascii_str <- "1   3*x\n- - ---\n2    2 "
  ucode_str <- "1   3\u22c5x\n\u2500 - \u2500\u2500\u2500\n2    2 "
  expect_identical(.pf_out(pretty(expr)), "1   3*x\\n- - ---\\n2    2 ")
  expect_identical(.pf_out(upretty(expr)), "1   3\u22c5x\\n\u2500 - \u2500\u2500\u2500\\n2    2 ")
})

test_that("pretty test_negative_fractions", {
  for (.n in c("a", "b", "c", "d", "x", "y", "z", "k", "n", "s", "p")) assign(.n, Symbol(.n))
  f <- Function("f"); th <- Symbol("theta"); ph <- Symbol("phi")
  .ppw <- function(e, u, order = NULL) if (inherits(e, "sym")) base::pretty(e, use_unicode = u, order = order) else if (inherits(e, "symmatrix")) base::pretty(e, use_unicode = u) else .pp2_doprint(e, u)
  pretty <- function(e, order = NULL) .ppw(e, FALSE, order)
  upretty <- function(e, order = NULL) .ppw(e, TRUE, order)
  expr <- (-x) / y
  ascii_str <- "-x \n---\n y "
  ucode_str <- "-x \n\u2500\u2500\u2500\n y "
  expect_identical(.pf_out(pretty(expr)), "-x \\n---\\n y ")
  expect_identical(.pf_out(upretty(expr)), "-x \\n\u2500\u2500\u2500\\n y ")
  expr <- ((-x) * z) / y
  ascii_str <- "-x*z \n-----\n  y  "
  ucode_str <- "-x\u22c5z \n\u2500\u2500\u2500\u2500\u2500\n  y  "
  expect_identical(.pf_out(pretty(expr)), "-x*z \\n-----\\n  y  ")
  expect_identical(.pf_out(upretty(expr)), "-x\u22c5z \\n\u2500\u2500\u2500\u2500\u2500\\n  y  ")
  expr <- (x ^ 2L) / y
  ascii_str <- " 2\nx \n--\ny "
  ucode_str <- " 2\nx \n\u2500\u2500\ny "
  expect_identical(.pf_out(pretty(expr)), " 2\\nx \\n--\\ny ")
  expect_identical(.pf_out(upretty(expr)), " 2\\nx \\n\u2500\u2500\\ny ")
  expr <- (-(x ^ 2L)) / y
  ascii_str <- "  2 \n-x  \n----\n y  "
  ucode_str <- "  2 \n-x  \n\u2500\u2500\u2500\u2500\n y  "
  expect_identical(.pf_out(pretty(expr)), "  2 \\n-x  \\n----\\n y  ")
  expect_identical(.pf_out(upretty(expr)), "  2 \\n-x  \\n\u2500\u2500\u2500\u2500\\n y  ")
  expr <- (-x) / (y * z)
  ascii_str <- "-x \n---\ny*z"
  ucode_str <- "-x \n\u2500\u2500\u2500\ny\u22c5z"
  expect_identical(.pf_out(pretty(expr)), "-x \\n---\\ny*z")
  expect_identical(.pf_out(upretty(expr)), "-x \\n\u2500\u2500\u2500\\ny\u22c5z")
  expr <- (-a) / (y ^ 2L)
  ascii_str <- "-a \n---\n 2 \ny  "
  ucode_str <- "-a \n\u2500\u2500\u2500\n 2 \ny  "
  expect_identical(.pf_out(pretty(expr)), "-a \\n---\\n 2 \\ny  ")
  expect_identical(.pf_out(upretty(expr)), "-a \\n\u2500\u2500\u2500\\n 2 \\ny  ")
  expr <- y ^ ((-a) / b)
  ascii_str <- " -a \n ---\n  b \ny   "
  ucode_str <- " -a \n \u2500\u2500\u2500\n  b \ny   "
  expect_identical(.pf_out(pretty(expr)), " -a \\n ---\\n  b \\ny   ")
  expect_identical(.pf_out(upretty(expr)), " -a \\n \u2500\u2500\u2500\\n  b \\ny   ")
  expr <- (-1L) / (y ^ 2L)
  ascii_str <- "-1 \n---\n 2 \ny  "
  ucode_str <- "-1 \n\u2500\u2500\u2500\n 2 \ny  "
  expect_identical(.pf_out(pretty(expr)), "-1 \\n---\\n 2 \\ny  ")
  expect_identical(.pf_out(upretty(expr)), "-1 \\n\u2500\u2500\u2500\\n 2 \\ny  ")
  expr <- (-10L) / (b ^ 2L)
  ascii_str <- "-10 \n----\n  2 \n b  "
  ucode_str <- "-10 \n\u2500\u2500\u2500\u2500\n  2 \n b  "
  expect_identical(.pf_out(pretty(expr)), "-10 \\n----\\n  2 \\n b  ")
  expect_identical(.pf_out(upretty(expr)), "-10 \\n\u2500\u2500\u2500\u2500\\n  2 \\n b  ")
  expr <- Rational(-200L, 37L)
  ascii_str <- "-200 \n-----\n 37  "
  ucode_str <- "-200 \n\u2500\u2500\u2500\u2500\u2500\n 37  "
  expect_identical(.pf_out(pretty(expr)), "-200 \\n-----\\n 37  ")
  expect_identical(.pf_out(upretty(expr)), "-200 \\n\u2500\u2500\u2500\u2500\u2500\\n 37  ")
})

test_that("pretty test_Mul", {
  for (.n in c("a", "b", "c", "d", "x", "y", "z", "k", "n", "s", "p")) assign(.n, Symbol(.n))
  f <- Function("f"); th <- Symbol("theta"); ph <- Symbol("phi")
  .ppw <- function(e, u, order = NULL) if (inherits(e, "sym")) base::pretty(e, use_unicode = u, order = order) else if (inherits(e, "symmatrix")) base::pretty(e, use_unicode = u) else .pp2_doprint(e, u)
  pretty <- function(e, order = NULL) .ppw(e, FALSE, order)
  upretty <- function(e, order = NULL) .ppw(e, TRUE, order)
  expr <- Mul(0L, 1L, evaluate = FALSE)
  expect_identical(.pf_out(pretty(expr)), "0*1")
  expect_identical(.pf_out(upretty(expr)), "0\u22c51")
  expr <- Mul(1L, 0L, evaluate = FALSE)
  expect_identical(.pf_out(pretty(expr)), "1*0")
  expect_identical(.pf_out(upretty(expr)), "1\u22c50")
  expr <- Mul(1L, 1L, evaluate = FALSE)
  expect_identical(.pf_out(pretty(expr)), "1*1")
  expect_identical(.pf_out(upretty(expr)), "1\u22c51")
  expr <- Mul(1L, 1L, 1L, evaluate = FALSE)
  expect_identical(.pf_out(pretty(expr)), "1*1*1")
  expect_identical(.pf_out(upretty(expr)), "1\u22c51\u22c51")
  expr <- Mul(1L, 2L, evaluate = FALSE)
  expect_identical(.pf_out(pretty(expr)), "1*2")
  expect_identical(.pf_out(upretty(expr)), "1\u22c52")
  expr <- Add(0L, 1L, evaluate = FALSE)
  expect_identical(.pf_out(pretty(expr)), "0 + 1")
  expect_identical(.pf_out(upretty(expr)), "0 + 1")
  expr <- Mul(1L, 1L, 2L, evaluate = FALSE)
  expect_identical(.pf_out(pretty(expr)), "1*1*2")
  expect_identical(.pf_out(upretty(expr)), "1\u22c51\u22c52")
  expr <- Add(0L, 0L, 1L, evaluate = FALSE)
  expect_identical(.pf_out(pretty(expr)), "0 + 0 + 1")
  expect_identical(.pf_out(upretty(expr)), "0 + 0 + 1")
  expr <- Mul(1L, -1L, evaluate = FALSE)
  expect_identical(.pf_out(pretty(expr)), "1*-1")
  expect_identical(.pf_out(upretty(expr)), "1\u22c5-1")
  expr <- Mul(Float(1.0), x, evaluate = FALSE)
  expect_identical(.pf_out(pretty(expr)), "1.0*x")
  expect_identical(.pf_out(upretty(expr)), "1.0\u22c5x")
  expr <- Mul(1L, 1L, 2L, 3L, x, evaluate = FALSE)
  expect_identical(.pf_out(pretty(expr)), "1*1*2*3*x")
  expect_identical(.pf_out(upretty(expr)), "1\u22c51\u22c52\u22c53\u22c5x")
  expr <- Mul(-1L, 1L, evaluate = FALSE)
  expect_identical(.pf_out(pretty(expr)), "-1*1")
  expect_identical(.pf_out(upretty(expr)), "-1\u22c51")
  expr <- Mul(4L, 3L, 2L, 1L, 0L, y, x, evaluate = FALSE)
  expect_identical(.pf_out(pretty(expr)), "4*3*2*1*0*y*x")
  expect_identical(.pf_out(upretty(expr)), "4\u22c53\u22c52\u22c51\u22c50\u22c5y\u22c5x")
  expr <- Mul(4L, 3L, 2L, 1L + z, 0L, y, x, evaluate = FALSE)
  expect_identical(.pf_out(pretty(expr)), "4*3*2*(z + 1)*0*y*x")
  expect_identical(.pf_out(upretty(expr)), "4\u22c53\u22c52\u22c5(z + 1)\u22c50\u22c5y\u22c5x")
  expr <- Mul(Rational(2L, 3L), Rational(5L, 7L), evaluate = FALSE)
  expect_identical(.pf_out(pretty(expr)), "2/3*5/7")
  expect_identical(.pf_out(upretty(expr)), "2/3\u22c55/7")
  expr <- Mul(x + y, Rational(1L, 2L), evaluate = FALSE)
  expect_identical(.pf_out(pretty(expr)), "(x + y)*1/2")
  expect_identical(.pf_out(upretty(expr)), "(x + y)\u22c51/2")
  expr <- Mul(Rational(1L, 2L), x + y, evaluate = FALSE)
  expect_identical(.pf_out(pretty(expr)), "x + y\\n-----\\n  2  ")
  expect_identical(.pf_out(upretty(expr)), "x + y\\n\u2500\u2500\u2500\u2500\u2500\\n  2  ")
  expr <- Mul(S_One, x + y, evaluate = FALSE)
  expect_identical(.pf_out(pretty(expr)), "1*(x + y)")
  expect_identical(.pf_out(upretty(expr)), "1\u22c5(x + y)")
  expr <- Mul(x - y, S_One, evaluate = FALSE)
  expect_identical(.pf_out(pretty(expr)), "(x - y)*1")
  expect_identical(.pf_out(upretty(expr)), "(x - y)\u22c51")
  expr <- Mul(Rational(1L, 2L), x - y, S_One, x + y, evaluate = FALSE)
  expect_identical(.pf_out(pretty(expr)), "1/2*(x - y)*1*(x + y)")
  expect_identical(.pf_out(upretty(expr)), "1/2\u22c5(x - y)\u22c51\u22c5(x + y)")
  expr <- Mul(x + y, Rational(3L, 4L), S_One, y - z, evaluate = FALSE)
  expect_identical(.pf_out(pretty(expr)), "(x + y)*3/4*1*(y - z)")
  expect_identical(.pf_out(upretty(expr)), "(x + y)\u22c53/4\u22c51\u22c5(y - z)")
  expr <- Mul(x + y, Rational(1L, 1L), Rational(3L, 4L), Rational(5L, 6L), evaluate = FALSE)
  expect_identical(.pf_out(pretty(expr)), "(x + y)*1*3/4*5/6")
  expect_identical(.pf_out(upretty(expr)), "(x + y)\u22c51\u22c53/4\u22c55/6")
  expr <- Mul(Rational(3L, 4L), x + y, S_One, y - z, evaluate = FALSE)
  expect_identical(.pf_out(pretty(expr)), "3/4*(x + y)*1*(y - z)")
  expect_identical(.pf_out(upretty(expr)), "3/4\u22c5(x + y)\u22c51\u22c5(y - z)")
})

test_that("pretty test_issue_5524", {
  for (.n in c("a", "b", "c", "d", "x", "y", "z", "k", "n", "s", "p")) assign(.n, Symbol(.n))
  f <- Function("f"); th <- Symbol("theta"); ph <- Symbol("phi")
  .ppw <- function(e, u, order = NULL) if (inherits(e, "sym")) base::pretty(e, use_unicode = u, order = order) else if (inherits(e, "symmatrix")) base::pretty(e, use_unicode = u) else .pp2_doprint(e, u)
  pretty <- function(e, order = NULL) .ppw(e, FALSE, order)
  upretty <- function(e, order = NULL) .ppw(e, TRUE, order)
  expect_identical(.pf_out(pretty(((-((-x) + 5L)) * (((-x) - (2L * sqrt(Integer(2L)))) + 5L)) - (((-y) + 5L) * ((-y) + 5L)))), "         2           /         ___    \\\\n- (5 - y)  + (x - 5)*\\-x - 2*\\/ 2  + 5/")
  expect_identical(.pf_out(upretty(((-((-x) + 5L)) * (((-x) - (2L * sqrt(Integer(2L)))) + 5L)) - (((-y) + 5L) * ((-y) + 5L)))), "         2                          \\n- (5 - y)  + (x - 5)\u22c5(-x - 2\u22c5\u221a2 + 5)")
})

test_that("pretty test_pretty_ordering", {
  for (.n in c("a", "b", "c", "d", "x", "y", "z", "k", "n", "s", "p")) assign(.n, Symbol(.n))
  f <- Function("f"); th <- Symbol("theta"); ph <- Symbol("phi")
  .ppw <- function(e, u, order = NULL) if (inherits(e, "sym")) base::pretty(e, use_unicode = u, order = order) else if (inherits(e, "symmatrix")) base::pretty(e, use_unicode = u) else .pp2_doprint(e, u)
  pretty <- function(e, order = NULL) .ppw(e, FALSE, order)
  upretty <- function(e, order = NULL) .ppw(e, TRUE, order)
  expect_identical(.pf_out(pretty(((x ^ 2L) + x) + 1L, order = "lex")), " 2        \\nx  + x + 1")
  expect_identical(.pf_out(pretty(((x ^ 2L) + x) + 1L, order = "rev-lex")), "         2\\n1 + x + x ")
  expect_identical(.pf_out(pretty(1L - x, order = "rev-lex")), "1 - x")
  expect_identical(.pf_out(pretty(1L - (2L * x), order = "rev-lex")), "1 - 2*x")
  f <- (((2L * (x ^ 4L)) + (y ^ 2L)) - (x ^ 2L)) + (y ^ 3L)
  expect_identical(.pf_out(pretty(f, order = NULL)), "   4    2    3    2\\n2*x  - x  + y  + y ")
  expect_identical(.pf_out(pretty(f, order = "lex")), "   4    2    3    2\\n2*x  - x  + y  + y ")
  expect_identical(.pf_out(pretty(f, order = "rev-lex")), " 2    3    2      4\\ny  + y  - x  + 2*x ")
  expr <- ((x - ((x ^ 3L) / 6L)) + ((x ^ 5L) / 120L)) + O(x ^ 6L)
  ascii_str <- "     3    5         \n    x    x      / 6\\\nx - -- + --- + O\\x /\n    6    120        "
  ucode_str <- "     3    5         \n    x    x      \u239b 6\u239e\nx - \u2500\u2500 + \u2500\u2500\u2500 + O\u239dx \u23a0\n    6    120        "
})

