test_that("pretty test_pretty_relational", {
  for (.n in c("a", "b", "c", "d", "x", "y", "z", "k", "n", "s", "p")) assign(.n, Symbol(.n))
  f <- Function("f"); th <- Symbol("theta"); ph <- Symbol("phi")
  .ppw <- function(e, u, order = NULL) if (inherits(e, "sym")) base::pretty(e, use_unicode = u, order = order) else if (inherits(e, "symmatrix")) base::pretty(e, use_unicode = u) else .pp2_doprint(e, u)
  pretty <- function(e, order = NULL) .ppw(e, FALSE, order)
  upretty <- function(e, order = NULL) .ppw(e, TRUE, order)
  expr <- Eq(x, y)
  ascii_str <- "x = y"
  ucode_str <- "x = y"
  expect_identical(.pf_out(pretty(expr)), "x = y")
  expect_identical(.pf_out(upretty(expr)), "x = y")
  expr <- Lt(x, y)
  ascii_str <- "x < y"
  ucode_str <- "x < y"
  expect_identical(.pf_out(pretty(expr)), "x < y")
  expect_identical(.pf_out(upretty(expr)), "x < y")
  expr <- Gt(x, y)
  ascii_str <- "x > y"
  ucode_str <- "x > y"
  expect_identical(.pf_out(pretty(expr)), "x > y")
  expect_identical(.pf_out(upretty(expr)), "x > y")
  expr <- Le(x, y)
  ascii_str <- "x <= y"
  ucode_str <- "x \u2264 y"
  expect_identical(.pf_out(pretty(expr)), "x <= y")
  expect_identical(.pf_out(upretty(expr)), "x \u2264 y")
  expr <- Ge(x, y)
  ascii_str <- "x >= y"
  ucode_str <- "x \u2265 y"
  expect_identical(.pf_out(pretty(expr)), "x >= y")
  expect_identical(.pf_out(upretty(expr)), "x \u2265 y")
  expr <- Ne(x / (y + 1L), y ^ 2L)
  ascii_str_1 <- "  x       2\n----- != y \n1 + y      "
  ascii_str_2 <- "  x       2\n----- != y \ny + 1      "
  ucode_str_1 <- "  x      2\n\u2500\u2500\u2500\u2500\u2500 \u2260 y \n1 + y     "
  ucode_str_2 <- "  x      2\n\u2500\u2500\u2500\u2500\u2500 \u2260 y \ny + 1     "
  expect_identical(.pf_out(pretty(expr)), "  x       2\\n----- != y \\ny + 1      ")
  expect_identical(.pf_out(upretty(expr)), "  x      2\\n\u2500\u2500\u2500\u2500\u2500 \u2260 y \\ny + 1     ")
})

