test_that("pretty test_pretty_rational", {
  for (.n in c("a", "b", "c", "d", "x", "y", "z", "k", "n", "s", "p")) assign(.n, Symbol(.n))
  f <- Function("f"); th <- Symbol("theta"); ph <- Symbol("phi")
  .ppw <- function(e, u, order = NULL) if (inherits(e, "sym")) base::pretty(e, use_unicode = u, order = order) else if (inherits(e, "symmatrix")) base::pretty(e, use_unicode = u) else .pp2_doprint(e, u)
  pretty <- function(e, order = NULL) .ppw(e, FALSE, order)
  upretty <- function(e, order = NULL) .ppw(e, TRUE, order)
  expr <- y * (x ^ (-2L))
  ascii_str <- "y \n--\n 2\nx "
  ucode_str <- "y \n\u2500\u2500\n 2\nx "
  expect_identical(.pf_out(pretty(expr)), "y \\n--\\n 2\\nx ")
  expect_identical(.pf_out(upretty(expr)), "y \\n\u2500\u2500\\n 2\\nx ")
  expr <- (y ^ Rational(3L, 2L)) * (x ^ Rational(-5L, 2L))
  ascii_str <- " 3/2\ny   \n----\n 5/2\nx   "
  ucode_str <- " 3/2\ny   \n\u2500\u2500\u2500\u2500\n 5/2\nx   "
  expect_identical(.pf_out(pretty(expr)), " 3/2\\ny   \\n----\\n 5/2\\nx   ")
  expect_identical(.pf_out(upretty(expr)), " 3/2\\ny   \\n\u2500\u2500\u2500\u2500\\n 5/2\\nx   ")
  expr <- (sin(x) ^ 3L) / (tan(x) ^ 2L)
  ascii_str <- "   3   \nsin (x)\n-------\n   2   \ntan (x)"
  ucode_str <- "   3   \nsin (x)\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n   2   \ntan (x)"
  expect_identical(.pf_out(pretty(expr)), "   3   \\nsin (x)\\n-------\\n   2   \\ntan (x)")
  expect_identical(.pf_out(upretty(expr)), "   3   \\nsin (x)\\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\\n   2   \\ntan (x)")
})

test_that("pretty test_pretty_functions", {
  for (.n in c("a", "b", "c", "d", "x", "y", "z", "k", "n", "s", "p")) assign(.n, Symbol(.n))
  f <- Function("f"); th <- Symbol("theta"); ph <- Symbol("phi")
  .ppw <- function(e, u, order = NULL) if (inherits(e, "sym")) base::pretty(e, use_unicode = u, order = order) else if (inherits(e, "symmatrix")) base::pretty(e, use_unicode = u) else .pp2_doprint(e, u)
  pretty <- function(e, order = NULL) .ppw(e, FALSE, order)
  upretty <- function(e, order = NULL) .ppw(e, TRUE, order)
  try(expr <- (2L * x) + exp(x), silent = TRUE)
  try(ascii_str_1 <- "       x\n2*x + e ", silent = TRUE)
  try(ascii_str_2 <- " x      \ne  + 2*x", silent = TRUE)
  try(ucode_str_1 <- "       x\n2\u22c5x + \u212f ", silent = TRUE)
  try(ucode_str_2 <- " x     \n\u212f + 2\u22c5x", silent = TRUE)
  try(ucode_str_3 <- " x      \n\u212f  + 2\u22c5x", silent = TRUE)
  expect_identical(.pf_out(pretty(expr)), "       x\\n2*x + e ")
  expect_identical(.pf_out(upretty(expr)), "       x\\n2\u22c5x + \u212f ")
  try(expr <- Abs(x), silent = TRUE)
  try(ascii_str <- "|x|", silent = TRUE)
  try(ucode_str <- "\u2502x\u2502", silent = TRUE)
  expect_identical(.pf_out(pretty(expr)), "|x|")
  expect_identical(.pf_out(upretty(expr)), "\u2502x\u2502")
  try(expr <- Abs(x / ((x ^ 2L) + 1L)), silent = TRUE)
  try(ascii_str_1 <- "|  x   |\n|------|\n|     2|\n|1 + x |", silent = TRUE)
  try(ascii_str_2 <- "|  x   |\n|------|\n| 2    |\n|x  + 1|", silent = TRUE)
  try(ucode_str_1 <- "\u2502  x   \u2502\n\u2502\u2500\u2500\u2500\u2500\u2500\u2500\u2502\n\u2502     2\u2502\n\u25021 + x \u2502", silent = TRUE)
  try(ucode_str_2 <- "\u2502  x   \u2502\n\u2502\u2500\u2500\u2500\u2500\u2500\u2500\u2502\n\u2502 2    \u2502\n\u2502x  + 1\u2502", silent = TRUE)
  expect_identical(.pf_out(pretty(expr)), "|  x   |\\n|------|\\n| 2    |\\n|x  + 1|")
  expect_identical(.pf_out(upretty(expr)), "\u2502  x   \u2502\\n\u2502\u2500\u2500\u2500\u2500\u2500\u2500\u2502\\n\u2502 2    \u2502\\n\u2502x  + 1\u2502")
  try(expr <- Abs(1L / (y - Abs(x))), silent = TRUE)
  try(ascii_str <- "    1    \n---------\n|y - |x||", silent = TRUE)
  try(ucode_str <- "    1    \n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\u2502y - \u2502x\u2502\u2502", silent = TRUE)
  expect_identical(.pf_out(pretty(expr)), "    1    \\n---------\\n|y - |x||")
  expect_identical(.pf_out(upretty(expr)), "    1    \\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\\n\u2502y - \u2502x\u2502\u2502")
  try(n <- Symbol("n", integer = TRUE), silent = TRUE)
  try(expr <- sym_factorial(n), silent = TRUE)
  try(ascii_str <- "n!", silent = TRUE)
  try(ucode_str <- "n!", silent = TRUE)
  expect_identical(.pf_out(pretty(expr)), "n!")
  expect_identical(.pf_out(upretty(expr)), "n!")
  try(expr <- sym_factorial(2L * n), silent = TRUE)
  try(ascii_str <- "(2*n)!", silent = TRUE)
  try(ucode_str <- "(2\u22c5n)!", silent = TRUE)
  expect_identical(.pf_out(pretty(expr)), "(2*n)!")
  expect_identical(.pf_out(upretty(expr)), "(2\u22c5n)!")
  try(expr <- sym_factorial(sym_factorial(sym_factorial(n))), silent = TRUE)
  try(ascii_str <- "((n!)!)!", silent = TRUE)
  try(ucode_str <- "((n!)!)!", silent = TRUE)
  expect_identical(.pf_out(pretty(expr)), "((n!)!)!")
  expect_identical(.pf_out(upretty(expr)), "((n!)!)!")
  try(expr <- sym_factorial(n + 1L), silent = TRUE)
  try(ascii_str_1 <- "(1 + n)!", silent = TRUE)
  try(ascii_str_2 <- "(n + 1)!", silent = TRUE)
  try(ucode_str_1 <- "(1 + n)!", silent = TRUE)
  try(ucode_str_2 <- "(n + 1)!", silent = TRUE)
  expect_identical(.pf_out(pretty(expr)), "(n + 1)!")
  expect_identical(.pf_out(upretty(expr)), "(n + 1)!")
  try(expr <- subfactorial(n), silent = TRUE)
  try(ascii_str <- "!n", silent = TRUE)
  try(ucode_str <- "!n", silent = TRUE)
  expect_identical(.pf_out(pretty(expr)), "!n")
  expect_identical(.pf_out(upretty(expr)), "!n")
  try(expr <- subfactorial(2L * n), silent = TRUE)
  try(ascii_str <- "!(2*n)", silent = TRUE)
  try(ucode_str <- "!(2\u22c5n)", silent = TRUE)
  expect_identical(.pf_out(pretty(expr)), "!(2*n)")
  expect_identical(.pf_out(upretty(expr)), "!(2\u22c5n)")
  try(n <- Symbol("n", integer = TRUE), silent = TRUE)
  try(expr <- factorial2(n), silent = TRUE)
  try(ascii_str <- "n!!", silent = TRUE)
  try(ucode_str <- "n!!", silent = TRUE)
  expect_identical(.pf_out(pretty(expr)), "n!!")
  expect_identical(.pf_out(upretty(expr)), "n!!")
  try(expr <- factorial2(2L * n), silent = TRUE)
  try(ascii_str <- "(2*n)!!", silent = TRUE)
  try(ucode_str <- "(2\u22c5n)!!", silent = TRUE)
  expect_identical(.pf_out(pretty(expr)), "(2*n)!!")
  expect_identical(.pf_out(upretty(expr)), "(2\u22c5n)!!")
  try(expr <- factorial2(factorial2(factorial2(n))), silent = TRUE)
  try(ascii_str <- "((n!!)!!)!!", silent = TRUE)
  try(ucode_str <- "((n!!)!!)!!", silent = TRUE)
  expect_identical(.pf_out(pretty(expr)), "((n!!)!!)!!")
  expect_identical(.pf_out(upretty(expr)), "((n!!)!!)!!")
  try(expr <- factorial2(n + 1L), silent = TRUE)
  try(ascii_str_1 <- "(1 + n)!!", silent = TRUE)
  try(ascii_str_2 <- "(n + 1)!!", silent = TRUE)
  try(ucode_str_1 <- "(1 + n)!!", silent = TRUE)
  try(ucode_str_2 <- "(n + 1)!!", silent = TRUE)
  expect_identical(.pf_out(pretty(expr)), "(n + 1)!!")
  expect_identical(.pf_out(upretty(expr)), "(n + 1)!!")
  try(expr <- 2L * sym_binomial(n, k), silent = TRUE)
  try(ascii_str <- "  /n\\\n2*| |\n  \\k/", silent = TRUE)
  try(ucode_str <- "  \u239bn\u239e\n2\u22c5\u239c \u239f\n  \u239dk\u23a0", silent = TRUE)
  expect_identical(.pf_out(pretty(expr)), "  /n\\\\n2*| |\\n  \\k/")
  expect_identical(.pf_out(upretty(expr)), "  \u239bn\u239e\\n2\u22c5\u239c \u239f\\n  \u239dk\u23a0")
  try(expr <- 2L * sym_binomial(2L * n, k), silent = TRUE)
  try(ascii_str <- "  /2*n\\\n2*|   |\n  \\ k /", silent = TRUE)
  try(ucode_str <- "  \u239b2\u22c5n\u239e\n2\u22c5\u239c   \u239f\n  \u239d k \u23a0", silent = TRUE)
  expect_identical(.pf_out(pretty(expr)), "  /2*n\\\\n2*|   |\\n  \\ k /")
  expect_identical(.pf_out(upretty(expr)), "  \u239b2\u22c5n\u239e\\n2\u22c5\u239c   \u239f\\n  \u239d k \u23a0")
  try(expr <- 2L * sym_binomial(n ^ 2L, k), silent = TRUE)
  try(ascii_str <- "  / 2\\\n  |n |\n2*|  |\n  \\k /", silent = TRUE)
  try(ucode_str <- "  \u239b 2\u239e\n  \u239cn \u239f\n2\u22c5\u239c  \u239f\n  \u239dk \u23a0", silent = TRUE)
  expect_identical(.pf_out(pretty(expr)), "  / 2\\\\n  |n |\\n2*|  |\\n  \\k /")
  expect_identical(.pf_out(upretty(expr)), "  \u239b 2\u239e\\n  \u239cn \u239f\\n2\u22c5\u239c  \u239f\\n  \u239dk \u23a0")
  try(expr <- catalan(n), silent = TRUE)
  try(ascii_str <- "C \n n", silent = TRUE)
  try(ucode_str <- "C \n n", silent = TRUE)
  expect_identical(.pf_out(pretty(expr)), "C \\n n")
  expect_identical(.pf_out(upretty(expr)), "C \\n n")
  try(expr <- catalan(n), silent = TRUE)
  try(ascii_str <- "C \n n", silent = TRUE)
  try(ucode_str <- "C \n n", silent = TRUE)
  expect_identical(.pf_out(pretty(expr)), "C \\n n")
  expect_identical(.pf_out(upretty(expr)), "C \\n n")
  try(expr <- bell(n), silent = TRUE)
  try(ascii_str <- "B \n n", silent = TRUE)
  try(ucode_str <- "B \n n", silent = TRUE)
  expect_identical(.pf_out(pretty(expr)), "B \\n n")
  expect_identical(.pf_out(upretty(expr)), "B \\n n")
  try(expr <- bernoulli(n), silent = TRUE)
  try(ascii_str <- "B \n n", silent = TRUE)
