  expect_identical(.pf_out(upretty(expr)), "B (x)\\n n   ")
  try(expr <- fibonacci(n), silent = TRUE)
  try(ascii_str <- "F \n n", silent = TRUE)
  try(ucode_str <- "F \n n", silent = TRUE)
  expect_identical(.pf_out(pretty(expr)), "F \\n n")
  expect_identical(.pf_out(upretty(expr)), "F \\n n")
  try(expr <- lucas(n), silent = TRUE)
  try(ascii_str <- "L \n n", silent = TRUE)
  try(ucode_str <- "L \n n", silent = TRUE)
  expect_identical(.pf_out(pretty(expr)), "L \\n n")
  expect_identical(.pf_out(upretty(expr)), "L \\n n")
  try(expr <- tribonacci(n), silent = TRUE)
  try(ascii_str <- "T \n n", silent = TRUE)
  try(ucode_str <- "T \n n", silent = TRUE)
  expect_identical(.pf_out(pretty(expr)), "T \\n n")
  expect_identical(.pf_out(upretty(expr)), "T \\n n")
  try(expr <- stieltjes(n), silent = TRUE)
  try(ascii_str <- "stieltjes \n         n", silent = TRUE)
  try(ucode_str <- "\u03b3 \n n", silent = TRUE)
  expect_identical(.pf_out(pretty(expr)), "stieltjes \\n         n")
  expect_identical(.pf_out(upretty(expr)), "\u03b3 \\n n")
  try(expr <- stieltjes(n, x), silent = TRUE)
  try(ascii_str <- "stieltjes (x)\n         n   ", silent = TRUE)
  try(ucode_str <- "\u03b3 (x)\n n   ", silent = TRUE)
  expect_identical(.pf_out(pretty(expr)), "stieltjes (x)\\n         n   ")
  expect_identical(.pf_out(upretty(expr)), "\u03b3 (x)\\n n   ")
  try(expr <- mathieuc(x, y, z), silent = TRUE)
  try(ascii_str <- "C(x, y, z)", silent = TRUE)
  try(ucode_str <- "C(x, y, z)", silent = TRUE)
  expect_identical(.pf_out(pretty(expr)), "C(x, y, z)")
  expect_identical(.pf_out(upretty(expr)), "C(x, y, z)")
  try(expr <- mathieus(x, y, z), silent = TRUE)
  try(ascii_str <- "S(x, y, z)", silent = TRUE)
  try(ucode_str <- "S(x, y, z)", silent = TRUE)
  expect_identical(.pf_out(pretty(expr)), "S(x, y, z)")
  expect_identical(.pf_out(upretty(expr)), "S(x, y, z)")
  try(expr <- mathieucprime(x, y, z), silent = TRUE)
  try(ascii_str <- "C'(x, y, z)", silent = TRUE)
  try(ucode_str <- "C'(x, y, z)", silent = TRUE)
  expect_identical(.pf_out(pretty(expr)), "C'(x, y, z)")
  expect_identical(.pf_out(upretty(expr)), "C'(x, y, z)")
  try(expr <- mathieusprime(x, y, z), silent = TRUE)
