  expect_identical(.pf_out(pretty(expr)), "S'(x, y, z)")
  expect_identical(.pf_out(upretty(expr)), "S'(x, y, z)")
  try(expr <- conjugate(x), silent = TRUE)
  try(ascii_str <- "_\nx", silent = TRUE)
  try(ucode_str <- "_\nx", silent = TRUE)
  expect_identical(.pf_out(pretty(expr)), "_\\nx")
  expect_identical(.pf_out(upretty(expr)), "_\\nx")
  try(f <- Function("f"), silent = TRUE)
  try(expr <- conjugate(f(x + 1L)), silent = TRUE)
  try(ascii_str_1 <- "________\nf(1 + x)", silent = TRUE)
  try(ascii_str_2 <- "________\nf(x + 1)", silent = TRUE)
  try(ucode_str_1 <- "________\nf(1 + x)", silent = TRUE)
  try(ucode_str_2 <- "________\nf(x + 1)", silent = TRUE)
  expect_identical(.pf_out(pretty(expr)), "________\\nf(x + 1)")
  expect_identical(.pf_out(upretty(expr)), "________\\nf(x + 1)")
  try(expr <- f(x), silent = TRUE)
  try(ascii_str <- "f(x)", silent = TRUE)
  try(ucode_str <- "f(x)", silent = TRUE)
  expect_identical(.pf_out(pretty(expr)), "f(x)")
  expect_identical(.pf_out(upretty(expr)), "f(x)")
  try(expr <- f(x, y), silent = TRUE)
  try(ascii_str <- "f(x, y)", silent = TRUE)
  try(ucode_str <- "f(x, y)", silent = TRUE)
  expect_identical(.pf_out(pretty(expr)), "f(x, y)")
  expect_identical(.pf_out(upretty(expr)), "f(x, y)")
  try(expr <- f(x / (y + 1L), y), silent = TRUE)
  try(ascii_str_1 <- " /  x     \\\nf|-----, y|\n \\1 + y   /", silent = TRUE)
  try(ascii_str_2 <- " /  x     \\\nf|-----, y|\n \\y + 1   /", silent = TRUE)
  try(ucode_str_1 <- " \u239b  x     \u239e\nf\u239c\u2500\u2500\u2500\u2500\u2500, y\u239f\n \u239d1 + y   \u23a0", silent = TRUE)
  try(ucode_str_2 <- " \u239b  x     \u239e\nf\u239c\u2500\u2500\u2500\u2500\u2500, y\u239f\n \u239dy + 1   \u23a0", silent = TRUE)
  expect_identical(.pf_out(pretty(expr)), " /  x     \\\\nf|-----, y|\\n \\y + 1   /")
  expect_identical(.pf_out(upretty(expr)), " \u239b  x     \u239e\\nf\u239c\u2500\u2500\u2500\u2500\u2500, y\u239f\\n \u239dy + 1   \u23a0")
  try(expr <- f(x ^ (x ^ (x ^ (x ^ (x ^ x))))), silent = TRUE)
  try(ascii_str <- " / / / / / x\\\\\\\\\\\n | | | | \\x /||||\n | | | \\x    /|||\n | | \\x       /||\n | \\x          /|\nf\\x             /", silent = TRUE)
  try(ucode_str <- " \u239b \u239b \u239b \u239b \u239b x\u239e\u239e\u239e\u239e\u239e\n \u239c \u239c \u239c \u239c \u239dx \u23a0\u239f\u239f\u239f\u239f\n \u239c \u239c \u239c \u239dx    \u23a0\u239f\u239f\u239f\n \u239c \u239c \u239dx       \u23a0\u239f\u239f\n \u239c \u239dx          \u23a0\u239f\nf\u239dx             \u23a0", silent = TRUE)
  expect_identical(.pf_out(pretty(expr)), " / / / / / x\\\\\\\\\\\\n | | | | \\x /||||\\n | | | \\x    /|||\\n | | \\x       /||\\n | \\x          /|\\nf\\x             /")
  expect_identical(.pf_out(upretty(expr)), " \u239b \u239b \u239b \u239b \u239b x\u239e\u239e\u239e\u239e\u239e\\n \u239c \u239c \u239c \u239c \u239dx \u23a0\u239f\u239f\u239f\u239f\\n \u239c \u239c \u239c \u239dx    \u23a0\u239f\u239f\u239f\\n \u239c \u239c \u239dx       \u23a0\u239f\u239f\\n \u239c \u239dx          \u23a0\u239f\\nf\u239dx             \u23a0")
  try(expr <- sin(x) ^ 2L, silent = TRUE)
  try(ascii_str <- "   2   \nsin (x)", silent = TRUE)
  try(ucode_str <- "   2   \nsin (x)", silent = TRUE)
  expect_identical(.pf_out(pretty(expr)), "   2   \\nsin (x)")
  expect_identical(.pf_out(upretty(expr)), "   2   \\nsin (x)")
  try(expr <- conjugate(a + (b * S_I)), silent = TRUE)
  try(ascii_str <- "_     _\na - I*b", silent = TRUE)
  try(ucode_str <- "_     _\na - \u2148\u22c5b", silent = TRUE)
  expect_identical(.pf_out(pretty(expr)), "_     _\\na - I*b")
  expect_identical(.pf_out(upretty(expr)), "_     _\\na - \u2148\u22c5b")
  try(expr <- conjugate(exp(a + (b * S_I))), silent = TRUE)
  try(ascii_str <- " _     _\n a - I*b\ne       ", silent = TRUE)
  try(ucode_str <- " _     _\n a - \u2148\u22c5b\n\u212f       ", silent = TRUE)
  expect_identical(.pf_out(pretty(expr)), " _     _\\n a - I*b\\ne       ")
  expect_identical(.pf_out(upretty(expr)), " _     _\\n a - \u2148\u22c5b\\n\u212f       ")
  try(expr <- conjugate(f(1L + conjugate(f(x)))), silent = TRUE)
  try(ascii_str_1 <- "___________\n /    ____\\\nf\\1 + f(x)/", silent = TRUE)
  try(ascii_str_2 <- "___________\n /____    \\\nf\\f(x) + 1/", silent = TRUE)
  try(ucode_str_1 <- "___________\n \u239b    ____\u239e\nf\u239d1 + f(x)\u23a0", silent = TRUE)
  try(ucode_str_2 <- "___________\n \u239b____    \u239e\nf\u239df(x) + 1\u23a0", silent = TRUE)
  expect_identical(.pf_out(pretty(expr)), "___________\\n /____    \\\\nf\\f(x) + 1/")
  expect_identical(.pf_out(upretty(expr)), "___________\\n \u239b____    \u239e\\nf\u239df(x) + 1\u23a0")
  try(expr <- f(x / (y + 1L), y), silent = TRUE)
  try(ascii_str_1 <- " /  x     \\\nf|-----, y|\n \\1 + y   /", silent = TRUE)
  try(ascii_str_2 <- " /  x     \\\nf|-----, y|\n \\y + 1   /", silent = TRUE)
  try(ucode_str_1 <- " \u239b  x     \u239e\nf\u239c\u2500\u2500\u2500\u2500\u2500, y\u239f\n \u239d1 + y   \u23a0", silent = TRUE)
  try(ucode_str_2 <- " \u239b  x     \u239e\nf\u239c\u2500\u2500\u2500\u2500\u2500, y\u239f\n \u239dy + 1   \u23a0", silent = TRUE)
  expect_identical(.pf_out(pretty(expr)), " /  x     \\\\nf|-----, y|\\n \\y + 1   /")
  expect_identical(.pf_out(upretty(expr)), " \u239b  x     \u239e\\nf\u239c\u2500\u2500\u2500\u2500\u2500, y\u239f\\n \u239dy + 1   \u23a0")
  try(expr <- floor(1L / (y - floor(x))), silent = TRUE)
  try(ascii_str <- "     /     1      \\\nfloor|------------|\n     \\y - floor(x)/", silent = TRUE)
  try(ucode_str <- "\u23a2   1   \u23a5\n\u23a2\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u23a5\n\u23a3y - \u230ax\u230b\u23a6", silent = TRUE)
  expect_identical(.pf_out(pretty(expr)), "     /     1      \\\\nfloor|------------|\\n     \\y - floor(x)/")
  expect_identical(.pf_out(upretty(expr)), "\u23a2   1   \u23a5\\n\u23a2\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u23a5\\n\u23a3y - \u230ax\u230b\u23a6")
  try(expr <- ceiling(1L / (y - ceiling(x))), silent = TRUE)
  try(ascii_str <- "       /      1       \\\nceiling|--------------|\n       \\y - ceiling(x)/", silent = TRUE)
  try(ucode_str <- "\u23a1   1   \u23a4\n\u23a2\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u23a5\n\u23a2y - \u2308x\u2309\u23a5", silent = TRUE)
  expect_identical(.pf_out(pretty(expr)), "       /      1       \\\\nceiling|--------------|\\n       \\y - ceiling(x)/")
  expect_identical(.pf_out(upretty(expr)), "\u23a1   1   \u23a4\\n\u23a2\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u23a5\\n\u23a2y - \u2308x\u2309\u23a5")
  try(expr <- euler(n), silent = TRUE)
  try(ascii_str <- "E \n n", silent = TRUE)
  try(ucode_str <- "E \n n", silent = TRUE)
  expect_identical(.pf_out(pretty(expr)), "E \\n n")
  expect_identical(.pf_out(upretty(expr)), "E \\n n")
  try(expr <- euler(1L / (1L + (1L / (1L + (1L / n))))), silent = TRUE)
  try(ascii_str <- "E         \n     1    \n ---------\n       1  \n 1 + -----\n         1\n     1 + -\n         n", silent = TRUE)
  try(ucode_str <- "E         \n     1    \n \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n       1  \n 1 + \u2500\u2500\u2500\u2500\u2500\n         1\n     1 + \u2500\n         n", silent = TRUE)
  expect_identical(.pf_out(pretty(expr)), "E         \\n     1    \\n ---------\\n       1  \\n 1 + -----\\n         1\\n     1 + -\\n         n")
  expect_identical(.pf_out(upretty(expr)), "E         \\n     1    \\n \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\\n       1  \\n 1 + \u2500\u2500\u2500\u2500\u2500\\n         1\\n     1 + \u2500\\n         n")
  try(expr <- euler(n, x), silent = TRUE)
  try(ascii_str <- "E (x)\n n   ", silent = TRUE)
  try(ucode_str <- "E (x)\n n   ", silent = TRUE)
  try(expr <- euler(n, x / 2L), silent = TRUE)
  try(ascii_str <- "  /x\\\nE |-|\n n\\2/", silent = TRUE)
  try(ucode_str <- "  \u239bx\u239e\nE \u239c\u2500\u239f\n n\u239d2\u23a0", silent = TRUE)
})

test_that("pretty test_pretty_sqrt", {
  for (.n in c("a", "b", "c", "d", "x", "y", "z", "k", "n", "s", "p")) assign(.n, Symbol(.n))
  f <- Function("f"); th <- Symbol("theta"); ph <- Symbol("phi")
  .ppw <- function(e, u, order = NULL) if (inherits(e, "sym")) base::pretty(e, use_unicode = u, order = order) else if (inherits(e, "symmatrix")) base::pretty(e, use_unicode = u) else .pp2_doprint(e, u)
  pretty <- function(e, order = NULL) .ppw(e, FALSE, order)
  upretty <- function(e, order = NULL) .ppw(e, TRUE, order)
  expr <- sqrt(Integer(2L))
  ascii_str <- "  ___\n\\/ 2 "
  ucode_str <- "\u221a2"
  expect_identical(.pf_out(pretty(expr)), "  ___\\n\\/ 2 ")
  expect_identical(.pf_out(upretty(expr)), "\u221a2")
  expr <- 2L ^ Rational(1L, 3L)
  ascii_str <- "3 ___\n\\/ 2 "
  ucode_str <- "3 ___\n\u2572\u2571 2 "
  expect_identical(.pf_out(pretty(expr)), "3 ___\\n\\/ 2 ")
  expect_identical(.pf_out(upretty(expr)), "3 ___\\n\u2572\u2571 2 ")
  expr <- 2L ^ Rational(1L, 1000L)
  ascii_str <- "1000___\n  \\/ 2 "
  ucode_str <- "1000___\n  \u2572\u2571 2 "
  expect_identical(.pf_out(pretty(expr)), "1000___\\n  \\/ 2 ")
  expect_identical(.pf_out(upretty(expr)), "1000___\\n  \u2572\u2571 2 ")
  expr <- sqrt((x ^ 2L) + 1L)
  ascii_str <- "   ________\n  /  2     \n\\/  x  + 1 "
  ucode_str <- "   ________\n  \u2571  2     \n\u2572\u2571  x  + 1 "
  expect_identical(.pf_out(pretty(expr)), "   ________\\n  /  2     \\n\\/  x  + 1 ")
  expect_identical(.pf_out(upretty(expr)), "   ________\\n  \u2571  2     \\n\u2572\u2571  x  + 1 ")
  expr <- (1L + sqrt(Integer(5L))) ^ Rational(1L, 3L)
  ascii_str <- "   ___________\n3 /       ___ \n\\/  1 + \\/ 5  "
  ucode_str <- "3 ________\n\u2572\u2571 1 + \u221a5 "
  expect_identical(.pf_out(pretty(expr)), "   ___________\\n3 /       ___ \\n\\/  1 + \\/ 5  ")
  expect_identical(.pf_out(upretty(expr)), "3 ________\\n\u2572\u2571 1 + \u221a5 ")
  expr <- 2L ^ (1L / x)
  ascii_str <- "x ___\n\\/ 2 "
  ucode_str <- "x ___\n\u2572\u2571 2 "
  expect_identical(.pf_out(pretty(expr)), "x ___\\n\\/ 2 ")
  expect_identical(.pf_out(upretty(expr)), "x ___\\n\u2572\u2571 2 ")
  expr <- sqrt(2L + S_Pi)
  ascii_str <- "  ________\n\\/ 2 + pi "
  ucode_str <- "  _______\n\u2572\u2571 2 + \u03c0 "
  expect_identical(.pf_out(pretty(expr)), "  ________\\n\\/ 2 + pi ")
  expect_identical(.pf_out(upretty(expr)), "  _______\\n\u2572\u2571 2 + \u03c0 ")
  expr <- ((2L + ((1L + (x ^ 2L)) / (2L + x))) ^ Rational(1L, 4L)) + ((1L + (x ^ Rational(1L, 1000L))) / sqrt(3L + (x ^ 2L)))
  ascii_str <- "     ____________              \n    /      2        1000___    \n   /      x  + 1      \\/ x  + 1\n4 /   2 + ------  + -----------\n\\/        x + 2        ________\n                      /  2     \n                    \\/  x  + 3 "
  ucode_str <- "     ____________              \n    \u2571      2        1000___    \n   \u2571      x  + 1      \u2572\u2571 x  + 1\n4 \u2571   2 + \u2500\u2500\u2500\u2500\u2500\u2500  + \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\u2572\u2571        x + 2        ________\n                      \u2571  2     \n                    \u2572\u2571  x  + 3 "
  expect_identical(.pf_out(pretty(expr)), "     ____________              \\n    /      2        1000___    \\n   /      x  + 1      \\/ x  + 1\\n4 /   2 + ------  + -----------\\n\\/        x + 2        ________\\n                      /  2     \\n                    \\/  x  + 3 ")
  expect_identical(.pf_out(upretty(expr)), "     ____________              \\n    \u2571      2        1000___    \\n   \u2571      x  + 1      \u2572\u2571 x  + 1\\n4 \u2571   2 + \u2500\u2500\u2500\u2500\u2500\u2500  + \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\\n\u2572\u2571        x + 2        ________\\n                      \u2571  2     \\n                    \u2572\u2571  x  + 3 ")
})

