test_that("pretty test_pretty_Lambda", {
  for (.n in c("a", "b", "c", "d", "x", "y", "z", "k", "n", "s", "p")) assign(.n, Symbol(.n))
  f <- Function("f"); th <- Symbol("theta"); ph <- Symbol("phi")
  .ppw <- function(e, u, order = NULL) if (inherits(e, "sym")) base::pretty(e, use_unicode = u, order = order) else if (inherits(e, "symmatrix")) base::pretty(e, use_unicode = u) else .pp2_doprint(e, u)
  pretty <- function(e, order = NULL) .ppw(e, FALSE, order)
  upretty <- function(e, order = NULL) .ppw(e, TRUE, order)
  try(expr <- Lambda(y, y), silent = TRUE)
  try(expr <- Lambda(x, x + 1L), silent = TRUE)
  expect_identical(.pf_out(pretty(expr)), "x -> x + 1")
  expect_identical(.pf_out(upretty(expr)), "x \u21a6 x + 1")
  try(expr <- Lambda(x, x ^ 2L), silent = TRUE)
  try(ascii_str <- "      2\nx -> x ", silent = TRUE)
  try(ucode_str <- "     2\nx \u21a6 x ", silent = TRUE)
  expect_identical(.pf_out(pretty(expr)), "      2\\nx -> x ")
  expect_identical(.pf_out(upretty(expr)), "     2\\nx \u21a6 x ")
  try(expr <- Lambda(x, x ^ 2L) ^ 2L, silent = TRUE)
  try(ascii_str <- "         2\n/      2\\ \n\\x -> x / ", silent = TRUE)
  try(ucode_str <- "        2\n\u239b     2\u239e \n\u239dx \u21a6 x \u23a0 ", silent = TRUE)
  expect_identical(.pf_out(pretty(expr)), "         2\\n/      2\\ \\n\\x -> x / ")
  expect_identical(.pf_out(upretty(expr)), "        2\\n\u239b     2\u239e \\n\u239dx \u21a6 x \u23a0 ")
  try(expr <- Lambda(list(x, y), x), silent = TRUE)
  try(ascii_str <- "(x, y) -> x", silent = TRUE)
  try(ucode_str <- "(x, y) \u21a6 x", silent = TRUE)
  expect_identical(.pf_out(pretty(expr)), "(x, y) -> x")
  expect_identical(.pf_out(upretty(expr)), "(x, y) \u21a6 x")
  try(expr <- Lambda(list(x, y), x ^ 2L), silent = TRUE)
  try(ascii_str <- "           2\n(x, y) -> x ", silent = TRUE)
  try(ucode_str <- "          2\n(x, y) \u21a6 x ", silent = TRUE)
  expect_identical(.pf_out(pretty(expr)), "           2\\n(x, y) -> x ")
  expect_identical(.pf_out(upretty(expr)), "          2\\n(x, y) \u21a6 x ")
  try(expr <- Lambda(list(list(x, y)), x ^ 2L), silent = TRUE)
  try(ascii_str <- "              2\n((x, y),) -> x ", silent = TRUE)
  try(ucode_str <- "             2\n((x, y),) \u21a6 x ", silent = TRUE)
})

test_that("pretty test_pretty_order", {
  for (.n in c("a", "b", "c", "d", "x", "y", "z", "k", "n", "s", "p")) assign(.n, Symbol(.n))
  f <- Function("f"); th <- Symbol("theta"); ph <- Symbol("phi")
  .ppw <- function(e, u, order = NULL) if (inherits(e, "sym")) base::pretty(e, use_unicode = u, order = order) else if (inherits(e, "symmatrix")) base::pretty(e, use_unicode = u) else .pp2_doprint(e, u)
  pretty <- function(e, order = NULL) .ppw(e, FALSE, order)
  upretty <- function(e, order = NULL) .ppw(e, TRUE, order)
  expr <- O(1L)
  ascii_str <- "O(1)"
  ucode_str <- "O(1)"
  expect_identical(.pf_out(pretty(expr)), "O(1)")
  expect_identical(.pf_out(upretty(expr)), "O(1)")
  expr <- O(1L / x)
  ascii_str <- " /1\\\nO|-|\n \\x/"
  ucode_str <- " \u239b1\u239e\nO\u239c\u2500\u239f\n \u239dx\u23a0"
  expect_identical(.pf_out(pretty(expr)), " /1\\\\nO|-|\\n \\x/")
  expect_identical(.pf_out(upretty(expr)), " \u239b1\u239e\\nO\u239c\u2500\u239f\\n \u239dx\u23a0")
  expr <- O((x ^ 2L) + (y ^ 2L))
  ascii_str <- " / 2    2                  \\\nO\\x  + y ; (x, y) -> (0, 0)/"
  ucode_str <- " \u239b 2    2                 \u239e\nO\u239dx  + y ; (x, y) \u2192 (0, 0)\u23a0"
  expect_identical(.pf_out(pretty(expr)), " / 2    2                  \\\\nO\\x  + y ; (x, y) -> (0, 0)/")
  expect_identical(.pf_out(upretty(expr)), " \u239b 2    2                 \u239e\\nO\u239dx  + y ; (x, y) \u2192 (0, 0)\u23a0")
  expr <- O(1L, list(x, oo))
  ascii_str <- "O(1; x -> oo)"
  ucode_str <- "O(1; x \u2192 \u221e)"
  expect_identical(.pf_out(pretty(expr)), "O(1; x -> oo)")
  expect_identical(.pf_out(upretty(expr)), "O(1; x \u2192 \u221e)")
  expr <- O(1L / x, list(x, oo))
  ascii_str <- " /1         \\\nO|-; x -> oo|\n \\x         /"
  ucode_str <- " \u239b1       \u239e\nO\u239c\u2500; x \u2192 \u221e\u239f\n \u239dx       \u23a0"
  expect_identical(.pf_out(pretty(expr)), " /1         \\\\nO|-; x -> oo|\\n \\x         /")
  expect_identical(.pf_out(upretty(expr)), " \u239b1       \u239e\\nO\u239c\u2500; x \u2192 \u221e\u239f\\n \u239dx       \u23a0")
  expr <- O((x ^ 2L) + (y ^ 2L), list(x, oo), list(y, oo))
  ascii_str <- " / 2    2                    \\\nO\\x  + y ; (x, y) -> (oo, oo)/"
  ucode_str <- " \u239b 2    2                 \u239e\nO\u239dx  + y ; (x, y) \u2192 (\u221e, \u221e)\u23a0"
  expect_identical(.pf_out(pretty(expr)), " / 2    2                    \\\\nO\\x  + y ; (x, y) -> (oo, oo)/")
  expect_identical(.pf_out(upretty(expr)), " \u239b 2    2                 \u239e\\nO\u239dx  + y ; (x, y) \u2192 (\u221e, \u221e)\u23a0")
})

test_that("pretty test_pretty_derivatives", {
  for (.n in c("a", "b", "c", "d", "x", "y", "z", "k", "n", "s", "p")) assign(.n, Symbol(.n))
  f <- Function("f"); th <- Symbol("theta"); ph <- Symbol("phi")
  .ppw <- function(e, u, order = NULL) if (inherits(e, "sym")) base::pretty(e, use_unicode = u, order = order) else if (inherits(e, "symmatrix")) base::pretty(e, use_unicode = u) else .pp2_doprint(e, u)
  pretty <- function(e, order = NULL) .ppw(e, FALSE, order)
  upretty <- function(e, order = NULL) .ppw(e, TRUE, order)
  try(expr <- Derivative(log(x), x, evaluate = FALSE), silent = TRUE)
  try(ascii_str <- "d         \n--(log(x))\ndx        ", silent = TRUE)
  try(ucode_str <- "d         \n\u2500\u2500(log(x))\ndx        ", silent = TRUE)
  expect_identical(.pf_out(pretty(expr)), "d         \\n--(log(x))\\ndx        ")
  expect_identical(.pf_out(upretty(expr)), "d         \\n\u2500\u2500(log(x))\\ndx        ")
  try(expr <- Derivative(log(x), x, evaluate = FALSE) + x, silent = TRUE)
  try(ascii_str_1 <- "    d         \nx + --(log(x))\n    dx        ", silent = TRUE)
  try(ascii_str_2 <- "d             \n--(log(x)) + x\ndx            ", silent = TRUE)
  try(ucode_str_1 <- "    d         \nx + \u2500\u2500(log(x))\n    dx        ", silent = TRUE)
  try(ucode_str_2 <- "d             \n\u2500\u2500(log(x)) + x\ndx            ", silent = TRUE)
  expect_identical(.pf_out(pretty(expr)), "    d         \\nx + --(log(x))\\n    dx        ")
  expect_identical(.pf_out(upretty(expr)), "    d         \\nx + \u2500\u2500(log(x))\\n    dx        ")
  try(expr <- Derivative(log(x + y) + x, x), silent = TRUE)
  try(ascii_str_1 <- "d                 \n--(log(x + y) + x)\ndx                ", silent = TRUE)
  try(ascii_str_2 <- "d                 \n--(x + log(x + y))\ndx                ", silent = TRUE)
  try(ucode_str_1 <- "\u2202                 \n\u2500\u2500(log(x + y) + x)\n\u2202x                ", silent = TRUE)
  try(ucode_str_2 <- "\u2202                 \n\u2500\u2500(x + log(x + y))\n\u2202x                ", silent = TRUE)
  expect_identical(.pf_out(pretty(expr)), "d                 \\n--(x + log(x + y))\\ndx                ")
  expect_identical(.pf_out(upretty(expr)), "\u2202                 \\n\u2500\u2500(x + log(x + y))\\n\u2202x                ")
  try(expr <- Derivative(log(x) + (x ^ 2L), x, y), silent = TRUE)
  try(ascii_str_1 <- "   2              \n  d  /          2\\\n-----\\log(x) + x /\ndy dx             ", silent = TRUE)
  try(ascii_str_2 <- "   2              \n  d  / 2         \\\n-----\\x  + log(x)/\ndy dx             ", silent = TRUE)
  try(ascii_str_3 <- "  2               \n d   / 2         \\\n-----\\x  + log(x)/\ndy dx             ", silent = TRUE)
  try(ucode_str_1 <- "   2              \n  d  \u239b          2\u239e\n\u2500\u2500\u2500\u2500\u2500\u239dlog(x) + x \u23a0\ndy dx             ", silent = TRUE)
  try(ucode_str_2 <- "   2              \n  d  \u239b 2         \u239e\n\u2500\u2500\u2500\u2500\u2500\u239dx  + log(x)\u23a0\ndy dx             ", silent = TRUE)
  try(ucode_str_3 <- "  2               \n d   \u239b 2         \u239e\n\u2500\u2500\u2500\u2500\u2500\u239dx  + log(x)\u23a0\ndy dx             ", silent = TRUE)
  expect_identical(.pf_out(pretty(expr)), "  2               \\n d   / 2         \\\\n-----\\x  + log(x)/\\ndy dx             ")
  expect_identical(.pf_out(upretty(expr)), "  2               \\n d   \u239b 2         \u239e\\n\u2500\u2500\u2500\u2500\u2500\u239dx  + log(x)\u23a0\\ndy dx             ")
  try(expr <- Derivative((2L * x) * y, y, x) + (x ^ 2L), silent = TRUE)
  try(ascii_str_1 <- "   2             \n  d             2\n-----(2*x*y) + x \ndx dy            ", silent = TRUE)
  try(ascii_str_2 <- "        2        \n 2     d         \nx  + -----(2*x*y)\n     dx dy       ", silent = TRUE)
  try(ascii_str_3 <- "       2         \n 2    d          \nx  + -----(2*x*y)\n     dx dy       ", silent = TRUE)
  try(ucode_str_1 <- "   2             \n  \u2202             2\n\u2500\u2500\u2500\u2500\u2500(2\u22c5x\u22c5y) + x \n\u2202x \u2202y            ", silent = TRUE)
  try(ucode_str_2 <- "        2        \n 2     \u2202         \nx  + \u2500\u2500\u2500\u2500\u2500(2\u22c5x\u22c5y)\n     \u2202x \u2202y       ", silent = TRUE)
  try(ucode_str_3 <- "       2         \n 2    \u2202          \nx  + \u2500\u2500\u2500\u2500\u2500(2\u22c5x\u22c5y)\n     \u2202x \u2202y       ", silent = TRUE)
  expect_identical(.pf_out(pretty(expr)), "       2         \\n 2    d          \\nx  + -----(2*x*y)\\n     dx dy       ")
  expect_identical(.pf_out(upretty(expr)), "       2         \\n 2    \u2202          \\nx  + \u2500\u2500\u2500\u2500\u2500(2\u22c5x\u22c5y)\\n     \u2202x \u2202y       ")
  try(expr <- Derivative((2L * x) * y, x, x), silent = TRUE)
  try(ascii_str <- " 2        \nd         \n---(2*x*y)\n  2       \ndx        ", silent = TRUE)
  try(ucode_str <- " 2        \n\u2202         \n\u2500\u2500\u2500(2\u22c5x\u22c5y)\n  2       \n\u2202x        ", silent = TRUE)
  expect_identical(.pf_out(pretty(expr)), " 2        \\nd         \\n---(2*x*y)\\n  2       \\ndx        ")
  expect_identical(.pf_out(upretty(expr)), " 2        \\n\u2202         \\n\u2500\u2500\u2500(2\u22c5x\u22c5y)\\n  2       \\n\u2202x        ")
  try(expr <- Derivative((2L * x) * y, x, 17L), silent = TRUE)
  try(ascii_str <- " 17        \nd          \n----(2*x*y)\n  17       \ndx         ", silent = TRUE)
  try(ucode_str <- " 17        \n\u2202          \n\u2500\u2500\u2500\u2500(2\u22c5x\u22c5y)\n  17       \n\u2202x         ", silent = TRUE)
  expect_identical(.pf_out(pretty(expr)), " 17        \\nd          \\n----(2*x*y)\\n  17       \\ndx         ")
  expect_identical(.pf_out(upretty(expr)), " 17        \\n\u2202          \\n\u2500\u2500\u2500\u2500(2\u22c5x\u22c5y)\\n  17       \\n\u2202x         ")
  try(expr <- Derivative((2L * x) * y, x, x, y), silent = TRUE)
  try(ascii_str <- "   3         \n  d          \n------(2*x*y)\n     2       \ndy dx        ", silent = TRUE)
  try(ucode_str <- "   3         \n  \u2202          \n\u2500\u2500\u2500\u2500\u2500\u2500(2\u22c5x\u22c5y)\n     2       \n\u2202y \u2202x        ", silent = TRUE)
  expect_identical(.pf_out(pretty(expr)), "   3         \\n  d          \\n------(2*x*y)\\n     2       \\ndy dx        ")
  expect_identical(.pf_out(upretty(expr)), "   3         \\n  \u2202          \\n\u2500\u2500\u2500\u2500\u2500\u2500(2\u22c5x\u22c5y)\\n     2       \\n\u2202y \u2202x        ")
  try(alpha <- Symbol("alpha"), silent = TRUE)
  try(sym_beta <- Function("beta"), silent = TRUE)
  try(expr <- diff(sym_beta(alpha), alpha), silent = TRUE)
  try(ascii_str <- "  d                \n------(beta(alpha))\ndalpha             ", silent = TRUE)
  try(ucode_str <- "d       \n\u2500\u2500(\u03b2(\u03b1))\nd\u03b1      ", silent = TRUE)
  try(expr <- Derivative(f(x), list(x, n)), silent = TRUE)
  try(ascii_str <- " n       \nd        \n---(f(x))\n  n      \ndx       ", silent = TRUE)
  try(ucode_str <- " n       \nd        \n\u2500\u2500\u2500(f(x))\n  n      \ndx       ", silent = TRUE)
  expect_identical(.pf_out(pretty(expr)), " n       \\nd        \\n---(f(x))\\n  n      \\ndx       ")
  expect_identical(.pf_out(upretty(expr)), " n       \\nd        \\n\u2500\u2500\u2500(f(x))\\n  n      \\ndx       ")
})

test_that("pretty test_pretty_integrals", {
  for (.n in c("a", "b", "c", "d", "x", "y", "z", "k", "n", "s", "p")) assign(.n, Symbol(.n))
  f <- Function("f"); th <- Symbol("theta"); ph <- Symbol("phi")
  .ppw <- function(e, u, order = NULL) if (inherits(e, "sym")) base::pretty(e, use_unicode = u, order = order) else if (inherits(e, "symmatrix")) base::pretty(e, use_unicode = u) else .pp2_doprint(e, u)
  pretty <- function(e, order = NULL) .ppw(e, FALSE, order)
  upretty <- function(e, order = NULL) .ppw(e, TRUE, order)
  expr <- Integral(log(x), x)
  ascii_str <- "  /         \n |          \n | log(x) dx\n |          \n/           "
  ucode_str <- "\u2320          \n\u23ae log(x) dx\n\u2321          "
  expect_identical(.pf_out(pretty(expr)), "  /         \\n |          \\n | log(x) dx\\n |          \\n/           ")
  expect_identical(.pf_out(upretty(expr)), "\u2320          \\n\u23ae log(x) dx\\n\u2321          ")
  expr <- Integral(x ^ 2L, x)
  ascii_str <- "  /     \n |      \n |  2   \n | x  dx\n |      \n/       "
  ucode_str <- "\u2320      \n\u23ae  2   \n\u23ae x  dx\n\u2321      "
  expect_identical(.pf_out(pretty(expr)), "  /     \\n |      \\n |  2   \\n | x  dx\\n |      \\n/       ")
  expect_identical(.pf_out(upretty(expr)), "\u2320      \\n\u23ae  2   \\n\u23ae x  dx\\n\u2321      ")
  expr <- Integral((sin(x) ^ 2L) / (tan(x) ^ 2L))
  ascii_str <- "  /          \n |           \n |    2      \n | sin (x)   \n | ------- dx\n |    2      \n | tan (x)   \n |           \n/            "
  ucode_str <- "\u2320           \n\u23ae    2      \n\u23ae sin (x)   \n\u23ae \u2500\u2500\u2500\u2500\u2500\u2500\u2500 dx\n\u23ae    2      \n\u23ae tan (x)   \n\u2321           "
  expect_identical(.pf_out(pretty(expr)), "  /          \\n |           \\n |    2      \\n | sin (x)   \\n | ------- dx\\n |    2      \\n | tan (x)   \\n |           \\n/            ")
  expect_identical(.pf_out(upretty(expr)), "\u2320           \\n\u23ae    2      \\n\u23ae sin (x)   \\n\u23ae \u2500\u2500\u2500\u2500\u2500\u2500\u2500 dx\\n\u23ae    2      \\n\u23ae tan (x)   \\n\u2321           ")
  expr <- Integral(x ^ (2L ^ x), x)
  ascii_str <- "  /        \n |         \n |  / x\\   \n |  \\2 /   \n | x     dx\n |         \n/          "
  ucode_str <- "\u2320         \n\u23ae  \u239b x\u239e   \n\u23ae  \u239d2 \u23a0   \n\u23ae x     dx\n\u2321         "
  expect_identical(.pf_out(pretty(expr)), "  /        \\n |         \\n |  / x\\   \\n |  \\2 /   \\n | x     dx\\n |         \\n/          ")
  expect_identical(.pf_out(upretty(expr)), "\u2320         \\n\u23ae  \u239b x\u239e   \\n\u23ae  \u239d2 \u23a0   \\n\u23ae x     dx\\n\u2321         ")
  expr <- Integral(x ^ 2L, list(x, 1L, 2L))
  ascii_str <- "  2      \n  /      \n |       \n |   2   \n |  x  dx\n |       \n/        \n1        "
  ucode_str <- "2      \n\u2320      \n\u23ae  2   \n\u23ae x  dx\n\u2321      \n1      "
  expect_identical(.pf_out(pretty(expr)), "  2      \\n  /      \\n |       \\n |   2   \\n |  x  dx\\n |       \\n/        \\n1        ")
  expect_identical(.pf_out(upretty(expr)), "2      \\n\u2320      \\n\u23ae  2   \\n\u23ae x  dx\\n\u2321      \\n1      ")
  expr <- Integral(x ^ 2L, list(x, Rational(1L, 2L), 10L))
  ascii_str <- " 10      \n  /      \n |       \n |   2   \n |  x  dx\n |       \n/        \n1/2      "
  ucode_str <- "10       \n\u2320        \n\u23ae    2   \n\u23ae   x  dx\n\u2321        \n1/2      "
  expect_identical(.pf_out(pretty(expr)), " 10      \\n  /      \\n |       \\n |   2   \\n |  x  dx\\n |       \\n/        \\n1/2      ")
  expect_identical(.pf_out(upretty(expr)), "10       \\n\u2320        \\n\u23ae    2   \\n\u23ae   x  dx\\n\u2321        \\n1/2      ")
  expr <- Integral((x ^ 2L) * (y ^ 2L), x, y)
  ascii_str <- "  /  /           \n |  |            \n |  |  2  2      \n |  | x *y  dx dy\n |  |            \n/  /             "
  ucode_str <- "\u2320 \u2320            \n\u23ae \u23ae  2  2      \n\u23ae \u23ae x \u22c5y  dx dy\n\u2321 \u2321            "
  expect_identical(.pf_out(pretty(expr)), "  /  /           \\n |  |            \\n |  |  2  2      \\n |  | x *y  dx dy\\n |  |            \\n/  /             ")
  expect_identical(.pf_out(upretty(expr)), "\u2320 \u2320            \\n\u23ae \u23ae  2  2      \\n\u23ae \u23ae x \u22c5y  dx dy\\n\u2321 \u2321            ")
  expr <- Integral(sin(th) / cos(ph), list(th, 0L, S_Pi), list(ph, 0L, 2L * S_Pi))
  ascii_str <- " 2*pi pi                           \n   /   /                           \n  |   |                            \n  |   |  sin(theta)                \n  |   |  ---------- d(theta) d(phi)\n  |   |   cos(phi)                 \n  |   |                            \n /   /                             \n0    0                             "
  ucode_str <- "2\u22c5\u03c0 \u03c0             \n \u2320  \u2320             \n \u23ae  \u23ae sin(\u03b8)      \n \u23ae  \u23ae \u2500\u2500\u2500\u2500\u2500\u2500 d\u03b8 d\u03c6\n \u23ae  \u23ae cos(\u03c6)      \n \u2321  \u2321             \n 0  0             "
  expect_identical(.pf_out(pretty(expr)), " 2*pi pi                           \\n   /   /                           \\n  |   |                            \\n  |   |  sin(theta)                \\n  |   |  ---------- d(theta) d(phi)\\n  |   |   cos(phi)                 \\n  |   |                            \\n /   /                             \\n0    0                             ")
  expect_identical(.pf_out(upretty(expr)), "2\u22c5\u03c0 \u03c0             \\n \u2320  \u2320             \\n \u23ae  \u23ae sin(\u03b8)      \\n \u23ae  \u23ae \u2500\u2500\u2500\u2500\u2500\u2500 d\u03b8 d\u03c6\\n \u23ae  \u23ae cos(\u03c6)      \\n \u2321  \u2321             \\n 0  0             ")
})

test_that("pretty test_pretty_matrix", {
  for (.n in c("a", "b", "c", "d", "x", "y", "z", "k", "n", "s", "p")) assign(.n, Symbol(.n))
  f <- Function("f"); th <- Symbol("theta"); ph <- Symbol("phi")
  .ppw <- function(e, u, order = NULL) if (inherits(e, "sym")) base::pretty(e, use_unicode = u, order = order) else if (inherits(e, "symmatrix")) base::pretty(e, use_unicode = u) else .pp2_doprint(e, u)
  pretty <- function(e, order = NULL) .ppw(e, FALSE, order)
  upretty <- function(e, order = NULL) .ppw(e, TRUE, order)
  try(expr <- Matrix(), silent = TRUE)
  try(ascii_str <- "[]", silent = TRUE)
  try(unicode_str <- "[]", silent = TRUE)
  try(expr <- Matrix(2L, 0L, function(i, j) 0L), silent = TRUE)
  try(ascii_str <- "[]", silent = TRUE)
  try(unicode_str <- "[]", silent = TRUE)
  expect_identical(.pf_out(pretty(expr)), "[]")
  expect_identical(.pf_out(upretty(expr)), "[]")
  try(expr <- Matrix(0L, 2L, function(i, j) 0L), silent = TRUE)
  try(ascii_str <- "[]", silent = TRUE)
  try(unicode_str <- "[]", silent = TRUE)
  expect_identical(.pf_out(pretty(expr)), "[]")
  expect_identical(.pf_out(upretty(expr)), "[]")
  try(expr <- Matrix(list(list((x ^ 2L) + 1L, 1L), list(y, x + y))), silent = TRUE)
  try(ascii_str_1 <- "[     2       ]\n[1 + x     1  ]\n[             ]\n[  y     x + y]", silent = TRUE)
  try(ascii_str_2 <- "[ 2           ]\n[x  + 1    1  ]\n[             ]\n[  y     x + y]", silent = TRUE)
  try(ucode_str_1 <- "\u23a1     2       \u23a4\n\u23a21 + x     1  \u23a5\n\u23a2             \u23a5\n\u23a3  y     x + y\u23a6", silent = TRUE)
  try(ucode_str_2 <- "\u23a1 2           \u23a4\n\u23a2x  + 1    1  \u23a5\n\u23a2             \u23a5\n\u23a3  y     x + y\u23a6", silent = TRUE)
  expect_identical(.pf_out(pretty(expr)), "[ 2           ]\\n[x  + 1    1  ]\\n[             ]\\n[  y     x + y]")
  expect_identical(.pf_out(upretty(expr)), "\u23a1 2           \u23a4\\n\u23a2x  + 1    1  \u23a5\\n\u23a2             \u23a5\\n\u23a3  y     x + y\u23a6")
  try(expr <- Matrix(list(list(x / y, y, th), list(0L, exp((S_I * k) * ph), 1L))), silent = TRUE)
  try(ascii_str <- "[x                 ]\n[-     y      theta]\n[y                 ]\n[                  ]\n[    I*k*phi       ]\n[0  e           1  ]", silent = TRUE)
  try(ucode_str <- "\u23a1x           \u23a4\n\u23a2\u2500    y     \u03b8\u23a5\n\u23a2y           \u23a5\n\u23a2            \u23a5\n\u23a2    \u2148\u22c5k\u22c5\u03c6   \u23a5\n\u23a30  \u212f       1\u23a6", silent = TRUE)
  expect_identical(.pf_out(pretty(expr)), "[x                 ]\\n[-     y      theta]\\n[y                 ]\\n[                  ]\\n[    I*k*phi       ]\\n[0  e           1  ]")
  expect_identical(.pf_out(upretty(expr)), "\u23a1x           \u23a4\\n\u23a2\u2500    y     \u03b8\u23a5\\n\u23a2y           \u23a5\\n\u23a2            \u23a5\\n\u23a2    \u2148\u22c5k\u22c5\u03c6   \u23a5\\n\u23a30  \u212f       1\u23a6")
  try(unicode_str <- "\u23a1v\u0307_msc_00     0         0    \u23a4\n\u23a2                            \u23a5\n\u23a2   0      v\u0307_msc_01     0    \u23a5\n\u23a2                            \u23a5\n\u23a3   0         0      v\u0307_msc_02\u23a6", silent = TRUE)
})

test_that("pretty test_Adjoint", {
  for (.n in c("a", "b", "c", "d", "x", "y", "z", "k", "n", "s", "p")) assign(.n, Symbol(.n))
  f <- Function("f"); th <- Symbol("theta"); ph <- Symbol("phi")
  .ppw <- function(e, u, order = NULL) if (inherits(e, "sym")) base::pretty(e, use_unicode = u, order = order) else if (inherits(e, "symmatrix")) base::pretty(e, use_unicode = u) else .pp2_doprint(e, u)
  pretty <- function(e, order = NULL) .ppw(e, FALSE, order)
  upretty <- function(e, order = NULL) .ppw(e, TRUE, order)
  X <- MatrixSymbol("X", 2L, 2L)
  Y <- MatrixSymbol("Y", 2L, 2L)
  expect_identical(.pf_out(pretty(Adjoint(X))), " +\\nX ")
  expect_identical(.pf_out(pretty(Adjoint(X + Y))), "       +\\n(X + Y) ")
  expect_identical(.pf_out(pretty(Adjoint(X) + Adjoint(Y))), " +    +\\nX  + Y ")
  expect_identical(.pf_out(pretty(Adjoint(X * Y))), "     +\\n(X*Y) ")
  expect_identical(.pf_out(pretty(Adjoint(Y) * Adjoint(X))), " +  +\\nY *X ")
  expect_identical(.pf_out(pretty(Adjoint(X ^ 2L))), "    +\\n/ 2\\ \\n\\X / ")
  expect_identical(.pf_out(pretty(Adjoint(X) ^ 2L)), "    2\\n/ +\\ \\n\\X / ")
  expect_identical(.pf_out(pretty(Adjoint(Inverse(X)))), "     +\\n/ -1\\ \\n\\X  / ")
  expect_identical(.pf_out(pretty(Inverse(Adjoint(X)))), "    -1\\n/ +\\  \\n\\X /  ")
  expect_identical(.pf_out(pretty(Adjoint(Transpose(X)))), "    +\\n/ T\\ \\n\\X / ")
  expect_identical(.pf_out(pretty(Transpose(Adjoint(X)))), "    T\\n/ +\\ \\n\\X / ")
  expect_identical(.pf_out(upretty(Adjoint(X))), " \u2020\\nX ")
  expect_identical(.pf_out(upretty(Adjoint(X + Y))), "       \u2020\\n(X + Y) ")
  expect_identical(.pf_out(upretty(Adjoint(X) + Adjoint(Y))), " \u2020    \u2020\\nX  + Y ")
  expect_identical(.pf_out(upretty(Adjoint(X * Y))), "     \u2020\\n(X\u22c5Y) ")
  expect_identical(.pf_out(upretty(Adjoint(Y) * Adjoint(X))), " \u2020  \u2020\\nY \u22c5X ")
  expect_identical(.pf_out(upretty(Adjoint(X ^ 2L))), "    \u2020\\n\u239b 2\u239e \\n\u239dX \u23a0 ")
  expect_identical(.pf_out(upretty(Adjoint(X) ^ 2L)), "    2\\n\u239b \u2020\u239e \\n\u239dX \u23a0 ")
  expect_identical(.pf_out(upretty(Adjoint(Inverse(X)))), "     \u2020\\n\u239b -1\u239e \\n\u239dX  \u23a0 ")
  expect_identical(.pf_out(upretty(Inverse(Adjoint(X)))), "    -1\\n\u239b \u2020\u239e  \\n\u239dX \u23a0  ")
  expect_identical(.pf_out(upretty(Adjoint(Transpose(X)))), "    \u2020\\n\u239b T\u239e \\n\u239dX \u23a0 ")
  expect_identical(.pf_out(upretty(Transpose(Adjoint(X)))), "    T\\n\u239b \u2020\u239e \\n\u239dX \u23a0 ")
  m <- Matrix(list(list(1L, 2L), list(3L, 4L)))
  expect_identical(.pf_out(upretty(Adjoint(m + X))), "            \u2020\\n\u239b\u23a11  2\u23a4    \u239e \\n\u239c\u23a2    \u23a5 + X\u239f \\n\u239d\u23a33  4\u23a6    \u23a0 ")
  expect_identical(.pf_out(upretty(Adjoint(BlockMatrix(list(list(OneMatrix(2L, 2L), X), list(m, ZeroMatrix(2L, 2L))))))), "           \u2020\\n\u23a1  \U{1d7d9}     X\u23a4 \\n\u23a2         \u23a5 \\n\u23a2\u23a11  2\u23a4   \u23a5 \\n\u23a2\u23a2    \u23a5  \U{1d7d8}\u23a5 \\n\u23a3\u23a33  4\u23a6   \u23a6 ")
})

test_that("pretty test_Transpose", {
  for (.n in c("a", "b", "c", "d", "x", "y", "z", "k", "n", "s", "p")) assign(.n, Symbol(.n))
  f <- Function("f"); th <- Symbol("theta"); ph <- Symbol("phi")
  .ppw <- function(e, u, order = NULL) if (inherits(e, "sym")) base::pretty(e, use_unicode = u, order = order) else if (inherits(e, "symmatrix")) base::pretty(e, use_unicode = u) else .pp2_doprint(e, u)
  pretty <- function(e, order = NULL) .ppw(e, FALSE, order)
  upretty <- function(e, order = NULL) .ppw(e, TRUE, order)
  X <- MatrixSymbol("X", 2L, 2L)
  Y <- MatrixSymbol("Y", 2L, 2L)
  expect_identical(.pf_out(pretty(Transpose(X))), " T\\nX ")
  expect_identical(.pf_out(pretty(Transpose(X + Y))), "       T\\n(X + Y) ")
  expect_identical(.pf_out(pretty(Transpose(X) + Transpose(Y))), " T    T\\nX  + Y ")
  expect_identical(.pf_out(pretty(Transpose(X * Y))), "     T\\n(X*Y) ")
  expect_identical(.pf_out(pretty(Transpose(Y) * Transpose(X))), " T  T\\nY *X ")
  expect_identical(.pf_out(pretty(Transpose(X ^ 2L))), "    T\\n/ 2\\ \\n\\X / ")
  expect_identical(.pf_out(pretty(Transpose(X) ^ 2L)), "    2\\n/ T\\ \\n\\X / ")
  expect_identical(.pf_out(pretty(Transpose(Inverse(X)))), "     T\\n/ -1\\ \\n\\X  / ")
  expect_identical(.pf_out(pretty(Inverse(Transpose(X)))), "    -1\\n/ T\\  \\n\\X /  ")
  expect_identical(.pf_out(upretty(Transpose(X))), " T\\nX ")
  expect_identical(.pf_out(upretty(Transpose(X + Y))), "       T\\n(X + Y) ")
  expect_identical(.pf_out(upretty(Transpose(X) + Transpose(Y))), " T    T\\nX  + Y ")
  expect_identical(.pf_out(upretty(Transpose(X * Y))), "     T\\n(X\u22c5Y) ")
  expect_identical(.pf_out(upretty(Transpose(Y) * Transpose(X))), " T  T\\nY \u22c5X ")
  expect_identical(.pf_out(upretty(Transpose(X ^ 2L))), "    T\\n\u239b 2\u239e \\n\u239dX \u23a0 ")
  expect_identical(.pf_out(upretty(Transpose(X) ^ 2L)), "    2\\n\u239b T\u239e \\n\u239dX \u23a0 ")
  expect_identical(.pf_out(upretty(Transpose(Inverse(X)))), "     T\\n\u239b -1\u239e \\n\u239dX  \u23a0 ")
  expect_identical(.pf_out(upretty(Inverse(Transpose(X)))), "    -1\\n\u239b T\u239e  \\n\u239dX \u23a0  ")
  m <- Matrix(list(list(1L, 2L), list(3L, 4L)))
  expect_identical(.pf_out(upretty(Transpose(m))), "      T\\n\u23a11  2\u23a4 \\n\u23a2    \u23a5 \\n\u23a33  4\u23a6 ")
  expect_identical(.pf_out(upretty(Transpose(m + X))), "            T\\n\u239b\u23a11  2\u23a4    \u239e \\n\u239c\u23a2    \u23a5 + X\u239f \\n\u239d\u23a33  4\u23a6    \u23a0 ")
  expect_identical(.pf_out(upretty(Transpose(BlockMatrix(list(list(OneMatrix(2L, 2L), X), list(m, ZeroMatrix(2L, 2L))))))), "           T\\n\u23a1  \U{1d7d9}     X\u23a4 \\n\u23a2         \u23a5 \\n\u23a2\u23a11  2\u23a4   \u23a5 \\n\u23a2\u23a2    \u23a5  \U{1d7d8}\u23a5 \\n\u23a3\u23a33  4\u23a6   \u23a6 ")
})

test_that("pretty test_pretty_Trace_issue_9044", {
  for (.n in c("a", "b", "c", "d", "x", "y", "z", "k", "n", "s", "p")) assign(.n, Symbol(.n))
  f <- Function("f"); th <- Symbol("theta"); ph <- Symbol("phi")
  .ppw <- function(e, u, order = NULL) if (inherits(e, "sym")) base::pretty(e, use_unicode = u, order = order) else if (inherits(e, "symmatrix")) base::pretty(e, use_unicode = u) else .pp2_doprint(e, u)
  pretty <- function(e, order = NULL) .ppw(e, FALSE, order)
  upretty <- function(e, order = NULL) .ppw(e, TRUE, order)
  X <- Matrix(list(list(1L, 2L), list(3L, 4L)))
  Y <- Matrix(list(list(2L, 4L), list(6L, 8L)))
  ascii_str_1 <- "  /[1  2]\\\ntr|[    ]|\n  \\[3  4]/"
  ucode_str_1 <- "  \u239b\u23a11  2\u23a4\u239e\ntr\u239c\u23a2    \u23a5\u239f\n  \u239d\u23a33  4\u23a6\u23a0"
  ascii_str_2 <- "  /[1  2]\\     /[2  4]\\\ntr|[    ]| + tr|[    ]|\n  \\[3  4]/     \\[6  8]/"
  ucode_str_2 <- "  \u239b\u23a11  2\u23a4\u239e     \u239b\u23a12  4\u23a4\u239e\ntr\u239c\u23a2    \u23a5\u239f + tr\u239c\u23a2    \u23a5\u239f\n  \u239d\u23a33  4\u23a6\u23a0     \u239d\u23a36  8\u23a6\u23a0"
  expect_identical(.pf_out(pretty(Trace(X))), "  /[1  2]\\\\ntr|[    ]|\\n  \\[3  4]/")
  expect_identical(.pf_out(upretty(Trace(X))), "  \u239b\u23a11  2\u23a4\u239e\\ntr\u239c\u23a2    \u23a5\u239f\\n  \u239d\u23a33  4\u23a6\u23a0")
  expect_identical(.pf_out(pretty(Trace(X) + Trace(Y))), "  /[1  2]\\     /[2  4]\\\\ntr|[    ]| + tr|[    ]|\\n  \\[3  4]/     \\[6  8]/")
  expect_identical(.pf_out(upretty(Trace(X) + Trace(Y))), "  \u239b\u23a11  2\u23a4\u239e     \u239b\u23a12  4\u23a4\u239e\\ntr\u239c\u23a2    \u23a5\u239f + tr\u239c\u23a2    \u23a5\u239f\\n  \u239d\u23a33  4\u23a6\u23a0     \u239d\u23a36  8\u23a6\u23a0")
})

