test_that("pretty test_pretty_Determinant", {
  for (.n in c("a", "b", "c", "d", "x", "y", "z", "k", "n", "s", "p")) assign(.n, Symbol(.n))
  f <- Function("f"); th <- Symbol("theta"); ph <- Symbol("phi")
  .ppw <- function(e, u, order = NULL) if (inherits(e, "sym")) base::pretty(e, use_unicode = u, order = order) else if (inherits(e, "symmatrix")) base::pretty(e, use_unicode = u) else .pp2_doprint(e, u)
  pretty <- function(e, order = NULL) .ppw(e, FALSE, order)
  upretty <- function(e, order = NULL) .ppw(e, TRUE, order)
  m <- Matrix(list(list(1L, 2L), list(3L, 4L)))
  X <- MatrixSymbol("X", 2L, 2L)
  expect_identical(.pf_out(upretty(Determinant(X))), "\u2502X\u2502")
  expect_identical(.pf_out(upretty(Determinant(X + m))), "\u2502\u23a11  2\u23a4    \u2502\\n\u2502\u23a2    \u23a5 + X\u2502\\n\u2502\u23a33  4\u23a6    \u2502")
  expect_identical(.pf_out(upretty(Determinant(BlockMatrix(list(list(OneMatrix(2L, 2L), X), list(m, ZeroMatrix(2L, 2L))))))), "\u2502  \U{1d7d9}     X\u2502\\n\u2502         \u2502\\n\u2502\u23a11  2\u23a4   \u2502\\n\u2502\u23a2    \u23a5  \U{1d7d8}\u2502\\n\u2502\u23a33  4\u23a6   \u2502")
})

test_that("pretty test_pretty_piecewise", {
  for (.n in c("a", "b", "c", "d", "x", "y", "z", "k", "n", "s", "p")) assign(.n, Symbol(.n))
  f <- Function("f"); th <- Symbol("theta"); ph <- Symbol("phi")
  .ppw <- function(e, u, order = NULL) if (inherits(e, "sym")) base::pretty(e, use_unicode = u, order = order) else if (inherits(e, "symmatrix")) base::pretty(e, use_unicode = u) else .pp2_doprint(e, u)
  pretty <- function(e, order = NULL) .ppw(e, FALSE, order)
  upretty <- function(e, order = NULL) .ppw(e, TRUE, order)
  expr <- Piecewise(list(x, x < 1L), list(x ^ 2L, TRUE))
  ascii_str <- "/x   for x < 1\n|             \n< 2           \n|x   otherwise\n\\             "
  ucode_str <- "\u23a7x   for x < 1\n\u23aa             \n\u23a8 2           \n\u23aax   otherwise\n\u23a9             "
  expect_identical(.pf_out(pretty(expr)), "/x   for x < 1\\n|             \\n< 2           \\n|x   otherwise\\n\\             ")
  expect_identical(.pf_out(upretty(expr)), "\u23a7x   for x < 1\\n\u23aa             \\n\u23a8 2           \\n\u23aax   otherwise\\n\u23a9             ")
  expr <- -Piecewise(list(x, x < 1L), list(x ^ 2L, TRUE))
  ascii_str <- " //x   for x < 1\\\n ||             |\n-|< 2           |\n ||x   otherwise|\n \\\\             /"
  ucode_str <- " \u239b\u23a7x   for x < 1\u239e\n \u239c\u23aa             \u239f\n-\u239c\u23a8 2           \u239f\n \u239c\u23aax   otherwise\u239f\n \u239d\u23a9             \u23a0"
  expect_identical(.pf_out(pretty(expr)), " //x   for x < 1\\\\n ||             |\\n-|< 2           |\\n ||x   otherwise|\\n \\\\             /")
  expect_identical(.pf_out(upretty(expr)), " \u239b\u23a7x   for x < 1\u239e\\n \u239c\u23aa             \u239f\\n-\u239c\u23a8 2           \u239f\\n \u239c\u23aax   otherwise\u239f\\n \u239d\u23a9             \u23a0")
  expr <- ((x + Piecewise(list(x, x > 0L), list(y, TRUE))) + Piecewise(list(x / y, x < 2L), list(y ^ 2L, x > 2L), list(1L, TRUE))) + 1L
  ascii_str <- "                      //x            \\    \n                      ||-   for x < 2|    \n                      ||y            |    \n    //x  for x > 0\\   ||             |    \nx + |<            | + |< 2           | + 1\n    \\\\y  otherwise/   ||y   for x > 2|    \n                      ||             |    \n                      ||1   otherwise|    \n                      \\\\             /    "
  ucode_str <- "                      \u239b\u23a7x            \u239e    \n                      \u239c\u23aa\u2500   for x < 2\u239f    \n                      \u239c\u23aay            \u239f    \n    \u239b\u23a7x  for x > 0\u239e   \u239c\u23aa             \u239f    \nx + \u239c\u23a8            \u239f + \u239c\u23a8 2           \u239f + 1\n    \u239d\u23a9y  otherwise\u23a0   \u239c\u23aay   for x > 2\u239f    \n                      \u239c\u23aa             \u239f    \n                      \u239c\u23aa1   otherwise\u239f    \n                      \u239d\u23a9             \u23a0    "
  expect_identical(.pf_out(pretty(expr)), "                      //x            \\    \\n                      ||-   for x < 2|    \\n                      ||y            |    \\n    //x  for x > 0\\   ||             |    \\nx + |<            | + |< 2           | + 1\\n    \\\\y  otherwise/   ||y   for x > 2|    \\n                      ||             |    \\n                      ||1   otherwise|    \\n                      \\\\             /    ")
  expect_identical(.pf_out(upretty(expr)), "                      \u239b\u23a7x            \u239e    \\n                      \u239c\u23aa\u2500   for x < 2\u239f    \\n                      \u239c\u23aay            \u239f    \\n    \u239b\u23a7x  for x > 0\u239e   \u239c\u23aa             \u239f    \\nx + \u239c\u23a8            \u239f + \u239c\u23a8 2           \u239f + 1\\n    \u239d\u23a9y  otherwise\u23a0   \u239c\u23aay   for x > 2\u239f    \\n                      \u239c\u23aa             \u239f    \\n                      \u239c\u23aa1   otherwise\u239f    \\n                      \u239d\u23a9             \u23a0    ")
  expr <- ((x - Piecewise(list(x, x > 0L), list(y, TRUE))) + Piecewise(list(x / y, x < 2L), list(y ^ 2L, x > 2L), list(1L, TRUE))) + 1L
  ascii_str <- "                      //x            \\    \n                      ||-   for x < 2|    \n                      ||y            |    \n    //x  for x > 0\\   ||             |    \nx - |<            | + |< 2           | + 1\n    \\\\y  otherwise/   ||y   for x > 2|    \n                      ||             |    \n                      ||1   otherwise|    \n                      \\\\             /    "
  ucode_str <- "                      \u239b\u23a7x            \u239e    \n                      \u239c\u23aa\u2500   for x < 2\u239f    \n                      \u239c\u23aay            \u239f    \n    \u239b\u23a7x  for x > 0\u239e   \u239c\u23aa             \u239f    \nx - \u239c\u23a8            \u239f + \u239c\u23a8 2           \u239f + 1\n    \u239d\u23a9y  otherwise\u23a0   \u239c\u23aay   for x > 2\u239f    \n                      \u239c\u23aa             \u239f    \n                      \u239c\u23aa1   otherwise\u239f    \n                      \u239d\u23a9             \u23a0    "
  expect_identical(.pf_out(pretty(expr)), "                      //x            \\    \\n                      ||-   for x < 2|    \\n                      ||y            |    \\n    //x  for x > 0\\   ||             |    \\nx - |<            | + |< 2           | + 1\\n    \\\\y  otherwise/   ||y   for x > 2|    \\n                      ||             |    \\n                      ||1   otherwise|    \\n                      \\\\             /    ")
  expect_identical(.pf_out(upretty(expr)), "                      \u239b\u23a7x            \u239e    \\n                      \u239c\u23aa\u2500   for x < 2\u239f    \\n                      \u239c\u23aay            \u239f    \\n    \u239b\u23a7x  for x > 0\u239e   \u239c\u23aa             \u239f    \\nx - \u239c\u23a8            \u239f + \u239c\u23a8 2           \u239f + 1\\n    \u239d\u23a9y  otherwise\u23a0   \u239c\u23aay   for x > 2\u239f    \\n                      \u239c\u23aa             \u239f    \\n                      \u239c\u23aa1   otherwise\u239f    \\n                      \u239d\u23a9             \u23a0    ")
  expr <- x * Piecewise(list(x, x > 0L), list(y, TRUE))
  ascii_str <- "  //x  for x > 0\\\nx*|<            |\n  \\\\y  otherwise/"
  ucode_str <- "  \u239b\u23a7x  for x > 0\u239e\nx\u22c5\u239c\u23a8            \u239f\n  \u239d\u23a9y  otherwise\u23a0"
  expect_identical(.pf_out(pretty(expr)), "  //x  for x > 0\\\\nx*|<            |\\n  \\\\y  otherwise/")
  expect_identical(.pf_out(upretty(expr)), "  \u239b\u23a7x  for x > 0\u239e\\nx\u22c5\u239c\u23a8            \u239f\\n  \u239d\u23a9y  otherwise\u23a0")
  expr <- Piecewise(list(x, x > 0L), list(y, TRUE)) * Piecewise(list(x / y, x < 2L), list(y ^ 2L, x > 2L), list(1L, TRUE))
  ascii_str <- "                //x            \\\n                ||-   for x < 2|\n                ||y            |\n//x  for x > 0\\ ||             |\n|<            |*|< 2           |\n\\\\y  otherwise/ ||y   for x > 2|\n                ||             |\n                ||1   otherwise|\n                \\\\             /"
  ucode_str <- "                \u239b\u23a7x            \u239e\n                \u239c\u23aa\u2500   for x < 2\u239f\n                \u239c\u23aay            \u239f\n\u239b\u23a7x  for x > 0\u239e \u239c\u23aa             \u239f\n\u239c\u23a8            \u239f\u22c5\u239c\u23a8 2           \u239f\n\u239d\u23a9y  otherwise\u23a0 \u239c\u23aay   for x > 2\u239f\n                \u239c\u23aa             \u239f\n                \u239c\u23aa1   otherwise\u239f\n                \u239d\u23a9             \u23a0"
  expect_identical(.pf_out(pretty(expr)), "                //x            \\\\n                ||-   for x < 2|\\n                ||y            |\\n//x  for x > 0\\ ||             |\\n|<            |*|< 2           |\\n\\\\y  otherwise/ ||y   for x > 2|\\n                ||             |\\n                ||1   otherwise|\\n                \\\\             /")
  expect_identical(.pf_out(upretty(expr)), "                \u239b\u23a7x            \u239e\\n                \u239c\u23aa\u2500   for x < 2\u239f\\n                \u239c\u23aay            \u239f\\n\u239b\u23a7x  for x > 0\u239e \u239c\u23aa             \u239f\\n\u239c\u23a8            \u239f\u22c5\u239c\u23a8 2           \u239f\\n\u239d\u23a9y  otherwise\u23a0 \u239c\u23aay   for x > 2\u239f\\n                \u239c\u23aa             \u239f\\n                \u239c\u23aa1   otherwise\u239f\\n                \u239d\u23a9             \u23a0")
  expr <- (-Piecewise(list(x, x > 0L), list(y, TRUE))) * Piecewise(list(x / y, x < 2L), list(y ^ 2L, x > 2L), list(1L, TRUE))
  ascii_str <- "                 //x            \\\n                 ||-   for x < 2|\n                 ||y            |\n //x  for x > 0\\ ||             |\n-|<            |*|< 2           |\n \\\\y  otherwise/ ||y   for x > 2|\n                 ||             |\n                 ||1   otherwise|\n                 \\\\             /"
  ucode_str <- "                 \u239b\u23a7x            \u239e\n                 \u239c\u23aa\u2500   for x < 2\u239f\n                 \u239c\u23aay            \u239f\n \u239b\u23a7x  for x > 0\u239e \u239c\u23aa             \u239f\n-\u239c\u23a8            \u239f\u22c5\u239c\u23a8 2           \u239f\n \u239d\u23a9y  otherwise\u23a0 \u239c\u23aay   for x > 2\u239f\n                 \u239c\u23aa             \u239f\n                 \u239c\u23aa1   otherwise\u239f\n                 \u239d\u23a9             \u23a0"
  expect_identical(.pf_out(pretty(expr)), "                 //x            \\\\n                 ||-   for x < 2|\\n                 ||y            |\\n //x  for x > 0\\ ||             |\\n-|<            |*|< 2           |\\n \\\\y  otherwise/ ||y   for x > 2|\\n                 ||             |\\n                 ||1   otherwise|\\n                 \\\\             /")
  expect_identical(.pf_out(upretty(expr)), "                 \u239b\u23a7x            \u239e\\n                 \u239c\u23aa\u2500   for x < 2\u239f\\n                 \u239c\u23aay            \u239f\\n \u239b\u23a7x  for x > 0\u239e \u239c\u23aa             \u239f\\n-\u239c\u23a8            \u239f\u22c5\u239c\u23a8 2           \u239f\\n \u239d\u23a9y  otherwise\u23a0 \u239c\u23aay   for x > 2\u239f\\n                 \u239c\u23aa             \u239f\\n                 \u239c\u23aa1   otherwise\u239f\\n                 \u239d\u23a9             \u23a0")
  expr <- Piecewise(list(0L, Abs(1L / y) < 1L), list(1L, Abs(y) < 1L), list(y * meijerg(list(list(2L, 1L), list()), list(list(), list(1L, 0L)), 1L / y), TRUE))
  ascii_str <- "/                                 1     \n|            0               for --- < 1\n|                                |y|    \n|                                       \n<            1               for |y| < 1\n|                                       \n|   __0, 2 /1, 2       | 1\\             \n|y*/__     |           | -|   otherwise \n\\  \\_|2, 2 \\      0, 1 | y/             "
  ucode_str <- "\u23a7                                 1     \n\u23aa            0               for \u2500\u2500\u2500 < 1\n\u23aa                                \u2502y\u2502    \n\u23aa                                       \n\u23a8            1               for \u2502y\u2502 < 1\n\u23aa                                       \n\u23aa  \u256d\u2500\u256e0, 2 \u239b1, 2       \u2502 1\u239e             \n\u23aay\u22c5\u2502\u2576\u2510     \u239c           \u2502 \u2500\u239f   otherwise \n\u23a9  \u2570\u2500\u256f2, 2 \u239d      0, 1 \u2502 y\u23a0             "
  expect_identical(.pf_out(pretty(expr)), "/                                 1     \\n|            0               for --- < 1\\n|                                |y|    \\n|                                       \\n<            1               for |y| < 1\\n|                                       \\n|   __0, 2 /1, 2       | 1\\             \\n|y*/__     |           | -|   otherwise \\n\\  \\_|2, 2 \\      0, 1 | y/             ")
  expect_identical(.pf_out(upretty(expr)), "\u23a7                                 1     \\n\u23aa            0               for \u2500\u2500\u2500 < 1\\n\u23aa                                \u2502y\u2502    \\n\u23aa                                       \\n\u23a8            1               for \u2502y\u2502 < 1\\n\u23aa                                       \\n\u23aa  \u256d\u2500\u256e0, 2 \u239b1, 2       \u2502 1\u239e             \\n\u23aay\u22c5\u2502\u2576\u2510     \u239c           \u2502 \u2500\u239f   otherwise \\n\u23a9  \u2570\u2500\u256f2, 2 \u239d      0, 1 \u2502 y\u23a0             ")
  expr <- Pow(Piecewise(list(x, x > 0L), list(y, TRUE)), 2L, evaluate = FALSE)
  ascii_str <- "               2\n//x  for x > 0\\ \n|<            | \n\\\\y  otherwise/ "
  ucode_str <- "               2\n\u239b\u23a7x  for x > 0\u239e \n\u239c\u23a8            \u239f \n\u239d\u23a9y  otherwise\u23a0 "
  expect_identical(.pf_out(pretty(expr)), "               2\\n//x  for x > 0\\ \\n|<            | \\n\\\\y  otherwise/ ")
  expect_identical(.pf_out(upretty(expr)), "               2\\n\u239b\u23a7x  for x > 0\u239e \\n\u239c\u23a8            \u239f \\n\u239d\u23a9y  otherwise\u23a0 ")
})

test_that("pretty test_pretty_ITE", {
  for (.n in c("a", "b", "c", "d", "x", "y", "z", "k", "n", "s", "p")) assign(.n, Symbol(.n))
  f <- Function("f"); th <- Symbol("theta"); ph <- Symbol("phi")
  .ppw <- function(e, u, order = NULL) if (inherits(e, "sym")) base::pretty(e, use_unicode = u, order = order) else if (inherits(e, "symmatrix")) base::pretty(e, use_unicode = u) else .pp2_doprint(e, u)
  pretty <- function(e, order = NULL) .ppw(e, FALSE, order)
  upretty <- function(e, order = NULL) .ppw(e, TRUE, order)
  expr <- ITE(x, y, z)
  expect_identical(.pf_out(pretty(expr)), "/y    for x  \\n<            \\n\\z  otherwise")
  expect_identical(.pf_out(upretty(expr)), "\u23a7y    for x  \\n\u23a8            \\n\u23a9z  otherwise")
})

test_that("pretty test_pretty_seq", {
  for (.n in c("a", "b", "c", "d", "x", "y", "z", "k", "n", "s", "p")) assign(.n, Symbol(.n))
  f <- Function("f"); th <- Symbol("theta"); ph <- Symbol("phi")
  .ppw <- function(e, u, order = NULL) if (inherits(e, "sym")) base::pretty(e, use_unicode = u, order = order) else if (inherits(e, "symmatrix")) base::pretty(e, use_unicode = u) else .pp2_doprint(e, u)
  pretty <- function(e, order = NULL) .ppw(e, FALSE, order)
  upretty <- function(e, order = NULL) .ppw(e, TRUE, order)
  try(expr <- list(), silent = TRUE)
  try(ascii_str <- "()", silent = TRUE)
  try(ucode_str <- "()", silent = TRUE)
  try(expr <- list(), silent = TRUE)
  try(ascii_str <- "[]", silent = TRUE)
  try(ucode_str <- "[]", silent = TRUE)
  expect_identical(.pf_out(pretty(expr)), "[]")
  expect_identical(.pf_out(upretty(expr)), "[]")
  try(expr <- Dict(list(), list()), silent = TRUE)
  try(expr_2 <- Dict(list(), list()), silent = TRUE)
  try(ascii_str <- "{}", silent = TRUE)
  try(ucode_str <- "{}", silent = TRUE)
  expect_identical(.pf_out(pretty(expr)), "{}")
  expect_identical(.pf_out(pretty(expr_2)), "{}")
  expect_identical(.pf_out(upretty(expr)), "{}")
  expect_identical(.pf_out(upretty(expr_2)), "{}")
  try(expr <- list(1L / x), silent = TRUE)
  try(ascii_str <- " 1  \n(-,)\n x  ", silent = TRUE)
  try(ucode_str <- "\u239b1 \u239e\n\u239c\u2500,\u239f\n\u239dx \u23a0", silent = TRUE)
  try(expr <- list(x ^ 2L, 1L / x, x, y, (sin(th) ^ 2L) / (cos(ph) ^ 2L)), silent = TRUE)
  try(ascii_str <- "                 2        \n  2  1        sin (theta) \n[x , -, x, y, -----------]\n     x            2       \n               cos (phi)  ", silent = TRUE)
  try(ucode_str <- "\u23a1                2   \u23a4\n\u23a2 2  1        sin (\u03b8)\u23a5\n\u23a2x , \u2500, x, y, \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u23a5\n\u23a2    x           2   \u23a5\n\u23a3             cos (\u03c6)\u23a6", silent = TRUE)
  expect_identical(.pf_out(pretty(expr)), "                 2        \\n  2  1        sin (theta) \\n[x , -, x, y, -----------]\\n     x            2       \\n               cos (phi)  ")
  expect_identical(.pf_out(upretty(expr)), "\u23a1                2   \u23a4\\n\u23a2 2  1        sin (\u03b8)\u23a5\\n\u23a2x , \u2500, x, y, \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u23a5\\n\u23a2    x           2   \u23a5\\n\u23a3             cos (\u03c6)\u23a6")
  try(expr <- list(x ^ 2L, 1L / x, x, y, (sin(th) ^ 2L) / (cos(ph) ^ 2L)), silent = TRUE)
  try(ascii_str <- "                 2        \n  2  1        sin (theta) \n(x , -, x, y, -----------)\n     x            2       \n               cos (phi)  ", silent = TRUE)
  try(ucode_str <- "\u239b                2   \u239e\n\u239c 2  1        sin (\u03b8)\u239f\n\u239cx , \u2500, x, y, \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u239f\n\u239c    x           2   \u239f\n\u239d             cos (\u03c6)\u23a0", silent = TRUE)
  try(expr <- Tuple(x ^ 2L, 1L / x, x, y, (sin(th) ^ 2L) / (cos(ph) ^ 2L)), silent = TRUE)
  try(ascii_str <- "                 2        \n  2  1        sin (theta) \n(x , -, x, y, -----------)\n     x            2       \n               cos (phi)  ", silent = TRUE)
  try(ucode_str <- "\u239b                2   \u239e\n\u239c 2  1        sin (\u03b8)\u239f\n\u239cx , \u2500, x, y, \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u239f\n\u239c    x           2   \u239f\n\u239d             cos (\u03c6)\u23a0", silent = TRUE)
  expect_identical(.pf_out(pretty(expr)), "                 2        \\n  2  1        sin (theta) \\n(x , -, x, y, -----------)\\n     x            2       \\n               cos (phi)  ")
  expect_identical(.pf_out(upretty(expr)), "\u239b                2   \u239e\\n\u239c 2  1        sin (\u03b8)\u239f\\n\u239cx , \u2500, x, y, \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u239f\\n\u239c    x           2   \u239f\\n\u239d             cos (\u03c6)\u23a0")
  try(expr <- Dict(list(x), list(sin(x))), silent = TRUE)
  try(expr_2 <- Dict(Dict(list(x), list(sin(x)))), silent = TRUE)
  try(ascii_str <- "{x: sin(x)}", silent = TRUE)
  try(ucode_str <- "{x: sin(x)}", silent = TRUE)
  expect_identical(.pf_out(pretty(expr)), "{x: sin(x)}")
  expect_identical(.pf_out(upretty(expr)), "{x: sin(x)}")
  try(expr <- Dict(list(1L / x, x), list(1L / y, sin(x) ^ 2L)), silent = TRUE)
  try(expr_2 <- Dict(Dict(list(1L / x, x), list(1L / y, sin(x) ^ 2L))), silent = TRUE)
  try(ascii_str <- " 1  1        2    \n{-: -, x: sin (x)}\n x  y             ", silent = TRUE)
  try(ucode_str <- "\u23a71  1        2   \u23ab\n\u23a8\u2500: \u2500, x: sin (x)\u23ac\n\u23a9x  y            \u23ad", silent = TRUE)
  expect_identical(.pf_out(pretty(expr)), " 1  1        2    \\n{-: -, x: sin (x)}\\n x  y             ")
  expect_identical(.pf_out(upretty(expr)), "\u23a71  1        2   \u23ab\\n\u23a8\u2500: \u2500, x: sin (x)\u23ac\\n\u23a9x  y            \u23ad")
  try(expr <- list(x ^ 2L), silent = TRUE)
  try(ascii_str <- "  2 \n[x ]", silent = TRUE)
  try(ucode_str <- "\u23a1 2\u23a4\n\u23a3x \u23a6", silent = TRUE)
  expect_identical(.pf_out(pretty(expr)), "  2 \\n[x ]")
  expect_identical(.pf_out(upretty(expr)), "\u23a1 2\u23a4\\n\u23a3x \u23a6")
  try(expr <- list(x ^ 2L), silent = TRUE)
  try(ascii_str <- "  2  \n(x ,)", silent = TRUE)
  try(ucode_str <- "\u239b 2 \u239e\n\u239dx ,\u23a0", silent = TRUE)
  try(expr <- Tuple(x ^ 2L), silent = TRUE)
  try(ascii_str <- "  2  \n(x ,)", silent = TRUE)
  try(ucode_str <- "\u239b 2 \u239e\n\u239dx ,\u23a0", silent = TRUE)
  expect_identical(.pf_out(pretty(expr)), "  2  \\n(x ,)")
  expect_identical(.pf_out(upretty(expr)), "\u239b 2 \u239e\\n\u239dx ,\u23a0")
  try(expr <- Dict(list(x ^ 2L), list(1L)), silent = TRUE)
  try(expr_2 <- Dict(Dict(list(x ^ 2L), list(1L))), silent = TRUE)
  try(ascii_str <- "  2    \n{x : 1}", silent = TRUE)
  try(ucode_str <- "\u23a7 2   \u23ab\n\u23a8x : 1\u23ac\n\u23a9     \u23ad", silent = TRUE)
  expect_identical(.pf_out(pretty(expr)), "  2    \\n{x : 1}")
  expect_identical(.pf_out(upretty(expr)), "\u23a7 2   \u23ab\\n\u23a8x : 1\u23ac\\n\u23a9     \u23ad")
})

test_that("pretty test_pretty_sets", {
  for (.n in c("a", "b", "c", "d", "x", "y", "z", "k", "n", "s", "p")) assign(.n, Symbol(.n))
  f <- Function("f"); th <- Symbol("theta"); ph <- Symbol("phi")
  .ppw <- function(e, u, order = NULL) if (inherits(e, "sym")) base::pretty(e, use_unicode = u, order = order) else if (inherits(e, "symmatrix")) base::pretty(e, use_unicode = u) else .pp2_doprint(e, u)
  pretty <- function(e, order = NULL) .ppw(e, FALSE, order)
  upretty <- function(e, order = NULL) .ppw(e, TRUE, order)
  s <- FiniteSet
  expect_identical(.pf_out(pretty(Range(0L, 3L, 1L))), "{0, 1, 2}")
  ascii_str <- "{0, 1, ..., 29}"
  ucode_str <- "{0, 1, \u2026, 29}"
  expect_identical(.pf_out(pretty(Range(0L, 30L, 1L))), "{0, 1, ..., 29}")
  expect_identical(.pf_out(upretty(Range(0L, 30L, 1L))), "{0, 1, \u2026, 29}")
  ascii_str <- "{30, 29, ..., 2}"
  ucode_str <- "{30, 29, \u2026, 2}"
  expect_identical(.pf_out(pretty(Range(30L, 1L, -1L))), "{30, 29, ..., 2}")
  expect_identical(.pf_out(upretty(Range(30L, 1L, -1L))), "{30, 29, \u2026, 2}")
  ascii_str <- "{0, 2, ...}"
  ucode_str <- "{0, 2, \u2026}"
  expect_identical(.pf_out(pretty(Range(0L, oo, 2L))), "{0, 2, ...}")
  expect_identical(.pf_out(upretty(Range(0L, oo, 2L))), "{0, 2, \u2026}")
  ascii_str <- "{..., 2, 0}"
  ucode_str <- "{\u2026, 2, 0}"
  expect_identical(.pf_out(pretty(Range(oo, -2L, -2L))), "{..., 2, 0}")
  expect_identical(.pf_out(upretty(Range(oo, -2L, -2L))), "{\u2026, 2, 0}")
  ascii_str <- "{-2, -3, ...}"
  ucode_str <- "{-2, -3, \u2026}"
  expect_identical(.pf_out(pretty(Range(-2L, -oo, -1L))), "{-2, -3, ...}")
  expect_identical(.pf_out(upretty(Range(-2L, -oo, -1L))), "{-2, -3, \u2026}")
})

test_that("pretty test_pretty_ImageSet", {
  for (.n in c("a", "b", "c", "d", "x", "y", "z", "k", "n", "s", "p")) assign(.n, Symbol(.n))
  f <- Function("f"); th <- Symbol("theta"); ph <- Symbol("phi")
  .ppw <- function(e, u, order = NULL) if (inherits(e, "sym")) base::pretty(e, use_unicode = u, order = order) else if (inherits(e, "symmatrix")) base::pretty(e, use_unicode = u) else .pp2_doprint(e, u)
  pretty <- function(e, order = NULL) .ppw(e, FALSE, order)
  upretty <- function(e, order = NULL) .ppw(e, TRUE, order)
  try(imgset <- ImageSet(Lambda(list(x, y), x + y), list(1L, 2L, 3L), list(3L, 4L)), silent = TRUE)
  try(ascii_str <- "{x + y | x in {1, 2, 3}, y in {3, 4}}", silent = TRUE)
  try(ucode_str <- "{x + y \u2502 x \u220a {1, 2, 3}, y \u220a {3, 4}}", silent = TRUE)
  try(imgset <- ImageSet(Lambda(list(list(x, y)), x + y), ProductSet(list(1L, 2L, 3L), list(3L, 4L))), silent = TRUE)
  try(ascii_str <- "{x + y | (x, y) in {1, 2, 3} x {3, 4}}", silent = TRUE)
  try(ucode_str <- "{x + y \u2502 (x, y) \u220a {1, 2, 3} \u00d7 {3, 4}}", silent = TRUE)
  try(imgset <- ImageSet(Lambda(x, x ^ 2L), Naturals), silent = TRUE)
  try(ascii_str <- "  2                 \n{x  | x in Naturals}", silent = TRUE)
  try(ucode_str <- "\u23a7 2 \u2502      \u23ab\n\u23a8x  \u2502 x \u220a \u2115\u23ac\n\u23a9   \u2502      \u23ad", silent = TRUE)
  expect_identical(.pf_out(pretty(imgset)), "  2                 \\n{x  | x in Naturals}")
  expect_identical(.pf_out(upretty(imgset)), "\u23a7 2 \u2502      \u23ab\\n\u23a8x  \u2502 x \u220a \u2115\u23ac\\n\u23a9   \u2502      \u23ad")
  try(imgset <- ImageSet(Lambda(x, 1L / (x ^ 2L)), Naturals), silent = TRUE)
  try(ascii_str <- " 1                  \n{-- | x in Naturals}\n  2                 \n x                  ", silent = TRUE)
  try(ucode_str <- "\u23a71  \u2502      \u23ab\n\u23aa\u2500\u2500 \u2502 x \u220a \u2115\u23aa\n\u23a8 2 \u2502      \u23ac\n\u23aax  \u2502      \u23aa\n\u23a9   \u2502      \u23ad", silent = TRUE)
  expect_identical(.pf_out(pretty(imgset)), " 1                  \\n{-- | x in Naturals}\\n  2                 \\n x                  ")
  expect_identical(.pf_out(upretty(imgset)), "\u23a71  \u2502      \u23ab\\n\u23aa\u2500\u2500 \u2502 x \u220a \u2115\u23aa\\n\u23a8 2 \u2502      \u23ac\\n\u23aax  \u2502      \u23aa\\n\u23a9   \u2502      \u23ad")
  try(imgset <- ImageSet(Lambda(list(x, y), 1L / ((x + y) ^ 2L)), Naturals, Naturals), silent = TRUE)
  try(ascii_str <- "    1                                    \n{-------- | x in Naturals, y in Naturals}\n        2                                \n (x + y)                                 ", silent = TRUE)
  try(ucode_str <- "\u23a7   1     \u2502             \u23ab\n\u23aa\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 \u2502 x \u220a \u2115, y \u220a \u2115\u23aa\n\u23a8       2 \u2502             \u23ac\n\u23aa(x + y)  \u2502             \u23aa\n\u23a9         \u2502             \u23ad", silent = TRUE)
  expect_identical(.pf_out(pretty(imgset)), "    1                                    \\n{-------- | x in Naturals, y in Naturals}\\n        2                                \\n (x + y)                                 ")
  expect_identical(.pf_out(upretty(imgset)), "\u23a7   1     \u2502             \u23ab\\n\u23aa\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 \u2502 x \u220a \u2115, y \u220a \u2115\u23aa\\n\u23a8       2 \u2502             \u23ac\\n\u23aa(x + y)  \u2502             \u23aa\\n\u23a9         \u2502             \u23ad")
  expect_identical(.pf_out(upretty(list(Symbol("ihat") / (Symbol("i") + 1L)))), "\u23a1  i\u0302  \u23a4\\n\u23a2\u2500\u2500\u2500\u2500\u2500\u23a5\\n\u23a3i + 1\u23a6")
  expect_identical(.pf_out(upretty(Matrix(list(Symbol("ihat"), Symbol("i") + 1L)))), "\u23a1  i\u0302  \u23a4\\n\u23a2     \u23a5\\n\u23a3i + 1\u23a6")
})

test_that("pretty test_pretty_ConditionSet", {
  for (.n in c("a", "b", "c", "d", "x", "y", "z", "k", "n", "s", "p")) assign(.n, Symbol(.n))
  f <- Function("f"); th <- Symbol("theta"); ph <- Symbol("phi")
  .ppw <- function(e, u, order = NULL) if (inherits(e, "sym")) base::pretty(e, use_unicode = u, order = order) else if (inherits(e, "symmatrix")) base::pretty(e, use_unicode = u) else .pp2_doprint(e, u)
  pretty <- function(e, order = NULL) .ppw(e, FALSE, order)
  upretty <- function(e, order = NULL) .ppw(e, TRUE, order)
  ascii_str <- "{x | x in (-oo, oo) and sin(x) = 0}"
  ucode_str <- "{x \u2502 x \u220a \u211d \u2227 (sin(x) = 0)}"
  expect_identical(.pf_out(pretty(ConditionSet(x, Eq(sin(x), 0L), Reals))), "{x | x in (-oo, oo) and sin(x) = 0}")
  expect_identical(.pf_out(upretty(ConditionSet(x, Eq(sin(x), 0L), Reals))), "{x \u2502 x \u220a \u211d \u2227 (sin(x) = 0)}")
  expect_identical(.pf_out(pretty(ConditionSet(x, And(x > 1L, x < (-1L)), FiniteSet(1L, 2L, 3L)))), "EmptySet")
  expect_identical(.pf_out(upretty(ConditionSet(x, And(x > 1L, x < (-1L)), FiniteSet(1L, 2L, 3L)))), "\u2205")
  expect_identical(.pf_out(pretty(ConditionSet(x, Or(x > 1L, x < (-1L)), FiniteSet(1L, 2L)))), "{2}")
  expect_identical(.pf_out(upretty(ConditionSet(x, Or(x > 1L, x < (-1L)), FiniteSet(1L, 2L)))), "{2}")
  condset <- ConditionSet(x, (1L / (x ^ 2L)) > 0L)
  ascii_str <- "     1      \n{x | -- > 0}\n      2     \n     x      "
  ucode_str <- "\u23a7  \u2502 \u239b1     \u239e\u23ab\n\u23aax \u2502 \u239c\u2500\u2500 > 0\u239f\u23aa\n\u23a8  \u2502 \u239c 2    \u239f\u23ac\n\u23aa  \u2502 \u239dx     \u23a0\u23aa\n\u23a9  \u2502         \u23ad"
  expect_identical(.pf_out(pretty(condset)), "     1      \\n{x | -- > 0}\\n      2     \\n     x      ")
  expect_identical(.pf_out(upretty(condset)), "\u23a7  \u2502 \u239b1     \u239e\u23ab\\n\u23aax \u2502 \u239c\u2500\u2500 > 0\u239f\u23aa\\n\u23a8  \u2502 \u239c 2    \u239f\u23ac\\n\u23aa  \u2502 \u239dx     \u23a0\u23aa\\n\u23a9  \u2502         \u23ad")
  condset <- ConditionSet(x, (1L / (x ^ 2L)) > 0L, Reals)
  ascii_str <- "                        1      \n{x | x in (-oo, oo) and -- > 0}\n                         2     \n                        x      "
  ucode_str <- "\u23a7  \u2502         \u239b1     \u239e\u23ab\n\u23aax \u2502 x \u220a \u211d \u2227 \u239c\u2500\u2500 > 0\u239f\u23aa\n\u23a8  \u2502         \u239c 2    \u239f\u23ac\n\u23aa  \u2502         \u239dx     \u23a0\u23aa\n\u23a9  \u2502                 \u23ad"
  expect_identical(.pf_out(pretty(condset)), "                        1      \\n{x | x in (-oo, oo) and -- > 0}\\n                         2     \\n                        x      ")
  expect_identical(.pf_out(upretty(condset)), "\u23a7  \u2502         \u239b1     \u239e\u23ab\\n\u23aax \u2502 x \u220a \u211d \u2227 \u239c\u2500\u2500 > 0\u239f\u23aa\\n\u23a8  \u2502         \u239c 2    \u239f\u23ac\\n\u23aa  \u2502         \u239dx     \u23a0\u23aa\\n\u23a9  \u2502                 \u23ad")
})

test_that("pretty test_pretty_Union_issue_10414", {
  for (.n in c("a", "b", "c", "d", "x", "y", "z", "k", "n", "s", "p")) assign(.n, Symbol(.n))
  f <- Function("f"); th <- Symbol("theta"); ph <- Symbol("phi")
  .ppw <- function(e, u, order = NULL) if (inherits(e, "sym")) base::pretty(e, use_unicode = u, order = order) else if (inherits(e, "symmatrix")) base::pretty(e, use_unicode = u) else .pp2_doprint(e, u)
  pretty <- function(e, order = NULL) .ppw(e, FALSE, order)
  upretty <- function(e, order = NULL) .ppw(e, TRUE, order)
  a <- Interval(2L, 3L); b <- Interval(4L, 7L)
  ucode_str <- "[2, 3] \u222a [4, 7]"
