test_that("pretty test_pretty_sequences", {
  for (.n in c("a", "b", "c", "d", "x", "y", "z", "k", "n", "s", "p")) assign(.n, Symbol(.n))
  f <- Function("f"); th <- Symbol("theta"); ph <- Symbol("phi")
  .ppw <- function(e, u, order = NULL) if (inherits(e, "sym")) base::pretty(e, use_unicode = u, order = order) else if (inherits(e, "symmatrix")) base::pretty(e, use_unicode = u) else .pp2_doprint(e, u)
  pretty <- function(e, order = NULL) .ppw(e, FALSE, order)
  upretty <- function(e, order = NULL) .ppw(e, TRUE, order)
  s1 <- SeqFormula(a ^ 2L, list(0L, oo))
  s2 <- SeqPer(list(1L, 2L))
  ascii_str <- "[0, 1, 4, 9, ...]"
  ucode_str <- "[0, 1, 4, 9, \u2026]"
  expect_identical(.pf_out(pretty(s1)), "[0, 1, 4, 9, ...]")
  expect_identical(.pf_out(upretty(s1)), "[0, 1, 4, 9, \u2026]")
  ascii_str <- "[1, 2, 1, 2, ...]"
  ucode_str <- "[1, 2, 1, 2, \u2026]"
  expect_identical(.pf_out(pretty(s2)), "[1, 2, 1, 2, ...]")
  expect_identical(.pf_out(upretty(s2)), "[1, 2, 1, 2, \u2026]")
  s3 <- SeqFormula(a ^ 2L, list(0L, 2L))
  s4 <- SeqPer(list(1L, 2L), list(0L, 2L))
  ascii_str <- "[0, 1, 4]"
  ucode_str <- "[0, 1, 4]"
  expect_identical(.pf_out(pretty(s3)), "[0, 1, 4]")
  expect_identical(.pf_out(upretty(s3)), "[0, 1, 4]")
  ascii_str <- "[1, 2, 1]"
  ucode_str <- "[1, 2, 1]"
  expect_identical(.pf_out(pretty(s4)), "[1, 2, 1]")
  expect_identical(.pf_out(upretty(s4)), "[1, 2, 1]")
  s5 <- SeqFormula(a ^ 2L, list(-oo, 0L))
  s6 <- SeqPer(list(1L, 2L), list(-oo, 0L))
  ascii_str <- "[..., 9, 4, 1, 0]"
  ucode_str <- "[\u2026, 9, 4, 1, 0]"
  expect_identical(.pf_out(pretty(s5)), "[..., 9, 4, 1, 0]")
  expect_identical(.pf_out(upretty(s5)), "[\u2026, 9, 4, 1, 0]")
  ascii_str <- "[..., 2, 1, 2, 1]"
  ucode_str <- "[\u2026, 2, 1, 2, 1]"
  expect_identical(.pf_out(pretty(s6)), "[..., 2, 1, 2, 1]")
  expect_identical(.pf_out(upretty(s6)), "[\u2026, 2, 1, 2, 1]")
  ascii_str <- "[1, 3, 5, 11, ...]"
  ucode_str <- "[1, 3, 5, 11, \u2026]"
  expect_identical(.pf_out(pretty(SeqAdd(s1, s2))), "[1, 3, 5, 11, ...]")
  expect_identical(.pf_out(upretty(SeqAdd(s1, s2))), "[1, 3, 5, 11, \u2026]")
  ascii_str <- "[1, 3, 5]"
  ucode_str <- "[1, 3, 5]"
  expect_identical(.pf_out(pretty(SeqAdd(s3, s4))), "[1, 3, 5]")
  expect_identical(.pf_out(upretty(SeqAdd(s3, s4))), "[1, 3, 5]")
  ascii_str <- "[..., 11, 5, 3, 1]"
  ucode_str <- "[\u2026, 11, 5, 3, 1]"
  expect_identical(.pf_out(pretty(SeqAdd(s5, s6))), "[..., 11, 5, 3, 1]")
  expect_identical(.pf_out(upretty(SeqAdd(s5, s6))), "[\u2026, 11, 5, 3, 1]")
  ascii_str <- "[0, 2, 4, 18, ...]"
  ucode_str <- "[0, 2, 4, 18, \u2026]"
  expect_identical(.pf_out(pretty(SeqMul(s1, s2))), "[0, 2, 4, 18, ...]")
  expect_identical(.pf_out(upretty(SeqMul(s1, s2))), "[0, 2, 4, 18, \u2026]")
  ascii_str <- "[0, 2, 4]"
  ucode_str <- "[0, 2, 4]"
  expect_identical(.pf_out(pretty(SeqMul(s3, s4))), "[0, 2, 4]")
  expect_identical(.pf_out(upretty(SeqMul(s3, s4))), "[0, 2, 4]")
  ascii_str <- "[..., 18, 4, 2, 0]"
  ucode_str <- "[\u2026, 18, 4, 2, 0]"
  expect_identical(.pf_out(pretty(SeqMul(s5, s6))), "[..., 18, 4, 2, 0]")
  expect_identical(.pf_out(upretty(SeqMul(s5, s6))), "[\u2026, 18, 4, 2, 0]")
  s7 <- SeqFormula(a, list(a, 0L, x))
  expect_identical(.pf_out(pretty(s7)), "SeqFormula(a, (a, 0, x))")
  expect_identical(.pf_out(upretty(s7)), "SeqFormula(a, (a, 0, x))")
  b <- Symbol("b")
  s8 <- SeqFormula(b * (a ^ 2L), list(a, 0L, 2L))
  ascii_str <- "[0, b, 4*b]"
  ucode_str <- "[0, b, 4\u22c5b]"
  expect_identical(.pf_out(pretty(s8)), "[0, b, 4*b]")
  expect_identical(.pf_out(upretty(s8)), "[0, b, 4\u22c5b]")
})

test_that("pretty test_pretty_limits", {
  for (.n in c("a", "b", "c", "d", "x", "y", "z", "k", "n", "s", "p")) assign(.n, Symbol(.n))
  f <- Function("f"); th <- Symbol("theta"); ph <- Symbol("phi")
  .ppw <- function(e, u, order = NULL) if (inherits(e, "sym")) base::pretty(e, use_unicode = u, order = order) else if (inherits(e, "symmatrix")) base::pretty(e, use_unicode = u) else .pp2_doprint(e, u)
  pretty <- function(e, order = NULL) .ppw(e, FALSE, order)
  upretty <- function(e, order = NULL) .ppw(e, TRUE, order)
  expr <- Limit(x, x, oo)
  ascii_str <- " lim x\nx->oo "
  ucode_str <- "lim x\nx\u2500\u2192\u221e "
  expect_identical(.pf_out(pretty(expr)), " lim x\\nx->oo ")
  expect_identical(.pf_out(upretty(expr)), "lim x\\nx\u2500\u2192\u221e ")
  expr <- Limit(x ^ 2L, x, 0L)
  ascii_str <- "      2\n lim x \nx->0+  "
  ucode_str <- "      2\n lim x \nx\u2500\u21920\u207a  "
  expect_identical(.pf_out(pretty(expr)), "      2\\n lim x \\nx->0+  ")
  expect_identical(.pf_out(upretty(expr)), "      2\\n lim x \\nx\u2500\u21920\u207a  ")
  expr <- Limit(1L / x, x, 0L)
  ascii_str <- "     1\n lim -\nx->0+x"
  ucode_str <- "     1\n lim \u2500\nx\u2500\u21920\u207ax"
  expect_identical(.pf_out(pretty(expr)), "     1\\n lim -\\nx->0+x")
  expect_identical(.pf_out(upretty(expr)), "     1\\n lim \u2500\\nx\u2500\u21920\u207ax")
  expr <- Limit(sin(x) / x, x, 0L)
  ascii_str <- "     /sin(x)\\\n lim |------|\nx->0+\\  x   /"
  ucode_str <- "     \u239bsin(x)\u239e\n lim \u239c\u2500\u2500\u2500\u2500\u2500\u2500\u239f\nx\u2500\u21920\u207a\u239d  x   \u23a0"
  expect_identical(.pf_out(pretty(expr)), "     /sin(x)\\\\n lim |------|\\nx->0+\\  x   /")
  expect_identical(.pf_out(upretty(expr)), "     \u239bsin(x)\u239e\\n lim \u239c\u2500\u2500\u2500\u2500\u2500\u2500\u239f\\nx\u2500\u21920\u207a\u239d  x   \u23a0")
  expr <- Limit(sin(x) / x, x, 0L, "-")
  ascii_str <- "     /sin(x)\\\n lim |------|\nx->0-\\  x   /"
  ucode_str <- "     \u239bsin(x)\u239e\n lim \u239c\u2500\u2500\u2500\u2500\u2500\u2500\u239f\nx\u2500\u21920\u207b\u239d  x   \u23a0"
  expect_identical(.pf_out(pretty(expr)), "     /sin(x)\\\\n lim |------|\\nx->0-\\  x   /")
  expect_identical(.pf_out(upretty(expr)), "     \u239bsin(x)\u239e\\n lim \u239c\u2500\u2500\u2500\u2500\u2500\u2500\u239f\\nx\u2500\u21920\u207b\u239d  x   \u23a0")
  expr <- Limit(x + sin(x), x, 0L)
  ascii_str <- " lim (x + sin(x))\nx->0+            "
  ucode_str <- " lim (x + sin(x))\nx\u2500\u21920\u207a            "
  expect_identical(.pf_out(pretty(expr)), " lim (x + sin(x))\\nx->0+            ")
  expect_identical(.pf_out(upretty(expr)), " lim (x + sin(x))\\nx\u2500\u21920\u207a            ")
  expr <- Limit(x, x, 0L) ^ 2L
  ascii_str <- "        2\n/ lim x\\ \n\\x->0+ / "
  ucode_str <- "        2\n\u239b lim x\u239e \n\u239dx\u2500\u21920\u207a \u23a0 "
  expect_identical(.pf_out(pretty(expr)), "        2\\n/ lim x\\ \\n\\x->0+ / ")
  expect_identical(.pf_out(upretty(expr)), "        2\\n\u239b lim x\u239e \\n\u239dx\u2500\u21920\u207a \u23a0 ")
  expr <- Limit(x * Limit(y / 2L, y, 0L), x, 0L)
  ascii_str <- "     /       /y\\\\\n lim |x* lim |-||\nx->0+\\  y->0+\\2//"
  ucode_str <- "     \u239b       \u239by\u239e\u239e\n lim \u239cx\u22c5 lim \u239c\u2500\u239f\u239f\nx\u2500\u21920\u207a\u239d  y\u2500\u21920\u207a\u239d2\u23a0\u23a0"
  expect_identical(.pf_out(pretty(expr)), "     /       /y\\\\\\n lim |x* lim |-||\\nx->0+\\  y->0+\\2//")
  expect_identical(.pf_out(upretty(expr)), "     \u239b       \u239by\u239e\u239e\\n lim \u239cx\u22c5 lim \u239c\u2500\u239f\u239f\\nx\u2500\u21920\u207a\u239d  y\u2500\u21920\u207a\u239d2\u23a0\u23a0")
  expr <- 2L * Limit(x * Limit(y / 2L, y, 0L), x, 0L)
  ascii_str <- "       /       /y\\\\\n2* lim |x* lim |-||\n  x->0+\\  y->0+\\2//"
  ucode_str <- "       \u239b       \u239by\u239e\u239e\n2\u22c5 lim \u239cx\u22c5 lim \u239c\u2500\u239f\u239f\n  x\u2500\u21920\u207a\u239d  y\u2500\u21920\u207a\u239d2\u23a0\u23a0"
  expect_identical(.pf_out(pretty(expr)), "       /       /y\\\\\\n2* lim |x* lim |-||\\n  x->0+\\  y->0+\\2//")
  expect_identical(.pf_out(upretty(expr)), "       \u239b       \u239by\u239e\u239e\\n2\u22c5 lim \u239cx\u22c5 lim \u239c\u2500\u239f\u239f\\n  x\u2500\u21920\u207a\u239d  y\u2500\u21920\u207a\u239d2\u23a0\u23a0")
  expr <- Limit(sin(x), x, 0L, dir = "+-")
  ascii_str <- "lim sin(x)\nx->0      "
  ucode_str <- "lim sin(x)\nx\u2500\u21920      "
  expect_identical(.pf_out(pretty(expr)), "lim sin(x)\\nx->0      ")
  expect_identical(.pf_out(upretty(expr)), "lim sin(x)\\nx\u2500\u21920      ")
})

test_that("pretty test_pretty_ComplexRootOf", {
  for (.n in c("a", "b", "c", "d", "x", "y", "z", "k", "n", "s", "p")) assign(.n, Symbol(.n))
  f <- Function("f"); th <- Symbol("theta"); ph <- Symbol("phi")
  .ppw <- function(e, u, order = NULL) if (inherits(e, "sym")) base::pretty(e, use_unicode = u, order = order) else if (inherits(e, "symmatrix")) base::pretty(e, use_unicode = u) else .pp2_doprint(e, u)
  pretty <- function(e, order = NULL) .ppw(e, FALSE, order)
  upretty <- function(e, order = NULL) .ppw(e, TRUE, order)
  expr <- rootof(((x ^ 5L) + (11L * x)) - 2L, 0L)
  ascii_str <- "       / 5              \\\nCRootOf\\x  + 11*x - 2, 0/"
