test_that("pretty test_issue_6359", {
  for (.n in c("a", "b", "c", "d", "x", "y", "z", "k", "n", "s", "p")) assign(.n, Symbol(.n))
  f <- Function("f"); th <- Symbol("theta"); ph <- Symbol("phi")
  .ppw <- function(e, u, order = NULL) if (inherits(e, "sym")) base::pretty(e, use_unicode = u, order = order) else if (inherits(e, "symmatrix")) base::pretty(e, use_unicode = u) else .pp2_doprint(e, u)
  pretty <- function(e, order = NULL) .ppw(e, FALSE, order)
  upretty <- function(e, order = NULL) .ppw(e, TRUE, order)
  expect_identical(.pf_out(pretty(Integral(x ^ 2L, x) ^ 2L)), "          2\\n/  /     \\ \\n| |      | \\n| |  2   | \\n| | x  dx| \\n| |      | \\n\\/       / ")
  expect_identical(.pf_out(upretty(Integral(x ^ 2L, x) ^ 2L)), "         2\\n\u239b\u2320      \u239e \\n\u239c\u23ae  2   \u239f \\n\u239c\u23ae x  dx\u239f \\n\u239d\u2321      \u23a0 ")
  expect_identical(.pf_out(pretty(Sum(x ^ 2L, list(x, 0L, 1L)) ^ 2L)), "          2\\n/ 1      \\ \\n|___     | \\n|\\  `    | \\n| \\     2| \\n| /    x | \\n|/__,    | \\n\\x = 0   / ")
  expect_identical(.pf_out(upretty(Sum(x ^ 2L, list(x, 0L, 1L)) ^ 2L)), "          2\\n\u239b  1     \u239e \\n\u239c ___    \u239f \\n\u239c \u2572      \u239f \\n\u239c  \u2572    2\u239f \\n\u239c  \u2571   x \u239f \\n\u239c \u2571      \u239f \\n\u239c \u203e\u203e\u203e    \u239f \\n\u239dx = 0   \u23a0 ")
  expect_identical(.pf_out(pretty(Product(x ^ 2L, list(x, 1L, 2L)) ^ 2L)), "           2\\n/  2      \\ \\n|______   | \\n| |  |   2| \\n| |  |  x | \\n| |  |    | \\n\\x = 1    / ")
  expect_identical(.pf_out(upretty(Product(x ^ 2L, list(x, 1L, 2L)) ^ 2L)), "           2\\n\u239b  2      \u239e \\n\u239c\u2500\u252c\u2500\u2500\u252c\u2500   \u239f \\n\u239c \u2502  \u2502   2\u239f \\n\u239c \u2502  \u2502  x \u239f \\n\u239c \u2502  \u2502    \u239f \\n\u239dx = 1    \u23a0 ")
  f <- Function("f")
  expect_identical(.pf_out(pretty(Derivative(f(x), x) ^ 2L)), "          2\\n/d       \\ \\n|--(f(x))| \\n\\dx      / ")
  expect_identical(.pf_out(upretty(Derivative(f(x), x) ^ 2L)), "          2\\n\u239bd       \u239e \\n\u239c\u2500\u2500(f(x))\u239f \\n\u239ddx      \u23a0 ")
})

