  expect_identical(.pf_out(upretty(Union(a, Complement(b, c)))), "(2, 3) \u222a ([1, 2] \\ {x})")
  ucode_str2 <- "{x} \u2229 {y} \u2229 ({z} \\ [1, 2])"
  d <- FiniteSet(x); e <- FiniteSet(y); f <- FiniteSet(z); g <- Interval(1L, 2L)
  expect_identical(.pf_out(upretty(Intersection(d, e, Complement(f, g)))), "{x} \u2229 {y} \u2229 ({z} \\ [1, 2])")
})

