test_that("pretty test_MatrixSymbol_printing", {
  for (.n in c("a", "b", "c", "d", "x", "y", "z", "k", "n", "s", "p")) assign(.n, Symbol(.n))
  f <- Function("f"); th <- Symbol("theta"); ph <- Symbol("phi")
  .ppw <- function(e, u, order = NULL) if (inherits(e, "sym")) base::pretty(e, use_unicode = u, order = order) else if (inherits(e, "symmatrix")) base::pretty(e, use_unicode = u) else .pp2_doprint(e, u)
  pretty <- function(e, order = NULL) .ppw(e, FALSE, order)
  upretty <- function(e, order = NULL) .ppw(e, TRUE, order)
  A <- MatrixSymbol("A", 3L, 3L)
  B <- MatrixSymbol("B", 3L, 3L)
  C <- MatrixSymbol("C", 3L, 3L)
  expect_identical(.pf_out(pretty(((-A) * B) * C)), "-A*B*C")
  expect_identical(.pf_out(pretty(A - B)), "-B + A")
  expect_identical(.pf_out(pretty((((A * B) * C) - (A * B)) - (B * C))), "-A*B -B*C + A*B*C")
  x <- MatrixSymbol("x", n, n)
  y <- MatrixSymbol("y*", n, n)
  expect_identical(.pf_out(pretty(x + y)), "x + y*")
  ascii_str <- "     2     \n-2*y*  -a*x"
  expect_identical(.pf_out(pretty(((-a) * x) + (((-2L) * y) * y))), "     2     \\n-2*y*  -a*x")
})

