  expect_identical(.pf_out(upretty(ConditionSet(x, Eq((-x) + exp(x), 0L), Complexes))), "\u23a7  \u2502         \u239b      x    \u239e\u23ab\\n\u23a8x \u2502 x \u220a \u2102 \u2227 \u239d-x + \u212f  = 0\u23a0\u23ac\\n\u23a9  \u2502                      \u23ad")
  expect_identical(.pf_out(upretty(ConditionSet(x, Contains(n / 2L, Interval(0L, oo)), FiniteSet((-n) / 2L, n / 2L)))), "\u23a7  \u2502     \u23a7-n   n\u23ab   \u239bn         \u239e\u23ab\\n\u23a8x \u2502 x \u220a \u23a8\u2500\u2500\u2500, \u2500\u23ac \u2227 \u239c\u2500 \u2208 [0, \u221e)\u239f\u23ac\\n\u23a9  \u2502     \u23a9 2   2\u23ad   \u239d2         \u23a0\u23ad")
  expect_identical(.pf_out(upretty(ConditionSet(x, Eq(Piecewise(list(1L, x >= 3L), list((x / 2L) - (1L / 2L), x >= 2L), list(1L / 2L, x >= 1L), list(x / 2L, TRUE)) - (1L / 2L), 0L), Interval(0L, 3L)))), "\u23a7  \u2502              \u239b\u239b\u23a7   1     for x \u2265 3\u239e          \u239e\u23ab\\n\u23aa  \u2502              \u239c\u239c\u23aa                  \u239f          \u239f\u23aa\\n\u23aa  \u2502              \u239c\u239c\u23aax                 \u239f          \u239f\u23aa\\n\u23aa  \u2502              \u239c\u239c\u23aa\u2500 - 0.5  for x \u2265 2\u239f          \u239f\u23aa\\n\u23aa  \u2502              \u239c\u239c\u23aa2                 \u239f          \u239f\u23aa\\n\u23a8x \u2502 x \u220a [0, 3] \u2227 \u239c\u239c\u23a8                  \u239f - 0.5 = 0\u239f\u23ac\\n\u23aa  \u2502              \u239c\u239c\u23aa  0.5    for x \u2265 1\u239f          \u239f\u23aa\\n\u23aa  \u2502              \u239c\u239c\u23aa                  \u239f          \u239f\u23aa\\n\u23aa  \u2502              \u239c\u239c\u23aa   x              \u239f          \u239f\u23aa\\n\u23aa  \u2502              \u239c\u239c\u23aa   \u2500     otherwise\u239f          \u239f\u23aa\\n\u23a9  \u2502              \u239d\u239d\u23a9   2              \u23a0          \u23a0\u23ad")
})

